INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C1','sci',6,2,'u2',1,'불씨가 살아나는 병 찾기 — 소금·탄산 칼슘·제빵 소다·산소계 표백제가 각각 든 유리병 하나를 골라 가루가 잠길 만큼 따뜻한 물을 넣고 뚜껑을 닫아 흔든 뒤, 뚜껑을 열고 작은 불씨만 남은 향불을 넣어 봄 · 소금·탄산 칼슘·제빵 소다 병에서는 불씨가 꺼지고 산소계 표백제 병에서만 불씨가 커짐 · 네 병 모두 같은 따뜻한 물을 넣었으므로 물이 불씨를 살린 것이 아님 · 꺼져 가는 불씨를 살릴 수 있는 물질이 있음(산소계 표백제에 있는 산소가 살렸을 것 같다 — 추측까지) · 면장갑, 점화기는 사람 없는 쪽으로, 환기, 맛보지 않기, 향불 끄기, 정해진 곳에 버리기 · 모둠 역할 책임',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C2','sci',6,2,'u2',2,'서로 다른 물질을 섞을 때의 변화 — 고무풍선 하나에 밀가루, 다른 하나에 탄산수소 나트륨을 두 숟가락씩 넣고 식초가 든 삼각 플라스크에 씌운 뒤 두 고무풍선을 동시에 세워 넣음(다른 것은 가루뿐) · 밀가루+식초: 고무풍선 변화 없음, 밀가루가 가라앉음 → 성질이 변하지 않음 · 탄산수소 나트륨+식초: 보글거리며 기포(기체)가 생기고 고무풍선이 부풀어 오름 → 성질이 변함 · 서로 다른 물질을 섞으면 성질이 변하기도 하고 변하지 않기도 함 · 분말 깔때기, 가루마다 다른 약숟가락, 정해진 양, 맛보지 않기, 피부에 닿지 않게, 환기',ARRAY['[6과14-01] 서로 다른 물질을 섞었을 때 물질의 성질이 달라지는 변화와 달라지지 않는 변화 관찰·비교(문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C3','sci',6,2,'u2',2,'우리 주변의 섞임과 녹은 물질의 성질 — 우유에 식초를 섞으면 덩어리가 생기고, 손난로 속 철 가루가 공기 중의 산소와 섞이면 색깔이 변하고 열이 발생함(성질이 변함) · 물에 설탕·꿀을 섞으면 단맛이 그대로 남(성질이 변하지 않음) · 소금과 설탕을 섞어도 짠맛·단맛이 그대로 · 설탕·소금이 물에 녹아 보이지 않아도 단맛·짠맛 같은 성질을 그대로 지니며 물을 증발시키면 다시 얻을 수 있음',ARRAY['[6과14-01] 서로 다른 물질을 섞었을 때 물질의 성질이 달라지는 변화와 달라지지 않는 변화 관찰·비교(문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C4','sci',6,2,'u2',3,'물질이 탈 때 나타나는 현상 — 양초와 알코올에 차례로 불을 붙여 불을 붙이기 전과 비교하며 불꽃의 모양·밝기·색깔·따뜻한 정도를 관찰 · 두 불꽃 모두 위아래로 길쭉하고 주변이 밝아지며 가까울수록 따뜻함, 색깔만 다름(양초 노란색·붉은색 등, 알코올 푸른색·붉은색 등) · 시간이 지나면 양초·알코올의 양이 줄어듦 · 물질이 탈 때에는 공통적으로 빛과 열이 발생함 · 비상구·소화기 위치 확인, 면장갑, 불꽃 근처에 탈 수 있는 물질 두지 않기, 환기, 불꽃 위에서 들여다보지 않기, 촛농 만지지 않기, 알코올램프는 뚜껑을 덮어 끔',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C5','sci',6,2,'u2',3,'물질이 탈 때 나오는 빛과 열의 이용 — 양초·알코올·나무 등의 탈 물질이 탈 때 나오는 빛으로 어두운 곳을 밝히고 열로 주변을 따뜻하게 하거나 음식을 조리함 · 주로 빛: 강물 위의 유등, 막대 폭죽의 불꽃 · 주로 열: 벽난로의 장작불, 가스레인지의 불꽃',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C6','sci',6,2,'u2',4,'연소와 연소의 조건 — 물질이 산소와 만나 빛과 열을 내면서 타는 현상을 연소라고 함 · 연소가 일어나려면 탈 물질, 산소, 발화점 이상의 온도가 모두 필요하고, 하나라도 없으면 연소는 일어나지 않음 · 로켓을 발사하려면 연소에 필요한 조건을 모두 만족해야 함',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C7','sci',6,2,'u2',4,'연소와 산소 — 양초 두 개에 불을 붙이고 묽은 과산화 수소수에 아이오딘화 칼륨을 넣은 비커(산소가 발생)를 한쪽에만 함께 두고 같은 크기의 아크릴 통 두 개로 동시에 덮음 · 양초만 덮은 쪽이 먼저 꺼지고 비커와 함께 덮은 쪽이 더 오래 탐 → 산소는 물질이 타는 것을 도움 · 촛불이 꺼진 것은 산소가 모두 없어져서가 아니라 연소할 수 있을 만큼 산소가 충분하지 않아서임 · 공기 중 산소가 많을수록 연소가 활발 — 부채질, 송풍기, 화로의 공기 조절 장치',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C8','sci',6,2,'u2',4,'발화점과 온도 — 삼발이 위 철판 가운데로부터 같은 거리에 성냥의 머리 부분과 나무 부분을 놓고 가운데를 가열하면 머리 부분에 불이 먼저 붙음(더 가열하면 나무 부분도 붙음) · 어떤 물질이 타기 시작하는 온도를 발화점이라 하고 물질에 따라 다름 · 물질의 온도가 발화점 이상이 되어야 타며, 불을 직접 붙이지 않아도 마른나무를 마찰하거나 볼록 렌즈로 햇빛을 모아 온도를 높이면 탐 · 가열한 철판은 완전히 식을 때까지 만지지 않기, 머리 부분에 불이 붙을 때 얼굴을 가까이하지 않기',ARRAY['[6과14-02] 물질이 탈 때 나타나는 공통적인 현상을 관찰하고 연소의 조건 찾기(문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C9','sci',6,2,'u2',5,'연소 후 생성되는 물질 — 푸른색 염화 코발트 종이는 물에 닿으면 붉은색으로 변하고, 무색투명한 석회수는 이산화 탄소를 만나면 뿌옇게 흐려짐 · 아크릴 통 안쪽 벽면에 셀로판테이프로 붙인 푸른색 염화 코발트 종이가 촛불이 꺼진 뒤 붉게 변함(테이프 붙인 자리는 푸른색 그대로) → 물이 생김 · 석회수 유리병을 촛불과 함께 덮고, 꺼지면 뚜껑을 닫아 흔드니 뿌옇게 흐려짐 → 이산화 탄소가 생김 · 핀셋·실험용 장갑, 석회수 피부에 닿지 않게(닿으면 흐르는 물로), 뜨거운 통 조심, 환기',ARRAY['[6과14-03] 연소 전과 후의 물질을 비교하여 연소 과정에서 물질의 성질이 달라짐을 설명']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C10','sci',6,2,'u2',5,'연소 전과 후의 비교 — 양초가 연소하면 양이 줄어들고 물과 이산화 탄소가 생김 · 연소 전의 물질(양초)과 전혀 다른 물질이 생기므로 연소 과정에서 물질의 성질이 달라짐 · 양초가 많이 연소할수록 생성되는 물질의 양도 많아짐 · 난로의 굴뚝은 연기·열이 빠져나가게 함',ARRAY['[6과14-03] 연소 전과 후의 물질을 비교하여 연소 과정에서 물질의 성질이 달라짐을 설명']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C11','sci',6,2,'u2',6,'연소 생성물로 인한 생태계 피해 — 교통수단 운행, 가정의 가스 불 요리, 화력 발전소 전기 생산, 쓰레기 소각장 폐기물 처리 등 생활 곳곳에서 연소가 일어남 · 연소 생성물인 이산화 탄소가 대기 중에 많아지면 기후변화와 생물의 서식 환경 변화로 생태계에 피해를 줌 · 사례: 침엽수림(구상나무)이 말라 죽음, 바다 산성화로 조개류 껍데기가 얇아지거나 깨짐, 산호초가 하얗게 변함(백화 현상), 동식물의 감소·멸종 — 피해가 나타나는 곳은 달라도 모두 이산화 탄소 배출량 증가 때문 · 배출량이 계속 늘면 피해가 더 커짐 · 피해를 줄이려면 배출량을 줄여야 함 · 조사: 믿을 만한 자료, 출처, 불필요한 검색 하지 않기, 공유와 긍정적 피드백, 의견 존중',ARRAY['[6과14-04] 연소 과정에서 생성되는 물질로 인한 생태계의 피해 사례를 수집·분석하여 해결책을 제안·공유']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C12','sci',6,2,'u2',7,'이산화 탄소를 줄이는 실천 방법 홍보 자료 — 조사(재생 에너지, 친환경 기술, 물 절약, 실내 적정 온도, 재활용품 분리배출, 일회용품 줄이기 등) → 모둠별 제안 활동과 구체적인 실천 방법 정하기(자동차 적게 이용하기: 대중교통·자전거·걷기 / 물 아껴 쓰기: 양치 컵·씻는 시간 줄이기 / 전기 절약: 전등 끄기·플러그 뽑기) → 형태 정하기(카드 뉴스·표어, 도화지도 가능) → 문구 정하기 → 만들기 → 공유 플랫폼·사회 관계망 서비스에 공유 → 잘한 점을 댓글로 · 생활 속에서 실천 가능한 방법, 여러 사람의 꾸준한 노력 · 그대로 쓰지 않고 더하거나 빼는 변형으로 자신만의 생각, 창작물 허락·출처, 바르고 고운 말, 공정한 평가 · 꾸밈보다 내용',ARRAY['[6과14-04] 연소 과정에서 생성되는 물질로 인한 생태계의 피해 사례를 수집·분석하여 해결책을 제안·공유']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u2-C13','sci',6,2,'u2',8,'이산화 탄소의 포집과 재활용 — 배출량을 줄이는 노력과 함께 이미 배출된 이산화 탄소를 생활에 필요한 자원으로 바꾸려는 노력을 함 · 배기가스 발생 → 이산화 탄소 흡수 → 배기가스 중 이산화 탄소만 포집 → 다양한 산업 분야에 활용 · 가스발전 과정의 포집 기술, 화력 발전소의 분리·재활용 · 쓰임: 농작물 재배(생장 속도·품질), 드라이아이스(신선식품·아이스크림을 차갑게), 소화기 제조, 의약품 제조 · 재활용 기술이 있다고 마음껏 배출해도 되는 것은 아님 · 안전하고 지속가능한 사회',ARRAY['[6과14-04] 연소 과정에서 생성되는 물질로 인한 생태계의 피해 사례를 수집·분석하여 해결책을 제안·공유']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X01','sci',6,'u2',ARRAY['SC6-2-u2-C1']::text[],'불씨가 살아난 까닭을 네 병에 모두 넣은 따뜻한 물·병의 크기·흔든 것 등으로 돌리거나, 네 물질이 모두 불씨를 살린다고 여긴다','네 병의 같은 점과 다른 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X02','sci',6,'u2',ARRAY['SC6-2-u2-C1']::text[],'불씨 살리기 활동의 순서와 안전을 잘못 안다(큰 불꽃일 때 넣기, 맛보기, 점화기를 사람 쪽으로, 향불을 끄지 않기 등)','작은 불씨 · 면장갑 · 맛보지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X03','sci',6,'u2',ARRAY['SC6-2-u2-C2','SC6-2-u2-C3']::text[],'서로 다른 물질을 섞으면 성질이 항상 변하지 않는다고, 또는 항상 변한다고 여긴다','변하기도 하고 변하지 않기도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X04','sci',6,'u2',ARRAY['SC6-2-u2-C2']::text[],'밀가루+식초와 탄산수소 나트륨+식초의 결과를 뒤바꾸거나, 고무풍선과 삼각 플라스크 안의 변화를 헷갈린다','부푼 쪽은 탄산수소 나트륨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X05','sci',6,'u2',ARRAY['SC6-2-u2-C2']::text[],'섞기 실험에서 같게 할 조건·다르게 할 조건과 실험 방법·안전을 잘못 안다(따로따로 세우기, 식초 양 다르게, 가루를 많이 넣기, 맛보기 등)','가루만 다르게 · 동시에 세우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X06','sci',6,'u2',ARRAY['SC6-2-u2-C3']::text[],'설탕이나 소금이 물에 녹아 눈에 보이지 않으면 물질의 성질이 변한 것이라고 여긴다','단맛·짠맛은 그대로예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X07','sci',6,'u2',ARRAY['SC6-2-u2-C3']::text[],'우리 주변에서 섞을 때 성질이 변하는 예(우유와 식초, 손난로)와 변하지 않는 예(설탕물, 꿀물)를 바꾸어 가른다','덩어리·열 / 단맛 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X08','sci',6,'u2',ARRAY['SC6-2-u2-C4']::text[],'물질이 탈 때의 공통적인 현상을 빛과 열이 아닌 것(차가워짐, 어두워짐, 양이 늘어남 등)으로 여긴다','밝아지고 따뜻해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X09','sci',6,'u2',ARRAY['SC6-2-u2-C4']::text[],'불꽃의 색깔이 다르면 공통적인 현상을 말할 수 없다고 여기거나, 두 불꽃의 색깔이 같다고 여긴다','색깔만 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X10','sci',6,'u2',ARRAY['SC6-2-u2-C4','SC6-2-u2-C10']::text[],'물질이 타는 동안 양초나 알코올의 양이 그대로이거나 늘어난다고 여긴다','시간이 지나면 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X11','sci',6,'u2',ARRAY['SC6-2-u2-C5']::text[],'물질이 탈 때 나오는 빛을 주로 쓰는 예와 열을 주로 쓰는 예를 바꾸어 가른다','밝히기 / 데우기·조리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X12','sci',6,'u2',ARRAY['SC6-2-u2-C4','SC6-2-u2-C8']::text[],'불을 다루는 실험의 안전을 잘못 안다(불꽃 위에서 들여다보기, 탈 물질을 가까이 두기, 촛농·뜨거운 기구 만지기, 입으로 불어 끄기 등)','비상구·소화기 · 면장갑 · 가까이하지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X13','sci',6,'u2',ARRAY['SC6-2-u2-C6']::text[],'연소의 뜻을 잘못 안다(물질이 물과 만나는 현상, 섞어서 기체가 생기는 현상 등으로)','산소와 만나 빛과 열을 내며 타요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X14','sci',6,'u2',ARRAY['SC6-2-u2-C6']::text[],'연소의 조건을 잘못 안다(조건 하나만 있어도 탄다, 이산화 탄소나 발화점 미만의 온도가 필요하다 등)','탈 물질 · 산소 · 발화점 이상의 온도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X15','sci',6,'u2',ARRAY['SC6-2-u2-C7']::text[],'산소 실험의 결과를 온도·양초 크기·통의 크기 차이로 돌리거나, 산소가 타는 것을 돕는다는 것과 잇지 못한다','다른 것은 산소가 생기는 비커뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X16','sci',6,'u2',ARRAY['SC6-2-u2-C7']::text[],'아크릴 통 안의 산소가 모두 없어졌기 때문에 촛불이 꺼졌다고 여긴다','충분하지 않으면 꺼져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X17','sci',6,'u2',ARRAY['SC6-2-u2-C8']::text[],'발화점이 모든 물질에서 같다고 여기거나, 성냥의 머리 부분과 나무 부분에 불이 함께 붙는다고 여긴다','머리 부분이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X18','sci',6,'u2',ARRAY['SC6-2-u2-C8']::text[],'물질은 불을 직접 붙여야만 탄다고 여겨 온도를 높이는 방법(마찰, 햇빛 모으기, 가열)으로도 탈 수 있음을 놓친다','발화점 이상으로 온도를 높이면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X19','sci',6,'u2',ARRAY['SC6-2-u2-C7','SC6-2-u2-C8']::text[],'연소의 조건 실험에서 같게 할 조건(같은 크기의 통, 동시에 덮기, 같은 거리)을 놓치거나 각 실험이 알려 주는 조건을 바꾸어 안다','한 가지만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X20','sci',6,'u2',ARRAY['SC6-2-u2-C9']::text[],'푸른색 염화 코발트 종이와 석회수가 알려 주는 것을 뒤바꾸거나 색 변화를 거꾸로 안다','종이는 물 · 석회수는 이산화 탄소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X21','sci',6,'u2',ARRAY['SC6-2-u2-C9']::text[],'양초가 연소하면 산소가 생성되거나, 연소 전과 같은 양초가 그대로 남는다고 여긴다','물과 이산화 탄소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X22','sci',6,'u2',ARRAY['SC6-2-u2-C10']::text[],'양초가 연소해 줄어든 것을 성질은 그대로인 채 크기만 작아진 것으로 여겨 연소 과정에서 물질의 성질이 달라짐을 놓친다','전혀 다른 물질이 생겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X23','sci',6,'u2',ARRAY['SC6-2-u2-C9']::text[],'연소 후 생성 물질 실험의 방법·안전을 잘못 안다(테이프로 종이를 모두 덮기, 맨손으로 집기, 흔들지 않고 판단하기, 석회수가 닿아도 그대로 두기 등)','핀셋·장갑 · 뚜껑 닫고 흔들기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X24','sci',6,'u2',ARRAY['SC6-2-u2-C11']::text[],'생태계 피해의 원인을 산소가 줄어든 것이나 사례마다 다른 원인으로 여기거나, 물을 피해를 주는 연소 생성물로 여긴다','모두 이산화 탄소 배출량 증가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X25','sci',6,'u2',ARRAY['SC6-2-u2-C11']::text[],'교통수단·발전소·쓰레기 소각장처럼 생활 속에서 연소가 일어나는 곳에서는 연소 생성물이 생기지 않는다고 여기거나, 배출량이 늘어도 피해가 그대로라고 여긴다','생활 곳곳에서 연소가 일어나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X26','sci',6,'u2',ARRAY['SC6-2-u2-C11','SC6-2-u2-C12']::text[],'조사하고 나누는 태도를 잘못 안다(믿을 만한지 확인하지 않기, 출처 빼기, 남의 자료 베끼기, 불필요한 검색, 비난하는 댓글 등)','확인 · 출처 · 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X27','sci',6,'u2',ARRAY['SC6-2-u2-C12']::text[],'이산화 탄소를 줄이는 제안을 실천하기 어려운 방법이나 꾸밈 위주로 정하거나, 한 사람·어른만 노력하면 된다고 여긴다','생활 속에서 꾸준히 · 여러 사람이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u2-X28','sci',6,'u2',ARRAY['SC6-2-u2-C13']::text[],'이산화 탄소를 재활용하는 기술이 있으니 마음껏 배출해도 된다고 여기거나, 포집한 이산화 탄소의 쓰임을 잘못 안다','줄이는 노력과 바꾸는 노력은 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#1','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'mc','auto','네 병 가운데 향불의 불씨가 커진 병은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"mc","stem":"네 병 가운데 향불의 불씨가 커진 병은 어느 것인가요?","options":[{"t":"산소계 표백제가 든 병","correct":true},{"t":"소금이 든 병","mis":"SC6-2-u2-X01"},{"t":"탄산 칼슘이 든 병","mis":"SC6-2-u2-X01"},{"t":"제빵 소다가 든 병","mis":"SC6-2-u2-X01"}],"explanation":["결과 표를 읽어요.","꺼진 병이 셋이에요.","커진 병은 산소계 표백제예요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#2','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'mc','auto','고른 유리병에는 무엇을 넣나요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"mc","stem":"고른 유리병에는 무엇을 넣나요?","options":[{"t":"가루가 잠길 정도의 따뜻한 물","correct":true},{"t":"얼음이 뜰 만큼 차가운 물","mis":"SC6-2-u2-X02"},{"t":"병에 가득 찰 만큼의 기름","mis":"SC6-2-u2-X02"},{"t":"아무것도 넣지 않는다","mis":"SC6-2-u2-X02"}],"explanation":["순서 ②를 읽어요.","가루가 잠길 정도예요.","따뜻한 물이에요."],"asset":{"type":"passage","lines":["① 네 가지 가루가 든 유리병 가운데 하나를 고른다.","② 가루가 잠길 만큼 따뜻한 물을 넣는다.","③ 뚜껑을 닫고 흔든 뒤 잠시 둔다.","④ 뚜껑을 열고 작은 불씨만 남은 향을 병 안에 넣는다.","⑤ 불씨를 살린 것이 무엇인지 이야기한다."],"title":"불씨가 살아나는 병 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#3','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'ox','auto','소금이 든 병에 향불을 넣으면 불씨가 커져요.',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"ox","stem":"소금이 든 병에 향불을 넣으면 불씨가 커져요.","answer":"X","reason_options":[{"t":"소금 병에서는 향불의 불씨가 꺼졌기 때문에","correct":true},{"t":"네 병은 모두 불씨를 살리기 때문에","mis":"SC6-2-u2-X01"}],"mis":"SC6-2-u2-X01","explanation":["소금 병 결과를 떠올려요.","불씨가 꺼졌어요.","커지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#4','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'sa','auto','향에 불을 붙일 때 쓰는 도구는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"sa","stem":"향에 불을 붙일 때 쓰는 도구는 무엇인가요? 세 글자로 쓰세요.","answer":["점화기"],"explanation":["불을 붙이는 도구예요.","□화기예요.","점화기예요."],"mis":"SC6-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#5','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'mc','auto','향은 어떤 상태일 때 병 안에 넣나요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"mc","stem":"향은 어떤 상태일 때 병 안에 넣나요?","options":[{"t":"향 끝에 작은 불씨만 남아 있을 때","correct":true},{"t":"큰 불꽃이 활활 타오를 때","mis":"SC6-2-u2-X02"},{"t":"불을 붙이지 않았을 때","mis":"SC6-2-u2-X02"},{"t":"향불을 완전히 끈 뒤","mis":"SC6-2-u2-X02"}],"explanation":["꺼져 가는 불씨를 살리는 활동이에요.","불꽃이 크면 비교가 안 돼요.","작은 불씨일 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#6','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'match','auto','준비물과 활동에서 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"match","stem":"준비물과 활동에서 하는 일을 알맞게 이으세요.","pairs":[{"l":"유리병","r":"가루 물질이 담겨 있다"},{"l":"따뜻한 물","r":"가루가 잠길 정도로 넣는다"},{"l":"향과 점화기","r":"불씨를 병 안에 넣어 본다"},{"l":"면장갑","r":"불을 다룰 때 화상을 막는다"}],"mis":"SC6-2-u2-X02","explanation":["담는 것은 병이에요.","넣는 것은 물이에요.","불과 보호를 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#7','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'ox','auto','어떤 가루인지 알아보려고 조금 맛을 보아도 괜찮아요.',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"ox","stem":"어떤 가루인지 알아보려고 조금 맛을 보아도 괜찮아요.","answer":"X","reason_options":[{"t":"실험에 쓰는 물질은 맛보지 않아야 하기 때문에","correct":true},{"t":"맛을 보아야 결과를 정확히 알 수 있기 때문에","mis":"SC6-2-u2-X02"}],"mis":"SC6-2-u2-X02","explanation":["실험 물질이에요.","먹으면 위험해요.","맛보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#8','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'error','auto','활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"error","stem":"활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「점화기는 친구가 있는 쪽으로 향해도 돼.」","correct":true,"mis_target":"SC6-2-u2-X02"},{"t":"도윤 — 「불을 다룰 때는 면장갑을 껴.」","mis":"SC6-2-u2-X02"},{"t":"하린 — 「다 쓴 향불은 꼭 끄자.」","mis":"SC6-2-u2-X02"}],"explanation":["점화기 방향을 떠올려요.","사람 쪽은 위험해요.","지안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#9','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'blank','auto','「유리병에 따뜻한 물을 넣고 (    ) 흔든 뒤 잠시 둡니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"blank","stem":"「유리병에 따뜻한 물을 넣고 (    ) 흔든 뒤 잠시 둡니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"뚜껑을 닫고","correct":true},{"t":"향불을 넣고","mis":"SC6-2-u2-X02"},{"t":"물을 버리고","mis":"SC6-2-u2-X02"},{"t":"병을 깨뜨리고","mis":"SC6-2-u2-X02"}],"explanation":["순서 ③이에요.","흔들려면 막아야 해요.","뚜껑을 닫아요."],"asset":{"type":"passage","lines":["① 네 가지 가루가 든 유리병 가운데 하나를 고른다.","② 가루가 잠길 만큼 따뜻한 물을 넣는다.","③ 뚜껑을 닫고 흔든 뒤 잠시 둔다.","④ 뚜껑을 열고 작은 불씨만 남은 향을 병 안에 넣는다.","⑤ 불씨를 살린 것이 무엇인지 이야기한다."],"title":"불씨가 살아나는 병 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_basic#10','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',3,'mc','auto','네 병에 모두 같은 따뜻한 물을 넣었는데 한 병에서만 불씨가 커졌어요. 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"mc","stem":"네 병에 모두 같은 따뜻한 물을 넣었는데 한 병에서만 불씨가 커졌어요. 알 수 있는 것은 어느 것인가요?","options":[{"t":"따뜻한 물이 아니라 병 속 물질에 따라 결과가 달랐다","correct":true},{"t":"따뜻한 물이 불씨를 살렸다","mis":"SC6-2-u2-X01"},{"t":"네 물질 모두 불씨를 살린다","mis":"SC6-2-u2-X01"},{"t":"병을 흔드는 횟수가 결과를 정했다","mis":"SC6-2-u2-X01"}],"explanation":["같게 한 것과 다른 것을 가려요.","물은 네 병이 같아요.","다른 것은 물질뿐이에요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#1','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',2,'sa','auto','꺼져 가는 향불의 불씨를 크게 만든 가루는 무엇인가요? (□□□ 표백제)','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"sa","stem":"꺼져 가는 향불의 불씨를 크게 만든 가루는 무엇인가요? (□□□ 표백제)","answer":["산소계","산소계 표백제"],"explanation":["불씨가 커진 병이에요.","세 글자예요.","산소계 표백제예요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"},"mis":"SC6-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#2','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',2,'ox','auto','향불을 넣어 보기 전에 뚜껑을 열어야 해요.',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"ox","stem":"향불을 넣어 보기 전에 뚜껑을 열어야 해요.","answer":"O","reason_options":[{"t":"뚜껑을 연 뒤 향불을 병 안에 넣어 보기 때문에","correct":true},{"t":"뚜껑을 닫은 채 넣어야 불씨가 커지기 때문에","mis":"SC6-2-u2-X02"}],"mis":"SC6-2-u2-X02","explanation":["순서 ④를 떠올려요.","열고 넣어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["① 네 가지 가루가 든 유리병 가운데 하나를 고른다.","② 가루가 잠길 만큼 따뜻한 물을 넣는다.","③ 뚜껑을 닫고 흔든 뒤 잠시 둔다.","④ 뚜껑을 열고 작은 불씨만 남은 향을 병 안에 넣는다.","⑤ 불씨를 살린 것이 무엇인지 이야기한다."],"title":"불씨가 살아나는 병 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#3','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',3,'mc','auto','불씨를 살린 것이 무엇인지 이야기할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"mc","stem":"불씨를 살린 것이 무엇인지 이야기할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"산소계 표백제에 있는 산소가 불씨를 살렸을 것 같다","correct":true},{"t":"따뜻한 물이 불씨를 살린 것이 확실하다","mis":"SC6-2-u2-X01"},{"t":"유리병이 커서 불씨가 살아났다","mis":"SC6-2-u2-X01"},{"t":"어떤 가루든 물에 넣으면 불씨가 커진다","mis":"SC6-2-u2-X01"}],"explanation":["커진 병만 떠올려요.","그 병에 있던 것을 짐작해요.","「~것 같다」로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#4','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',3,'error','auto','결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"error","stem":"결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「네 병 다 따뜻한 물을 넣었으니 물이 불씨를 살렸어.」","correct":true,"mis_target":"SC6-2-u2-X01"},{"t":"이준 — 「꺼져 가는 불씨를 살리는 물질이 있어.」","mis":"SC6-2-u2-X01"},{"t":"나윤 — 「불씨가 커진 병은 하나뿐이야.」","mis":"SC6-2-u2-X01"}],"explanation":["물은 네 병이 같아요.","물 때문이라면 네 병 다 커져야 해요.","서아가 잘못 말했어요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#5','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',3,'mc','auto','제빵 소다 병의 결과로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"mc","stem":"제빵 소다 병의 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"향불의 불씨가 꺼졌다","correct":true},{"t":"향불의 불씨가 커졌다","mis":"SC6-2-u2-X01"},{"t":"향불의 불씨가 두 개로 늘었다","mis":"SC6-2-u2-X01"},{"t":"병 안에 얼음이 생겼다","mis":"SC6-2-u2-X01"}],"explanation":["결과 표를 읽어요.","제빵 소다 줄이에요.","꺼졌어요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#6','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',3,'mc','auto','모둠이 네 병을 나누어 맡았을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"mc","stem":"모둠이 네 병을 나누어 맡았을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"각자 맡은 병의 결과를 책임지고 살펴 모둠과 나눈다","correct":true},{"t":"내 병만 보고 다른 친구 결과는 듣지 않는다","mis":"SC6-2-u2-X02"},{"t":"한 사람이 네 병을 모두 하고 나머지는 구경한다","mis":"SC6-2-u2-X02"},{"t":"먼저 끝낸 모둠을 이기려고 서두른다","mis":"SC6-2-u2-X02"}],"explanation":["역할을 나눴어요.","결과를 모아야 해요.","책임지고 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#7','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',3,'match','auto','병·물과 그에 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"match","stem":"병·물과 그에 알맞은 설명을 이으세요.","pairs":[{"l":"제빵 소다 병","r":"향불의 불씨가 꺼진다"},{"l":"산소계 표백제 병","r":"향불의 불씨가 커진다"},{"l":"따뜻한 물","r":"네 병에 모두 같게 넣는다"}],"mis":"SC6-2-u2-X01","explanation":["결과와 조건을 가려요.","커진 병은 하나예요.","물은 네 병이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#8','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',4,'mc','auto','불씨가 커진 까닭이 정말 산소계 표백제 때문인지 더 확인하려면 어떻게 하면 좋을까요?',ARRAY['SC6-2-u2-X01','SC6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C1","difficulty":4,"kind":"mc","stem":"불씨가 커진 까닭이 정말 산소계 표백제 때문인지 더 확인하려면 어떻게 하면 좋을까요?","options":[{"t":"물만 넣은 병과 산소계 표백제를 넣은 병을 같은 방법으로 견주어 본다","correct":true},{"t":"네 병의 따뜻한 물 온도를 모두 다르게 한다","mis":"SC6-2-u2-X01"},{"t":"향불 대신 큰 불꽃을 넣어 본다","mis":"SC6-2-u2-X02"},{"t":"결과를 짐작만 하고 실험은 하지 않는다","mis":"SC6-2-u2-X01"}],"explanation":["한 가지만 다르게 해요.","물만 넣은 병과 견줘요.","같은 방법으로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#9','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',4,'mc','auto','실험이 끝난 뒤 할 일로 가장 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C1","difficulty":4,"kind":"mc","stem":"실험이 끝난 뒤 할 일로 가장 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"사용한 향불을 끄고, 쓴 물질은 선생님 안내에 따라 정해진 곳에 버린다","correct":true},{"t":"향불은 그대로 두고 물질은 개수대에 쏟는다","mis":"SC6-2-u2-X02"},{"t":"남은 가루를 맛보아 무엇인지 확인한다","mis":"SC6-2-u2-X02"},{"t":"유리병을 흔들어 깨지는지 시험한다","mis":"SC6-2-u2-X02"}],"explanation":["불을 정리해요.","물질도 정리해요.","끄고 정해진 곳에 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L01_challenge#10','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',4,'essay','teacher','네 병의 결과를 쓰고, 불씨를 살린 것이 따뜻한 물이 아니라고 말할 수 있는 까닭과 불씨를 살린 것에 대한 나의 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C1","difficulty":4,"kind":"essay","stem":"네 병의 결과를 쓰고, 불씨를 살린 것이 따뜻한 물이 아니라고 말할 수 있는 까닭과 불씨를 살린 것에 대한 나의 생각을 쓰세요.","answer_guide":{"answer":"예: 소금·탄산 칼슘·제빵 소다 병에서는 향불의 불씨가 꺼졌고 산소계 표백제 병에서만 불씨가 커졌다. 네 병에는 모두 같은 따뜻한 물을 넣었는데 한 병에서만 불씨가 커졌으므로 따뜻한 물이 불씨를 살린 것이 아니다. 산소계 표백제가 물에 녹아 생긴 물질, 아마도 산소가 불씨를 살렸을 것 같다.","scoring_points":["네 병의 결과를 바르게 썼는가","같은 물을 넣었다는 점으로 물이 아닌 까닭을 썼는가","불씨를 살린 것을 짐작하는 말로 썼는가"]},"explanation":["결과부터 써요.","같게 한 것을 근거로 들어요.","짐작은 「~것 같다」로 써요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#1','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',1,'mc','auto','탄산수소 나트륨과 식초를 섞었을 때 고무풍선은 어떻게 되었나요?',ARRAY['SC6-2-u2-X04']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C2","difficulty":1,"kind":"mc","stem":"탄산수소 나트륨과 식초를 섞었을 때 고무풍선은 어떻게 되었나요?","options":[{"t":"점점 부풀어 올랐다","correct":true},{"t":"아무런 변화가 없었다","mis":"SC6-2-u2-X04"},{"t":"쪼그라들었다","mis":"SC6-2-u2-X04"},{"t":"색깔이 바뀌었다","mis":"SC6-2-u2-X04"}],"explanation":["결과 ㉯를 읽어요.","기포가 생겼어요.","부풀어 올랐어요."],"asset":{"type":"passage","lines":["㉮ 밀가루 — 고무풍선: 변화 없음 · 플라스크 안: 밀가루가 가라앉음","㉯ 탄산수소 나트륨 — 고무풍선: 점점 부풂 · 플라스크 안: 보글거리며 기포"],"title":"고무풍선 섞기 실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#2','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C3',1,'mc','auto','물에 설탕을 섞었을 때의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X07','SC6-2-u2-X06']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C3","difficulty":1,"kind":"mc","stem":"물에 설탕을 섞었을 때의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"설탕의 단맛이 그대로 난다","correct":true},{"t":"덩어리가 생긴다","mis":"SC6-2-u2-X07"},{"t":"열이 발생한다","mis":"SC6-2-u2-X07"},{"t":"짠맛이 난다","mis":"SC6-2-u2-X06"}],"explanation":["설탕물을 떠올려요.","맛이 남아요.","단맛이 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#3','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',1,'ox','auto','서로 다른 물질을 섞으면 물질의 성질이 항상 변하지 않아요.',ARRAY['SC6-2-u2-X03']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C2","difficulty":1,"kind":"ox","stem":"서로 다른 물질을 섞으면 물질의 성질이 항상 변하지 않아요.","answer":"X","reason_options":[{"t":"섞는 물질에 따라 성질이 변하기도 하고 변하지 않기도 하기 때문에","correct":true},{"t":"어떤 물질을 섞어도 그대로이기 때문에","mis":"SC6-2-u2-X03"}],"mis":"SC6-2-u2-X03","explanation":["두 고무풍선을 견줘요.","한쪽은 변했어요.","항상은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#4','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',1,'sa','auto','고무풍선에 가루를 넣을 때 쓰는 도구는 무엇인가요? (분말 □□□)','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C2","difficulty":1,"kind":"sa","stem":"고무풍선에 가루를 넣을 때 쓰는 도구는 무엇인가요? (분말 □□□)","answer":["깔때기","분말 깔때기"],"explanation":["가루를 흘리지 않게 해요.","세 글자예요.","깔때기예요."],"mis":"SC6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#5','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C3',2,'match','auto','섞은 것과 나타나는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"match","stem":"섞은 것과 나타나는 모습을 알맞게 이으세요.","pairs":[{"l":"우유와 식초","r":"덩어리가 생긴다"},{"l":"손난로 속 철 가루와 산소","r":"색깔이 변하고 열이 발생한다"},{"l":"물과 꿀","r":"꿀의 단맛이 그대로 난다"}],"mis":"SC6-2-u2-X07","explanation":["덩어리는 우유예요.","열은 손난로예요.","꿀물은 단맛이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#6','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',2,'mc','auto','밀가루와 식초를 섞은 삼각 플라스크 안에서는 어떤 일이 있었나요?',ARRAY['SC6-2-u2-X04','SC6-2-u2-X07']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"mc","stem":"밀가루와 식초를 섞은 삼각 플라스크 안에서는 어떤 일이 있었나요?","options":[{"t":"밀가루가 가라앉았다","correct":true},{"t":"보글거리며 기포가 생겼다","mis":"SC6-2-u2-X04"},{"t":"열이 나며 색깔이 변했다","mis":"SC6-2-u2-X07"},{"t":"고무풍선이 부풀었다","mis":"SC6-2-u2-X04"}],"explanation":["결과 ㉮를 읽어요.","플라스크 안이에요.","가라앉았어요."],"asset":{"type":"passage","lines":["㉮ 밀가루 — 고무풍선: 변화 없음 · 플라스크 안: 밀가루가 가라앉음","㉯ 탄산수소 나트륨 — 고무풍선: 점점 부풂 · 플라스크 안: 보글거리며 기포"],"title":"고무풍선 섞기 실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#7','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',2,'ox','auto','두 고무풍선은 하나씩 따로 세워도 결과를 똑같이 견줄 수 있어요.',ARRAY['SC6-2-u2-X05']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"ox","stem":"두 고무풍선은 하나씩 따로 세워도 결과를 똑같이 견줄 수 있어요.","answer":"X","reason_options":[{"t":"같은 때에 같은 조작을 해야 비교할 수 있어 동시에 세우기 때문에","correct":true},{"t":"세우는 때는 결과와 관계없기 때문에","mis":"SC6-2-u2-X05"}],"mis":"SC6-2-u2-X05","explanation":["실험 방법을 떠올려요.","동시에 세워요.","따로는 아니에요."],"asset":{"type":"passage","lines":["두 삼각 플라스크에 같은 양의 식초를 넣는다.","고무풍선 ㉮에는 밀가루, ㉯에는 탄산수소 나트륨을 두 숟가락씩 넣는다.","고무풍선을 플라스크 입구에 씌우고 두 개를 동시에 세운다."],"title":"고무풍선 섞기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#8','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C3',2,'blank','auto','「설탕이 물에 녹아 보이지 않아도 (    )과 같은 성질은 그대로입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"blank","stem":"「설탕이 물에 녹아 보이지 않아도 (    )과 같은 성질은 그대로입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"단맛","correct":true},{"t":"짠맛","mis":"SC6-2-u2-X06"},{"t":"색깔","mis":"SC6-2-u2-X06"},{"t":"딱딱함","mis":"SC6-2-u2-X06"}],"explanation":["설탕의 성질이에요.","맛을 떠올려요.","단맛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#9','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',2,'error','auto','실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X05']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"error","stem":"실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「고무풍선이 크게 부풀게 가루를 많이 넣자.」","correct":true,"mis_target":"SC6-2-u2-X05"},{"t":"유나 — 「가루마다 다른 약숟가락을 쓰자.」","mis":"SC6-2-u2-X05"},{"t":"준호 — 「약품이 피부에 닿지 않게 하자.」","mis":"SC6-2-u2-X05"}],"explanation":["정해진 양이 있어요.","두 숟가락씩이에요.","태민이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_basic#10','sci',6,2,'u2','L02','g6_2_sci_u2_L02_basic','lesson_basic','SC6-2-u2-C2',3,'mc','auto','두 삼각 플라스크에 같은 양의 식초를 넣은 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X05','SC6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C2","difficulty":3,"kind":"mc","stem":"두 삼각 플라스크에 같은 양의 식초를 넣은 까닭은 무엇인가요?","options":[{"t":"가루만 다르게 해서 가루에 따른 변화를 견주려고","correct":true},{"t":"식초가 많을수록 고무풍선이 커지니까","mis":"SC6-2-u2-X05"},{"t":"식초 냄새를 줄이려고","mis":"SC6-2-u2-X05"},{"t":"밀가루를 녹이려고","mis":"SC6-2-u2-X04"}],"explanation":["다른 것은 하나뿐이에요.","가루가 달라요.","나머지는 같게 해요."],"asset":{"type":"passage","lines":["두 삼각 플라스크에 같은 양의 식초를 넣는다.","고무풍선 ㉮에는 밀가루, ㉯에는 탄산수소 나트륨을 두 숟가락씩 넣는다.","고무풍선을 플라스크 입구에 씌우고 두 개를 동시에 세운다."],"title":"고무풍선 섞기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#1','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C2',2,'sa','auto','탄산수소 나트륨과 식초가 섞인 삼각 플라스크 안에서 보글거리며 생긴 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"sa","stem":"탄산수소 나트륨과 식초가 섞인 삼각 플라스크 안에서 보글거리며 생긴 것은 무엇인가요? 두 글자로 쓰세요.","answer":["기포","기체"],"explanation":["거품처럼 보여요.","고무풍선으로 들어갔어요.","기포예요."],"asset":{"type":"passage","lines":["㉮ 밀가루 — 고무풍선: 변화 없음 · 플라스크 안: 밀가루가 가라앉음","㉯ 탄산수소 나트륨 — 고무풍선: 점점 부풂 · 플라스크 안: 보글거리며 기포"],"title":"고무풍선 섞기 실험 결과"},"mis":"SC6-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#2','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C3',2,'mc','auto','물질의 성질이 변하는 예는 어느 것인가요?',ARRAY['SC6-2-u2-X07']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"mc","stem":"물질의 성질이 변하는 예는 어느 것인가요?","options":[{"t":"우유에 식초를 섞으면 덩어리가 생긴다","correct":true},{"t":"물에 설탕을 섞으면 단맛이 그대로 난다","mis":"SC6-2-u2-X07"},{"t":"물에 꿀을 섞으면 꿀의 단맛이 그대로 난다","mis":"SC6-2-u2-X07"},{"t":"소금과 설탕을 섞으면 짠맛과 단맛이 함께 난다","mis":"SC6-2-u2-X07"}],"explanation":["새로운 모습이 생긴 것을 골라요.","맛이 그대로면 변하지 않은 거예요.","덩어리가 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#3','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C3',3,'mc','auto','물에 녹은 설탕의 성질이 그대로라는 것을 보여 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"mc","stem":"물에 녹은 설탕의 성질이 그대로라는 것을 보여 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물을 증발시켜 설탕을 다시 얻는다","correct":true},{"t":"설탕물을 휘저어 거품을 낸다","mis":"SC6-2-u2-X06"},{"t":"설탕물에 식초를 붓는다","mis":"SC6-2-u2-X06"},{"t":"설탕물을 얼려 색깔을 본다","mis":"SC6-2-u2-X06"}],"explanation":["물을 없애 봐요.","설탕이 남아요.","증발시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#4','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C3',3,'error','auto','설탕물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"error","stem":"설탕물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「설탕이 안 보이니 설탕의 성질이 변한 거야.」","correct":true,"mis_target":"SC6-2-u2-X06"},{"t":"하준 — 「녹아도 단맛은 그대로야.」","mis":"SC6-2-u2-X06"},{"t":"은채 — 「물을 증발시키면 설탕을 다시 얻어.」","mis":"SC6-2-u2-X06"}],"explanation":["눈에 안 보여도 맛이 나요.","성질이 남아 있어요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#5','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C3',3,'ox','auto','손난로 속 철 가루가 공기 중의 산소와 섞이면 물질의 성질이 변해요.',ARRAY['SC6-2-u2-X07']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"ox","stem":"손난로 속 철 가루가 공기 중의 산소와 섞이면 물질의 성질이 변해요.","answer":"O","reason_options":[{"t":"색깔이 변하고 열이 발생하기 때문에","correct":true},{"t":"섞어도 아무 변화가 없기 때문에","mis":"SC6-2-u2-X07"}],"mis":"SC6-2-u2-X07","explanation":["손난로가 따뜻해져요.","색깔도 바뀌어요.","성질이 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#6','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C2',3,'mc','auto','이 실험에서 「물질의 성질이 변했다」고 말할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X04','SC6-2-u2-X05']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C2","difficulty":3,"kind":"mc","stem":"이 실험에서 「물질의 성질이 변했다」고 말할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탄산수소 나트륨 쪽에서 기포가 생기고 고무풍선이 부풀었다","correct":true},{"t":"밀가루 쪽 고무풍선이 늘어진 채 그대로였다","mis":"SC6-2-u2-X04"},{"t":"두 플라스크에 같은 식초를 넣었다","mis":"SC6-2-u2-X05"},{"t":"두 고무풍선을 동시에 세웠다","mis":"SC6-2-u2-X05"}],"explanation":["결과를 근거로 들어요.","새로운 변화가 보인 쪽이에요.","기포와 부푼 고무풍선이에요."],"asset":{"type":"passage","lines":["㉮ 밀가루 — 고무풍선: 변화 없음 · 플라스크 안: 밀가루가 가라앉음","㉯ 탄산수소 나트륨 — 고무풍선: 점점 부풂 · 플라스크 안: 보글거리며 기포"],"title":"고무풍선 섞기 실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#7','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C2',3,'match','auto','실험 도구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u2-C2","difficulty":3,"kind":"match","stem":"실험 도구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"삼각 플라스크","r":"식초가 담겨 있다"},{"l":"고무풍선","r":"플라스크 입구에 씌운다"},{"l":"약숟가락","r":"가루를 두 숟가락씩 담는다"},{"l":"분말 깔때기","r":"고무풍선에 가루를 넣을 때 쓴다"}],"mis":"SC6-2-u2-X05","explanation":["담는 그릇을 찾아요.","씌우는 것은 고무풍선이에요.","담고 넣는 도구를 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#8','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C3',4,'mc','auto','소금과 설탕을 섞은 것을 맛보았더니 짠맛과 단맛이 함께 났어요. 이 결과와 같은 쪽으로 가를 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X03','SC6-2-u2-X07']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C3","difficulty":4,"kind":"mc","stem":"소금과 설탕을 섞은 것을 맛보았더니 짠맛과 단맛이 함께 났어요. 이 결과와 같은 쪽으로 가를 수 있는 것은 어느 것인가요?","options":[{"t":"밀가루와 식초를 섞었을 때","correct":true},{"t":"탄산수소 나트륨과 식초를 섞었을 때","mis":"SC6-2-u2-X03"},{"t":"우유에 식초를 섞었을 때","mis":"SC6-2-u2-X07"},{"t":"손난로 속 철 가루가 산소와 섞일 때","mis":"SC6-2-u2-X07"}],"explanation":["맛이 그대로 났어요.","성질이 변하지 않은 쪽이에요.","밀가루와 식초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#9','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C2',4,'mc','auto','섞기 실험과 주변의 예에서 알게 된 것을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X03','SC6-2-u2-X06']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C2","difficulty":4,"kind":"mc","stem":"섞기 실험과 주변의 예에서 알게 된 것을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"서로 다른 물질을 섞으면 섞는 물질에 따라 성질이 변하기도 하고 변하지 않기도 한다","correct":true},{"t":"서로 다른 물질을 섞으면 성질이 항상 변한다","mis":"SC6-2-u2-X03"},{"t":"서로 다른 물질을 섞으면 성질이 항상 변하지 않는다","mis":"SC6-2-u2-X03"},{"t":"물에 녹아 보이지 않으면 성질이 변한 것이다","mis":"SC6-2-u2-X06"}],"explanation":["두 고무풍선을 함께 봐요.","주변의 예도 떠올려요.","변하기도, 변하지 않기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L02_challenge#10','sci',6,2,'u2','L02','g6_2_sci_u2_L02_challenge','lesson_challenge','SC6-2-u2-C2',4,'essay','teacher','고무풍선 섞기 실험의 두 결과를 견주어 쓰고, 이 실험에서 같게 한 것과 다르게 한 것을 들어 서로 다른 물질을 섞을 때의 변화를 정리하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C2","difficulty":4,"kind":"essay","stem":"고무풍선 섞기 실험의 두 결과를 견주어 쓰고, 이 실험에서 같게 한 것과 다르게 한 것을 들어 서로 다른 물질을 섞을 때의 변화를 정리하세요.","answer_guide":{"answer":"예: 밀가루와 식초를 섞은 쪽은 고무풍선에 변화가 없고 밀가루가 가라앉아 물질의 성질이 변하지 않았다. 탄산수소 나트륨과 식초를 섞은 쪽은 보글거리며 기포가 생기고 고무풍선이 부풀어 성질이 변했다. 식초의 양과 세우는 때는 같게 하고 가루만 다르게 했으므로, 서로 다른 물질을 섞으면 섞는 물질에 따라 성질이 변하기도 하고 변하지 않기도 한다.","scoring_points":["두 결과를 바르게 견주었는가","같게 한 것과 다르게 한 것을 썼는가","변하기도 하고 변하지 않기도 한다고 정리했는가"]},"explanation":["두 쪽 결과를 써요.","조건을 가려요.","정리 문장을 써요."],"asset":{"type":"passage","lines":["㉮ 밀가루 — 고무풍선: 변화 없음 · 플라스크 안: 밀가루가 가라앉음","㉯ 탄산수소 나트륨 — 고무풍선: 점점 부풂 · 플라스크 안: 보글거리며 기포"],"title":"고무풍선 섞기 실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#1','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',1,'mc','auto','양초와 알코올이 탈 때 공통적으로 나타나는 현상은 어느 것인가요?',ARRAY['SC6-2-u2-X08','SC6-2-u2-X09','SC6-2-u2-X10']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"mc","stem":"양초와 알코올이 탈 때 공통적으로 나타나는 현상은 어느 것인가요?","options":[{"t":"빛과 열이 난다","correct":true},{"t":"불꽃 주변이 차가워진다","mis":"SC6-2-u2-X08"},{"t":"불꽃이 푸른색만 보인다","mis":"SC6-2-u2-X09"},{"t":"양초와 알코올의 양이 늘어난다","mis":"SC6-2-u2-X10"}],"explanation":["밝아지고 따뜻해져요.","두 물질 모두 그래요.","빛과 열이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#2','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',1,'mc','auto','양초가 탈 때 불꽃의 색깔은 어떠했나요?',ARRAY['SC6-2-u2-X09']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"mc","stem":"양초가 탈 때 불꽃의 색깔은 어떠했나요?","options":[{"t":"노란색, 붉은색 등","correct":true},{"t":"푸른색, 붉은색 등","mis":"SC6-2-u2-X09"},{"t":"위아래로 길쭉하다","mis":"SC6-2-u2-X09"},{"t":"불꽃 주변이 밝아진다","mis":"SC6-2-u2-X09"}],"explanation":["색깔 줄을 읽어요.","양초 쪽이에요.","노란색, 붉은색 등이에요."],"asset":{"type":"passage","lines":["모양 — 양초: 위아래로 길쭉 · 알코올: 위아래로 길쭉","밝기 — 양초: 주변이 밝아짐 · 알코올: 주변이 밝아짐","색깔 — 양초: 노란색, 붉은색 등 · 알코올: 푸른색, 붉은색 등","따뜻한 정도 — 둘 다 불꽃에 가까울수록 더 따뜻함"],"title":"양초와 알코올이 탈 때 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#3','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',1,'ox','auto','양초가 타는 동안 시간이 지나면 양초의 길이가 점점 짧아져요.',ARRAY['SC6-2-u2-X10']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"ox","stem":"양초가 타는 동안 시간이 지나면 양초의 길이가 점점 짧아져요.","answer":"O","reason_options":[{"t":"양초가 타면서 양초의 양이 줄어들기 때문에","correct":true},{"t":"양초는 타도 양이 그대로이기 때문에","mis":"SC6-2-u2-X10"}],"mis":"SC6-2-u2-X10","explanation":["오래 켠 초를 떠올려요.","양이 줄어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#4','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C5',1,'sa','auto','물질이 탈 때 나오는 것 가운데 어두운 곳을 밝히는 것은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C5","difficulty":1,"kind":"sa","stem":"물질이 탈 때 나오는 것 가운데 어두운 곳을 밝히는 것은 무엇인가요? 한 글자로 쓰세요.","answer":["빛"],"explanation":["밝히는 것이에요.","열과 함께 나와요.","빛이에요."],"mis":"SC6-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#5','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',2,'match','auto','관찰 항목과 양초·알코올을 함께 본 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"match","stem":"관찰 항목과 양초·알코올을 함께 본 결과를 알맞게 이으세요.","pairs":[{"l":"불꽃의 모양","r":"둘 다 위아래로 길쭉하다"},{"l":"밝기","r":"둘 다 불꽃 주변이 밝아진다"},{"l":"색깔","r":"서로 다르다"},{"l":"따뜻한 정도","r":"둘 다 가까울수록 따뜻하다"}],"mis":"SC6-2-u2-X09","explanation":["관찰 기록을 읽어요.","셋은 같아요.","색깔만 달라요."],"asset":{"type":"passage","lines":["모양 — 양초: 위아래로 길쭉 · 알코올: 위아래로 길쭉","밝기 — 양초: 주변이 밝아짐 · 알코올: 주변이 밝아짐","색깔 — 양초: 노란색, 붉은색 등 · 알코올: 푸른색, 붉은색 등","따뜻한 정도 — 둘 다 불꽃에 가까울수록 더 따뜻함"],"title":"양초와 알코올이 탈 때 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#6','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C5',2,'mc','auto','물질이 탈 때 나오는 열을 주로 이용하는 예는 어느 것인가요?',ARRAY['SC6-2-u2-X11']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C5","difficulty":2,"kind":"mc","stem":"물질이 탈 때 나오는 열을 주로 이용하는 예는 어느 것인가요?","options":[{"t":"벽난로의 장작불","correct":true},{"t":"강물 위의 유등","mis":"SC6-2-u2-X11"},{"t":"막대 폭죽의 불꽃","mis":"SC6-2-u2-X11"},{"t":"생일 케이크 위 촛불로 어두운 방 밝히기","mis":"SC6-2-u2-X11"}],"explanation":["따뜻하게 하는 쪽이에요.","난방에 써요.","벽난로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#7','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',2,'ox','auto','알코올램프의 불을 끌 때는 입으로 세게 불어 꺼요.',ARRAY['SC6-2-u2-X12']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"ox","stem":"알코올램프의 불을 끌 때는 입으로 세게 불어 꺼요.","answer":"X","reason_options":[{"t":"알코올램프는 뚜껑을 덮어 끄기 때문에","correct":true},{"t":"입으로 불어야 가장 빨리 꺼지기 때문에","mis":"SC6-2-u2-X12"}],"mis":"SC6-2-u2-X12","explanation":["알코올램프 사용법을 떠올려요.","뚜껑이 있어요.","뚜껑을 덮어 꺼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#8','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',2,'error','auto','실험하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X12']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"error","stem":"실험하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「불꽃은 위에서 얼굴을 가까이 대고 보자.」","correct":true,"mis_target":"SC6-2-u2-X12"},{"t":"시우 — 「비상구와 소화기 위치부터 확인하자.」","mis":"SC6-2-u2-X12"},{"t":"다인 — 「불꽃 근처에 탈 수 있는 물질을 두지 말자.」","mis":"SC6-2-u2-X12"}],"explanation":["불꽃 윗부분은 매우 뜨거워요.","가까이하면 위험해요.","로아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#9','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',2,'blank','auto','「알코올이 타는 동안 시간이 지날수록 알코올의 양이 (    ).」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X10']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"blank","stem":"「알코올이 타는 동안 시간이 지날수록 알코올의 양이 (    ).」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"줄어듭니다","correct":true},{"t":"늘어납니다","mis":"SC6-2-u2-X10"},{"t":"그대로입니다","mis":"SC6-2-u2-X10"},{"t":"얼어붙습니다","mis":"SC6-2-u2-X10"}],"explanation":["타는 동안을 생각해요.","양초와 같아요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_basic#10','sci',6,2,'u2','L03','g6_2_sci_u2_L03_basic','lesson_basic','SC6-2-u2-C4',3,'mc','auto','불꽃의 색깔이 서로 다른데도 공통적인 현상이 있다고 말할 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X09','SC6-2-u2-X08']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C4","difficulty":3,"kind":"mc","stem":"불꽃의 색깔이 서로 다른데도 공통적인 현상이 있다고 말할 수 있는 까닭은 무엇인가요?","options":[{"t":"색깔은 달라도 두 불꽃 모두 빛과 열이 나기 때문에","correct":true},{"t":"두 불꽃의 색깔이 같기 때문에","mis":"SC6-2-u2-X09"},{"t":"양초에서만 빛과 열이 나기 때문에","mis":"SC6-2-u2-X08"},{"t":"색깔이 다르면 공통점을 말할 수 없기 때문에","mis":"SC6-2-u2-X09"}],"explanation":["네 항목을 함께 봐요.","셋이 같아요.","빛과 열은 둘 다예요."],"asset":{"type":"passage","lines":["모양 — 양초: 위아래로 길쭉 · 알코올: 위아래로 길쭉","밝기 — 양초: 주변이 밝아짐 · 알코올: 주변이 밝아짐","색깔 — 양초: 노란색, 붉은색 등 · 알코올: 푸른색, 붉은색 등","따뜻한 정도 — 둘 다 불꽃에 가까울수록 더 따뜻함"],"title":"양초와 알코올이 탈 때 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#1','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',2,'sa','auto','물질이 탈 때 공통적으로 발생하는 두 가지는 빛과 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"sa","stem":"물질이 탈 때 공통적으로 발생하는 두 가지는 빛과 무엇인가요? 한 글자로 쓰세요.","answer":["열"],"explanation":["따뜻해져요.","빛과 함께 나와요.","열이에요."],"mis":"SC6-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#2','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C5',2,'mc','auto','물질이 탈 때 나오는 빛을 주로 이용하는 예끼리 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X11']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C5","difficulty":2,"kind":"mc","stem":"물질이 탈 때 나오는 빛을 주로 이용하는 예끼리 짝지은 것은 어느 것인가요?","options":[{"t":"강물 위의 유등, 막대 폭죽의 불꽃","correct":true},{"t":"벽난로의 장작불, 가스레인지의 불꽃","mis":"SC6-2-u2-X11"},{"t":"강물 위의 유등, 가스레인지의 불꽃","mis":"SC6-2-u2-X11"},{"t":"벽난로의 장작불, 막대 폭죽의 불꽃","mis":"SC6-2-u2-X11"}],"explanation":["밝히는 쪽을 골라요.","데우는 쪽은 빼요.","유등과 막대 폭죽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#3','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',3,'mc','auto','불을 붙이기 전의 양초와 견주어 관찰하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X08','SC6-2-u2-X10','SC6-2-u2-X09']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C4","difficulty":3,"kind":"mc","stem":"불을 붙이기 전의 양초와 견주어 관찰하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탈 때 새로 나타나는 현상을 분명히 알아보려고","correct":true},{"t":"불을 붙이기 전에도 빛이 나는지 보려고","mis":"SC6-2-u2-X08"},{"t":"양초를 더 길게 만들려고","mis":"SC6-2-u2-X10"},{"t":"불꽃 색깔을 바꾸려고","mis":"SC6-2-u2-X09"}],"explanation":["전과 후를 견줘요.","달라진 것을 찾아요.","새로 나타난 현상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#4','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',3,'error','auto','관찰 기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X09','SC6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C4","difficulty":3,"kind":"error","stem":"관찰 기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「색깔이 다르니 두 불꽃은 같은 점이 하나도 없어.」","correct":true,"mis_target":"SC6-2-u2-X09"},{"t":"지후 — 「둘 다 주변이 밝아졌어.」","mis":"SC6-2-u2-X08"},{"t":"예린 — 「둘 다 가까울수록 따뜻했어.」","mis":"SC6-2-u2-X08"}],"explanation":["네 항목 가운데 셋이 같아요.","색깔만 달라요.","하율이 잘못 말했어요."],"asset":{"type":"passage","lines":["모양 — 양초: 위아래로 길쭉 · 알코올: 위아래로 길쭉","밝기 — 양초: 주변이 밝아짐 · 알코올: 주변이 밝아짐","색깔 — 양초: 노란색, 붉은색 등 · 알코올: 푸른색, 붉은색 등","따뜻한 정도 — 둘 다 불꽃에 가까울수록 더 따뜻함"],"title":"양초와 알코올이 탈 때 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#5','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C5',3,'ox','auto','가스레인지의 불꽃은 물질이 탈 때 나오는 열로 음식을 조리하는 예예요.',ARRAY['SC6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C5","difficulty":3,"kind":"ox","stem":"가스레인지의 불꽃은 물질이 탈 때 나오는 열로 음식을 조리하는 예예요.","answer":"O","reason_options":[{"t":"가스레인지는 불꽃의 열로 음식을 익히기 때문에","correct":true},{"t":"가스레인지는 주로 어두운 곳을 밝히기 때문에","mis":"SC6-2-u2-X11"}],"mis":"SC6-2-u2-X11","explanation":["부엌에서 써요.","음식을 익혀요.","열을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#6','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',3,'mc','auto','양초와 알코올이 탈 때 관찰한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X08','SC6-2-u2-X10']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C4","difficulty":3,"kind":"mc","stem":"양초와 알코올이 탈 때 관찰한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"불꽃 주변이 어두워졌다","correct":true},{"t":"불꽃이 위아래로 길쭉했다","mis":"SC6-2-u2-X08"},{"t":"불꽃에 가까울수록 따뜻했다","mis":"SC6-2-u2-X08"},{"t":"시간이 지나며 양이 줄었다","mis":"SC6-2-u2-X10"}],"explanation":["관찰 기록과 견줘요.","밝기 줄을 봐요.","어두워지지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#7','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',3,'mc','auto','양초에 불을 붙인 뒤 지킬 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X12']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C4","difficulty":3,"kind":"mc","stem":"양초에 불을 붙인 뒤 지킬 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜨거운 촛농을 만지지 않는다","correct":true},{"t":"촛농이 얼마나 뜨거운지 손가락으로 만져 본다","mis":"SC6-2-u2-X12"},{"t":"불꽃에 종이를 가까이 대어 본다","mis":"SC6-2-u2-X12"},{"t":"불꽃 바로 위에서 냄새를 맡는다","mis":"SC6-2-u2-X12"}],"explanation":["촛농은 뜨거워요.","몸이 닿지 않게 해요.","만지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#8','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C5',4,'mc','auto','정전이 된 캄캄한 겨울밤에 촛불을 켰어요. 이때 촛불에서 얻을 수 있는 것을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X08','SC6-2-u2-X10']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C5","difficulty":4,"kind":"mc","stem":"정전이 된 캄캄한 겨울밤에 촛불을 켰어요. 이때 촛불에서 얻을 수 있는 것을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"빛으로 방을 밝히고, 가까이에서는 열로 따뜻함을 느낄 수 있다","correct":true},{"t":"빛만 나고 열은 전혀 나지 않는다","mis":"SC6-2-u2-X08"},{"t":"열만 나고 빛은 나지 않는다","mis":"SC6-2-u2-X08"},{"t":"촛불을 켤수록 초가 점점 길어진다","mis":"SC6-2-u2-X10"}],"explanation":["탈 때 나오는 두 가지예요.","밝히고 데워요.","빛과 열을 모두 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#9','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',4,'mc','auto','이 차시에서 알게 된 것을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X09','SC6-2-u2-X08','SC6-2-u2-X10']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C4","difficulty":4,"kind":"mc","stem":"이 차시에서 알게 된 것을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"물질이 탈 때에는 빛과 열이 발생하고, 우리는 이 빛과 열을 생활에 이용한다","correct":true},{"t":"물질이 탈 때 나타나는 현상은 물질마다 모두 다르다","mis":"SC6-2-u2-X09"},{"t":"물질이 탈 때에는 빛만 발생한다","mis":"SC6-2-u2-X08"},{"t":"물질이 탈 때 물질의 양은 변하지 않는다","mis":"SC6-2-u2-X10"}],"explanation":["공통점을 떠올려요.","이용하는 예도 있어요.","빛과 열이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L03_challenge#10','sci',6,2,'u2','L03','g6_2_sci_u2_L03_challenge','lesson_challenge','SC6-2-u2-C4',4,'essay','teacher','양초와 알코올이 탈 때의 관찰 기록을 보고 같은 점과 다른 점을 쓰고, 물질이 탈 때 나타나는 공통적인 현상과 그것을 생활에서 이용하는 예를 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C4","difficulty":4,"kind":"essay","stem":"양초와 알코올이 탈 때의 관찰 기록을 보고 같은 점과 다른 점을 쓰고, 물질이 탈 때 나타나는 공통적인 현상과 그것을 생활에서 이용하는 예를 하나씩 쓰세요.","answer_guide":{"answer":"예: 두 불꽃은 모두 위아래로 길쭉하고, 주변이 밝아지며, 가까울수록 따뜻했다. 다른 점은 색깔로 양초는 노란색·붉은색 등, 알코올은 푸른색·붉은색 등이었다. 물질이 탈 때에는 공통적으로 빛과 열이 발생한다. 빛은 유등처럼 어두운 곳을 밝히는 데, 열은 가스레인지처럼 음식을 조리하는 데 이용한다.","scoring_points":["같은 점과 다른 점(색깔)을 바르게 썼는가","공통적인 현상을 빛과 열로 썼는가","빛이나 열을 이용하는 예를 알맞게 썼는가"]},"explanation":["네 항목을 견줘요.","공통점을 써요.","생활 예를 들어요."],"asset":{"type":"passage","lines":["모양 — 양초: 위아래로 길쭉 · 알코올: 위아래로 길쭉","밝기 — 양초: 주변이 밝아짐 · 알코올: 주변이 밝아짐","색깔 — 양초: 노란색, 붉은색 등 · 알코올: 푸른색, 붉은색 등","따뜻한 정도 — 둘 다 불꽃에 가까울수록 더 따뜻함"],"title":"양초와 알코올이 탈 때 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#1','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C6',1,'mc','auto','연소란 무엇인가요?',ARRAY['SC6-2-u2-X13']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"mc","stem":"연소란 무엇인가요?","options":[{"t":"물질이 산소와 만나 빛과 열을 내면서 타는 현상","correct":true},{"t":"물질이 물과 만나 차가워지는 현상","mis":"SC6-2-u2-X13"},{"t":"서로 다른 물질을 섞어 기포가 생기는 현상","mis":"SC6-2-u2-X13"},{"t":"물질의 색깔만 검게 변하는 현상","mis":"SC6-2-u2-X13"}],"explanation":["타는 현상이에요.","산소와 만나요.","빛과 열을 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#2','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C7',1,'mc','auto','아크릴 통 실험에서 더 오래 탄 촛불은 어느 것인가요?',ARRAY['SC6-2-u2-X15','SC6-2-u2-X19']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C7","difficulty":1,"kind":"mc","stem":"아크릴 통 실험에서 더 오래 탄 촛불은 어느 것인가요?","options":[{"t":"산소가 발생하는 비커와 함께 덮은 촛불","correct":true},{"t":"양초만 덮은 촛불","mis":"SC6-2-u2-X15"},{"t":"두 촛불이 동시에 꺼졌다","mis":"SC6-2-u2-X15"},{"t":"통을 덮지 않은 쪽만 탔다","mis":"SC6-2-u2-X19"}],"explanation":["결과 줄을 읽어요.","양초만 덮은 쪽이 먼저 꺼졌어요.","비커와 함께 덮은 쪽이에요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙인다.","한쪽 양초 옆에만 산소가 발생하는 비커를 놓는다.","같은 크기의 아크릴 통 두 개로 두 양초를 동시에 덮는다.","결과 — 양초만 덮은 쪽이 먼저 꺼지고, 비커와 함께 덮은 쪽이 더 오래 탔다."],"title":"아크릴 통 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#3','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C6',1,'ox','auto','연소에 필요한 조건 가운데 하나라도 없으면 연소는 일어나지 않아요.',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"ox","stem":"연소에 필요한 조건 가운데 하나라도 없으면 연소는 일어나지 않아요.","answer":"O","reason_options":[{"t":"탈 물질, 산소, 발화점 이상의 온도가 모두 있어야 하기 때문에","correct":true},{"t":"조건 하나만 있어도 물질이 타기 때문에","mis":"SC6-2-u2-X14"}],"mis":"SC6-2-u2-X14","explanation":["조건이 셋이에요.","모두 있어야 해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#4','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C8',1,'sa','auto','어떤 물질이 타기 시작하는 온도를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C8","difficulty":1,"kind":"sa","stem":"어떤 물질이 타기 시작하는 온도를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["발화점"],"explanation":["불이 붙기 시작하는 온도예요.","□화점이에요.","발화점이에요."],"mis":"SC6-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#5','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C8',2,'mc','auto','철판 실험에서 먼저 불이 붙은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X17','SC6-2-u2-X18']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":2,"kind":"mc","stem":"철판 실험에서 먼저 불이 붙은 것은 어느 것인가요?","options":[{"t":"성냥의 머리 부분","correct":true},{"t":"성냥의 나무 부분","mis":"SC6-2-u2-X17"},{"t":"둘에 동시에 붙었다","mis":"SC6-2-u2-X17"},{"t":"둘 다 끝까지 붙지 않았다","mis":"SC6-2-u2-X18"}],"explanation":["결과 줄을 읽어요.","먼저 붙은 쪽이에요.","머리 부분이에요."],"asset":{"type":"passage","lines":["삼발이 위에 철판을 올린다.","철판 가운데에서 같은 거리에 성냥의 머리 부분과 나무 부분을 놓는다.","철판 가운데를 알코올램프로 가열한다.","결과 — 성냥의 머리 부분에 불이 먼저 붙었다."],"title":"철판 가열 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#6','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C6',2,'match','auto','실험과 그 실험이 알려 주는 연소의 조건을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u2-C6","difficulty":2,"kind":"match","stem":"실험과 그 실험이 알려 주는 연소의 조건을 알맞게 이으세요.","pairs":[{"l":"비커와 함께 덮은 촛불이 더 오래 탔다","r":"산소가 필요하다"},{"l":"철판을 가열하니 성냥 머리 부분에 불이 붙었다","r":"발화점 이상의 온도가 필요하다"},{"l":"양초·나무·알코올이 탄다","r":"탈 물질이 필요하다"}],"mis":"SC6-2-u2-X19","explanation":["비커는 산소를 내요.","가열은 온도를 높여요.","타는 물질이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#7','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C7',2,'ox','auto','장작불이 약해졌을 때 부채질을 하면 불이 세져요.',ARRAY['SC6-2-u2-X15']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"ox","stem":"장작불이 약해졌을 때 부채질을 하면 불이 세져요.","answer":"O","reason_options":[{"t":"부채질로 산소를 공급하면 연소가 활발해지기 때문에","correct":true},{"t":"부채질로 장작의 온도를 낮추기 때문에","mis":"SC6-2-u2-X15"}],"mis":"SC6-2-u2-X15","explanation":["공기를 불어 넣어요.","산소가 더 들어가요.","불이 세져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#8','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C8',2,'error','auto','철판 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X12']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C8","difficulty":2,"kind":"error","stem":"철판 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「끝나자마자 철판을 손으로 치우자.」","correct":true,"mis_target":"SC6-2-u2-X12"},{"t":"승민 — 「철판이 완전히 식을 때까지 만지지 말자.」","mis":"SC6-2-u2-X12"},{"t":"채아 — 「머리 부분에 불이 붙을 때 얼굴을 가까이하지 말자.」","mis":"SC6-2-u2-X12"}],"explanation":["가열한 철판은 뜨거워요.","식을 때까지 기다려요.","규리가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#9','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C6',2,'blank','auto','「연소가 일어나려면 탈 물질, (    ), 발화점 이상의 온도가 모두 필요합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C6","difficulty":2,"kind":"blank","stem":"「연소가 일어나려면 탈 물질, (    ), 발화점 이상의 온도가 모두 필요합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"산소","correct":true},{"t":"물","mis":"SC6-2-u2-X14"},{"t":"식초","mis":"SC6-2-u2-X14"},{"t":"얼음","mis":"SC6-2-u2-X14"}],"explanation":["비커에서 발생한 기체예요.","타는 것을 도와요.","산소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_basic#10','sci',6,2,'u2','L04','g6_2_sci_u2_L04_basic','lesson_basic','SC6-2-u2-C7',3,'mc','auto','두 촛불을 덮을 때 같은 크기의 아크릴 통으로 동시에 덮은 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X19']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"mc","stem":"두 촛불을 덮을 때 같은 크기의 아크릴 통으로 동시에 덮은 까닭은 무엇인가요?","options":[{"t":"산소가 발생하는 비커가 있는지만 다르게 하려고","correct":true},{"t":"통이 클수록 촛불이 빨리 꺼지기 때문에","mis":"SC6-2-u2-X19"},{"t":"두 양초의 온도를 다르게 하려고","mis":"SC6-2-u2-X19"},{"t":"통 안을 더 밝게 하려고","mis":"SC6-2-u2-X19"}],"explanation":["다른 것은 하나뿐이어야 해요.","비커만 달라요.","나머지는 같게 해요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙인다.","한쪽 양초 옆에만 산소가 발생하는 비커를 놓는다.","같은 크기의 아크릴 통 두 개로 두 양초를 동시에 덮는다.","결과 — 양초만 덮은 쪽이 먼저 꺼지고, 비커와 함께 덮은 쪽이 더 오래 탔다."],"title":"아크릴 통 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#1','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C6',2,'sa','auto','물질이 산소와 만나 빛과 열을 내면서 타는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C6","difficulty":2,"kind":"sa","stem":"물질이 산소와 만나 빛과 열을 내면서 타는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["연소"],"explanation":["이 단원의 이름에 있어요.","□소예요.","연소예요."],"mis":"SC6-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#2','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C7',2,'mc','auto','양초만 덮은 촛불이 꺼진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X14','SC6-2-u2-X15']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"mc","stem":"양초만 덮은 촛불이 꺼진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"연소할 수 있을 만큼 산소가 충분하지 않았기 때문에","correct":true},{"t":"아크릴 통 안의 산소가 모두 없어졌기 때문에","mis":"SC6-2-u2-X16"},{"t":"아크릴 통 안의 양초가 모두 없어졌기 때문에","mis":"SC6-2-u2-X14"},{"t":"아크릴 통이 비커보다 컸기 때문에","mis":"SC6-2-u2-X15"}],"explanation":["꺼진 뒤에도 통 안에 산소가 남아 있어요.","모자랐던 거예요.","충분하지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#3','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C7',3,'error','auto','아크릴 통 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X15']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"error","stem":"아크릴 통 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「통 안의 산소가 하나도 남김없이 사라져서 꺼졌어.」","correct":true,"mis_target":"SC6-2-u2-X16"},{"t":"윤서 — 「산소가 충분하지 않으면 연소가 일어나지 않아.」","mis":"SC6-2-u2-X16"},{"t":"지민 — 「산소가 많을수록 더 잘 타.」","mis":"SC6-2-u2-X15"}],"explanation":["꺼진 뒤에도 산소가 남아요.","모두 없어진 게 아니에요.","도하가 잘못 말했어요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙인다.","한쪽 양초 옆에만 산소가 발생하는 비커를 놓는다.","같은 크기의 아크릴 통 두 개로 두 양초를 동시에 덮는다.","결과 — 양초만 덮은 쪽이 먼저 꺼지고, 비커와 함께 덮은 쪽이 더 오래 탔다."],"title":"아크릴 통 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#4','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C8',3,'mc','auto','성냥의 머리 부분에 먼저 불이 붙은 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X17','SC6-2-u2-X18']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"mc","stem":"성냥의 머리 부분에 먼저 불이 붙은 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물질에 따라 발화점이 다르다","correct":true},{"t":"모든 물질의 발화점은 같다","mis":"SC6-2-u2-X17"},{"t":"나무는 절대 타지 않는다","mis":"SC6-2-u2-X17"},{"t":"불은 철판에서 저절로 생긴다","mis":"SC6-2-u2-X18"}],"explanation":["같은 거리에 놓았어요.","붙는 때가 달랐어요.","발화점이 달라요."],"asset":{"type":"passage","lines":["삼발이 위에 철판을 올린다.","철판 가운데에서 같은 거리에 성냥의 머리 부분과 나무 부분을 놓는다.","철판 가운데를 알코올램프로 가열한다.","결과 — 성냥의 머리 부분에 불이 먼저 붙었다."],"title":"철판 가열 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#5','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C8',3,'mc','auto','불을 직접 붙이지 않고 물질을 태우는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X18','SC6-2-u2-X14']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"mc","stem":"불을 직접 붙이지 않고 물질을 태우는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"볼록 렌즈로 햇빛을 모아 물질의 온도를 높인다","correct":true},{"t":"물질을 차가운 물에 담근다","mis":"SC6-2-u2-X18"},{"t":"물질을 아크릴 통으로 꼭 덮는다","mis":"SC6-2-u2-X14"},{"t":"물질을 그늘에 오래 둔다","mis":"SC6-2-u2-X18"}],"explanation":["온도를 높여야 해요.","발화점 이상이 되게 해요.","햇빛을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#6','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C8',3,'ox','auto','성냥의 머리 부분과 나무 부분은 철판 가운데로부터 같은 거리에 놓아야 해요.',ARRAY['SC6-2-u2-X19']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"ox","stem":"성냥의 머리 부분과 나무 부분은 철판 가운데로부터 같은 거리에 놓아야 해요.","answer":"O","reason_options":[{"t":"받는 열을 같게 해야 두 부분의 발화점을 견줄 수 있기 때문에","correct":true},{"t":"가까이 붙여 놓아야 불이 함께 붙기 때문에","mis":"SC6-2-u2-X19"}],"mis":"SC6-2-u2-X19","explanation":["같게 할 조건이에요.","거리가 다르면 비교가 안 돼요.","같은 거리에 놓아요."],"asset":{"type":"passage","lines":["삼발이 위에 철판을 올린다.","철판 가운데에서 같은 거리에 성냥의 머리 부분과 나무 부분을 놓는다.","철판 가운데를 알코올램프로 가열한다.","결과 — 성냥의 머리 부분에 불이 먼저 붙었다."],"title":"철판 가열 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#7','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C7',3,'mc','auto','화로의 공기 조절 장치로 불의 세기를 조절할 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X14','SC6-2-u2-X15']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"mc","stem":"화로의 공기 조절 장치로 불의 세기를 조절할 수 있는 까닭은 무엇인가요?","options":[{"t":"들어가는 공기(산소)의 양에 따라 연소가 활발해지거나 약해지기 때문에","correct":true},{"t":"화로의 온도를 발화점 아래로만 유지하기 때문에","mis":"SC6-2-u2-X14"},{"t":"탈 물질을 더 넣어 주기 때문에","mis":"SC6-2-u2-X15"},{"t":"산소가 많을수록 불이 약해지기 때문에","mis":"SC6-2-u2-X15"}],"explanation":["공기가 드나들어요.","산소의 양이 달라져요.","연소의 세기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#8','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C6',4,'mc','auto','로켓을 발사하기 위해 꼭 갖추어야 할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C6","difficulty":4,"kind":"mc","stem":"로켓을 발사하기 위해 꼭 갖추어야 할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탈 물질, 산소, 발화점 이상의 온도를 모두 만족해야 한다","correct":true},{"t":"탈 물질만 많으면 산소는 없어도 된다","mis":"SC6-2-u2-X14"},{"t":"발화점 미만의 온도를 유지해야 한다","mis":"SC6-2-u2-X14"},{"t":"산소만 있으면 탈 물질은 없어도 된다","mis":"SC6-2-u2-X14"}],"explanation":["연소에 필요한 조건을 떠올려요.","셋 모두예요.","모두 만족해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#9','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C7',4,'mc','auto','촛불을 작은 유리컵으로 덮었더니 곧 꺼졌어요. 연소의 조건과 이어 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X14','SC6-2-u2-X15']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C7","difficulty":4,"kind":"mc","stem":"촛불을 작은 유리컵으로 덮었더니 곧 꺼졌어요. 연소의 조건과 이어 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"컵 안의 산소가 연소할 수 있을 만큼 충분하지 않게 되어 꺼졌다","correct":true},{"t":"컵 안의 산소가 하나도 남지 않아 꺼졌다","mis":"SC6-2-u2-X16"},{"t":"컵이 양초를 모두 없애 꺼졌다","mis":"SC6-2-u2-X14"},{"t":"컵 안이 더 뜨거워져 꺼졌다","mis":"SC6-2-u2-X15"}],"explanation":["아크릴 통 실험과 같아요.","산소가 남아 있어도 꺼져요.","충분하지 않아서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L04_challenge#10','sci',6,2,'u2','L04','g6_2_sci_u2_L04_challenge','lesson_challenge','SC6-2-u2-C6',4,'essay','teacher','아크릴 통 실험과 철판 실험의 결과를 각각 쓰고, 두 실험으로 알 수 있는 연소의 조건을 정리하세요. 「통 안의 산소가 모두 없어져 꺼졌다」는 생각을 바로잡는 말도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C6","difficulty":4,"kind":"essay","stem":"아크릴 통 실험과 철판 실험의 결과를 각각 쓰고, 두 실험으로 알 수 있는 연소의 조건을 정리하세요. 「통 안의 산소가 모두 없어져 꺼졌다」는 생각을 바로잡는 말도 쓰세요.","answer_guide":{"answer":"예: 아크릴 통 실험에서 양초만 덮은 쪽이 먼저 꺼지고, 산소가 발생하는 비커와 함께 덮은 쪽이 더 오래 탔으므로 연소에는 산소가 필요하다. 철판 실험에서 성냥의 머리 부분에 불이 먼저 붙었으므로 물질이 타려면 발화점 이상의 온도가 필요하고 발화점은 물질마다 다르다. 따라서 연소가 일어나려면 탈 물질, 산소, 발화점 이상의 온도가 모두 필요하다. 촛불이 꺼진 것은 산소가 모두 없어져서가 아니라 연소할 수 있을 만큼 산소가 충분하지 않았기 때문이다.","scoring_points":["두 실험 결과를 바르게 썼는가","연소의 조건 세 가지를 정리했는가","산소가 충분하지 않아 꺼진다고 바로잡았는가"]},"explanation":["두 실험을 나눠 써요.","조건 셋을 모아요.","오개념을 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#1','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',1,'mc','auto','푸른색 염화 코발트 종이는 무엇에 닿으면 붉은색으로 변하나요?',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"mc","stem":"푸른색 염화 코발트 종이는 무엇에 닿으면 붉은색으로 변하나요?","options":[{"t":"물","correct":true},{"t":"산소","mis":"SC6-2-u2-X20"},{"t":"이산화 탄소","mis":"SC6-2-u2-X20"},{"t":"석회수","mis":"SC6-2-u2-X20"}],"explanation":["실험 전에 알아본 성질이에요.","젖으면 색이 변해요.","물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#2','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',1,'mc','auto','촛불이 꺼진 뒤 뚜껑을 닫고 흔든 석회수는 어떻게 되었나요?',ARRAY['SC6-2-u2-X20','SC6-2-u2-X21']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"mc","stem":"촛불이 꺼진 뒤 뚜껑을 닫고 흔든 석회수는 어떻게 되었나요?","options":[{"t":"무색투명하던 석회수가 뿌옇게 흐려졌다","correct":true},{"t":"붉은색으로 변했다","mis":"SC6-2-u2-X20"},{"t":"푸른색으로 변했다","mis":"SC6-2-u2-X20"},{"t":"아무런 변화가 없었다","mis":"SC6-2-u2-X21"}],"explanation":["실험 2를 읽어요.","흐려졌어요.","뿌옇게 흐려졌어요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#3','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',1,'ox','auto','양초가 연소한 뒤에는 물과 이산화 탄소가 생성돼요.',ARRAY['SC6-2-u2-X21']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"ox","stem":"양초가 연소한 뒤에는 물과 이산화 탄소가 생성돼요.","answer":"O","reason_options":[{"t":"염화 코발트 종이가 붉게, 석회수가 뿌옇게 변했기 때문에","correct":true},{"t":"양초가 연소하면 산소만 생기기 때문에","mis":"SC6-2-u2-X21"}],"mis":"SC6-2-u2-X21","explanation":["두 실험을 함께 봐요.","물과 이산화 탄소예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#4','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',1,'sa','auto','이산화 탄소를 만나면 뿌옇게 흐려지는 무색투명한 액체는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"sa","stem":"이산화 탄소를 만나면 뿌옇게 흐려지는 무색투명한 액체는 무엇인가요? 세 글자로 쓰세요.","answer":["석회수"],"explanation":["유리병에 담아 덮었어요.","□□수예요.","석회수예요."],"mis":"SC6-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#5','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',2,'match','auto','확인한 것과 알 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"match","stem":"확인한 것과 알 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"푸른색 염화 코발트 종이가 붉은색으로 변함","r":"물이 생성되었다"},{"l":"석회수가 뿌옇게 흐려짐","r":"이산화 탄소가 생성되었다"},{"l":"셀로판테이프를 붙인 자리가 푸른색 그대로임","r":"물이 닿지 않은 자리와 견줄 수 있다"}],"mis":"SC6-2-u2-X20","explanation":["종이는 물이에요.","석회수는 이산화 탄소예요.","테이프 자리는 비교 대상이에요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#6','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',2,'mc','auto','푸른색 염화 코발트 종이를 아크릴 통에 붙일 때 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u2-X23']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"mc","stem":"푸른색 염화 코발트 종이를 아크릴 통에 붙일 때 알맞은 방법은 어느 것인가요?","options":[{"t":"핀셋으로 집어 셀로판테이프가 종이를 모두 덮지 않게 붙인다","correct":true},{"t":"맨손으로 집어 테이프로 종이 전체를 덮는다","mis":"SC6-2-u2-X23"},{"t":"종이를 물에 적신 뒤 붙인다","mis":"SC6-2-u2-X23"},{"t":"통 바깥쪽 벽면에 붙인다","mis":"SC6-2-u2-X23"}],"explanation":["종이를 바르게 다뤄요.","일부만 테이프로 붙여요.","핀셋으로 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#7','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C10',2,'ox','auto','양초가 연소하면 연소 전의 양초와 전혀 다른 물질이 생겨요.',ARRAY['SC6-2-u2-X22']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"ox","stem":"양초가 연소하면 연소 전의 양초와 전혀 다른 물질이 생겨요.","answer":"O","reason_options":[{"t":"양초가 줄어들고 물과 이산화 탄소가 새로 생기기 때문에","correct":true},{"t":"줄어든 양초가 그대로 통 벽에 붙어 있기 때문에","mis":"SC6-2-u2-X22"}],"mis":"SC6-2-u2-X22","explanation":["연소 뒤 생긴 것을 떠올려요.","양초와 달라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#8','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C9',2,'error','auto','석회수 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X23']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"error","stem":"석회수 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「석회수가 손에 묻어도 실험 끝날 때까지 그냥 두자.」","correct":true,"mis_target":"SC6-2-u2-X23"},{"t":"아린 — 「석회수가 닿으면 흐르는 물로 씻어야 해.」","mis":"SC6-2-u2-X23"},{"t":"세준 — 「꺼진 뒤 뚜껑을 닫고 흔들어 보자.」","mis":"SC6-2-u2-X23"}],"explanation":["석회수는 피부에 닿지 않게 해요.","닿으면 바로 씻어요.","도윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#9','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C10',2,'blank','auto','「연소 과정에서 물질의 (    )이 달라지며, 연소 전과 다른 새로운 물질이 생깁니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X22']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"blank","stem":"「연소 과정에서 물질의 (    )이 달라지며, 연소 전과 다른 새로운 물질이 생깁니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"성질","correct":true},{"t":"이름표","mis":"SC6-2-u2-X22"},{"t":"무게만","mis":"SC6-2-u2-X22"},{"t":"위치","mis":"SC6-2-u2-X22"}],"explanation":["이 단원에서 자주 쓴 말이에요.","새로운 물질이 생겨요.","성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_basic#10','sci',6,2,'u2','L05','g6_2_sci_u2_L05_basic','lesson_basic','SC6-2-u2-C10',3,'mc','auto','양초가 연소한 뒤 양초의 길이가 줄어든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X21','SC6-2-u2-X22']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"mc","stem":"양초가 연소한 뒤 양초의 길이가 줄어든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"양초가 연소하면서 물과 이산화 탄소로 변했기 때문에","correct":true},{"t":"양초가 연소하면서 산소로 변했기 때문에","mis":"SC6-2-u2-X21"},{"t":"성질은 그대로인 채 크기만 작아졌기 때문에","mis":"SC6-2-u2-X22"},{"t":"양초가 아크릴 통 벽에 달라붙었기 때문에","mis":"SC6-2-u2-X22"}],"explanation":["생성된 물질과 이어요.","다른 물질로 바뀌었어요.","물과 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#1','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C10',2,'sa','auto','양초가 연소한 뒤 생성되는 두 물질은 물과 무엇인가요?','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"sa","stem":"양초가 연소한 뒤 생성되는 두 물질은 물과 무엇인가요?","answer":["이산화 탄소","이산화탄소"],"explanation":["석회수가 알려 줬어요.","다섯 글자예요.","이산화 탄소예요."],"mis":"SC6-2-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#2','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',2,'mc','auto','석회수의 변화를 관찰할 때 알맞은 순서는 어느 것인가요?',ARRAY['SC6-2-u2-X23']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"mc","stem":"석회수의 변화를 관찰할 때 알맞은 순서는 어느 것인가요?","options":[{"t":"촛불이 꺼지면 먼저 살펴본 뒤 뚜껑을 닫고 가볍게 흔들며 다시 관찰한다","correct":true},{"t":"촛불을 덮자마자 흔들지 않고 바로 판단한다","mis":"SC6-2-u2-X23"},{"t":"뚜껑을 닫은 채 처음부터 촛불과 덮는다","mis":"SC6-2-u2-X23"},{"t":"유리병을 힘껏 세게 흔들어 깨지는지 본다","mis":"SC6-2-u2-X23"}],"explanation":["흔들어야 잘 보여요.","두 번 관찰해요.","뚜껑을 닫고 흔들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#3','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',3,'error','auto','두 실험의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C9","difficulty":3,"kind":"error","stem":"두 실험의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「석회수가 흐려졌으니 물이 생긴 거야.」","correct":true,"mis_target":"SC6-2-u2-X20"},{"t":"건우 — 「염화 코발트 종이가 붉게 변했으니 물이 생겼어.」","mis":"SC6-2-u2-X20"},{"t":"유진 — 「석회수가 흐려졌으니 이산화 탄소가 생겼어.」","mis":"SC6-2-u2-X20"}],"explanation":["두 지시약이 알려 주는 것이 달라요.","석회수는 이산화 탄소예요.","수아가 잘못 말했어요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#4','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',3,'mc','auto','셀로판테이프를 붙인 자리가 끝까지 푸른색으로 남은 것은 무엇을 보여 주나요?',ARRAY['SC6-2-u2-X20','SC6-2-u2-X21','SC6-2-u2-X23']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C9","difficulty":3,"kind":"mc","stem":"셀로판테이프를 붙인 자리가 끝까지 푸른색으로 남은 것은 무엇을 보여 주나요?","options":[{"t":"물이 닿지 않은 자리는 그대로이므로 붉게 변한 것이 물 때문임을 견줄 수 있다","correct":true},{"t":"종이가 처음부터 붉은 종이였다는 것","mis":"SC6-2-u2-X20"},{"t":"양초가 연소하면 물이 생기지 않는다는 것","mis":"SC6-2-u2-X21"},{"t":"셀로판테이프가 물을 만들었다는 것","mis":"SC6-2-u2-X23"}],"explanation":["같은 종이 안에서 견줘요.","닿은 곳만 변했어요.","물 때문이에요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#5','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C10',3,'ox','auto','양초가 많이 연소할수록 생성되는 물질의 양도 많아져요.',ARRAY['SC6-2-u2-X22']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"ox","stem":"양초가 많이 연소할수록 생성되는 물질의 양도 많아져요.","answer":"O","reason_options":[{"t":"타는 양초가 많을수록 새로 생기는 물과 이산화 탄소도 많아지기 때문에","correct":true},{"t":"연소 뒤 생기는 물질의 양은 늘 같기 때문에","mis":"SC6-2-u2-X22"}],"mis":"SC6-2-u2-X22","explanation":["많이 타면 어떨까요?","생기는 것도 늘어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#6','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C10',3,'mc','auto','난로에 굴뚝이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X10','SC6-2-u2-X22']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"mc","stem":"난로에 굴뚝이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"타면서 생긴 연기와 뜨거운 열이 밖으로 빠져나가게 하려고","correct":true},{"t":"난로 안의 산소를 모두 없애려고","mis":"SC6-2-u2-X16"},{"t":"타는 물질이 늘어나게 하려고","mis":"SC6-2-u2-X10"},{"t":"난로를 차갑게 하려고","mis":"SC6-2-u2-X22"}],"explanation":["타면 무언가 생겨요.","밖으로 내보내요.","연기와 열이 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#7','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',3,'mc','auto','두 실험에서 생성된 물질을 알아내는 데 쓴 것끼리 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C9","difficulty":3,"kind":"mc","stem":"두 실험에서 생성된 물질을 알아내는 데 쓴 것끼리 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"물 — 푸른색 염화 코발트 종이, 이산화 탄소 — 석회수","correct":true},{"t":"물 — 석회수, 이산화 탄소 — 푸른색 염화 코발트 종이","mis":"SC6-2-u2-X20"},{"t":"물 — 아크릴 통, 이산화 탄소 — 셀로판테이프","mis":"SC6-2-u2-X20"},{"t":"물과 이산화 탄소 — 둘 다 석회수","mis":"SC6-2-u2-X20"}],"explanation":["지시약마다 하는 일이 달라요.","종이는 물이에요.","석회수는 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#8','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C10',4,'mc','auto','「양초가 연소하면 산소가 생성된다」는 친구의 말이 옳지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X20','SC6-2-u2-X21','SC6-2-u2-X22']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C10","difficulty":4,"kind":"mc","stem":"「양초가 연소하면 산소가 생성된다」는 친구의 말이 옳지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실험에서 확인한 것은 물과 이산화 탄소였고, 산소는 연소에 쓰이는 것이기 때문에","correct":true},{"t":"산소는 석회수를 뿌옇게 만들기 때문에","mis":"SC6-2-u2-X20"},{"t":"연소 뒤에는 아무 물질도 생기지 않기 때문에","mis":"SC6-2-u2-X21"},{"t":"양초는 연소해도 성질이 그대로이기 때문에","mis":"SC6-2-u2-X22"}],"explanation":["두 실험 결과를 떠올려요.","산소는 필요한 쪽이었어요.","생긴 것은 물과 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#9','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',4,'mc','auto','이 차시의 결과를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X21','SC6-2-u2-X20','SC6-2-u2-X22']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C9","difficulty":4,"kind":"mc","stem":"이 차시의 결과를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"양초가 연소하면 물과 이산화 탄소가 생성되므로 연소 과정에서 물질의 성질이 달라진다","correct":true},{"t":"양초가 연소하면 산소가 생성된다","mis":"SC6-2-u2-X21"},{"t":"양초가 꺼지면 염화 코발트 종이가 붉게 변하므로 물이 사라진다","mis":"SC6-2-u2-X20"},{"t":"양초는 연소해도 크기만 작아질 뿐 같은 물질이다","mis":"SC6-2-u2-X22"}],"explanation":["생성된 물질을 써요.","성질 변화와 이어요.","물과 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L05_challenge#10','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C10',4,'essay','teacher','두 실험의 결과를 쓰고, 그것으로 양초가 연소한 뒤 생성되는 물질을 추리하세요. 양초의 길이가 줄어든 까닭을 연소 전과 후의 성질 변화와 이어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C10","difficulty":4,"kind":"essay","stem":"두 실험의 결과를 쓰고, 그것으로 양초가 연소한 뒤 생성되는 물질을 추리하세요. 양초의 길이가 줄어든 까닭을 연소 전과 후의 성질 변화와 이어 설명하세요.","answer_guide":{"answer":"예: 아크릴 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했으므로 물이 생성되었다. 촛불이 꺼진 뒤 뚜껑을 닫고 흔든 석회수가 뿌옇게 흐려졌으므로 이산화 탄소가 생성되었다. 양초의 길이가 줄어든 것은 양초가 연소하면서 물과 이산화 탄소라는 전혀 다른 물질로 변했기 때문이다. 따라서 연소 과정에서 물질의 성질이 달라진다.","scoring_points":["두 실험 결과를 바르게 썼는가","물과 이산화 탄소를 추리했는가","줄어든 까닭을 성질 변화와 이었는가"]},"explanation":["관찰을 먼저 써요.","알 수 있는 것을 추리해요.","성질 변화와 이어요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#1','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',1,'mc','auto','연소 생성물에 관한 설명으로 옳은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X25']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"mc","stem":"연소 생성물에 관한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"연소 생성물 중 이산화 탄소는 생태계에 피해를 준다","correct":true},{"t":"산소는 연소 생성물이다","mis":"SC6-2-u2-X24"},{"t":"물은 연소 생성물이며 생태계에 피해를 준다","mis":"SC6-2-u2-X24"},{"t":"자동차나 비행기를 이용할 때에는 연소 생성물이 생기지 않는다","mis":"SC6-2-u2-X25"}],"explanation":["양초 실험을 떠올려요.","피해를 주는 것을 골라요.","이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#2','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',1,'mc','auto','산호초가 하얗게 변하는 현상을 무엇이라고 하나요?',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"mc","stem":"산호초가 하얗게 변하는 현상을 무엇이라고 하나요?","options":[{"t":"백화 현상","correct":true},{"t":"단풍 현상","mis":"SC6-2-u2-X24"},{"t":"발화 현상","mis":"SC6-2-u2-X24"},{"t":"증발 현상","mis":"SC6-2-u2-X24"}],"explanation":["하얗게 변해요.","흰 백(白)을 떠올려요.","백화 현상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#3','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',1,'ox','auto','화력 발전소에서 전기를 생산할 때에도 연소가 일어나요.',ARRAY['SC6-2-u2-X25']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"ox","stem":"화력 발전소에서 전기를 생산할 때에도 연소가 일어나요.","answer":"O","reason_options":[{"t":"전기를 만들 때 물질을 태우기 때문에","correct":true},{"t":"발전소에서는 어떤 것도 태우지 않기 때문에","mis":"SC6-2-u2-X25"}],"mis":"SC6-2-u2-X25","explanation":["생활 속 연소를 떠올려요.","발전소도 태워요.","맞는 말이에요."],"asset":{"type":"passage","lines":["자동차나 비행기 같은 교통수단을 운행할 때","가정에서 가스 불로 요리할 때","화력 발전소에서 전기를 생산할 때","쓰레기 소각장에서 폐기물을 처리할 때"],"title":"생활 속에서 연소가 일어나는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#4','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',1,'sa','auto','연소할 때 생성되는 물질을 통틀어 무엇이라고 하나요? (연소 □□□)','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"sa","stem":"연소할 때 생성되는 물질을 통틀어 무엇이라고 하나요? (연소 □□□)","answer":["생성물","연소 생성물"],"explanation":["연소 뒤 생겨요.","세 글자예요.","연소 생성물이에요."],"mis":"SC6-2-u2-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#5','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',2,'match','auto','피해 사례와 그 현황을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"match","stem":"피해 사례와 그 현황을 알맞게 이으세요.","pairs":[{"l":"침엽수림","r":"한꺼번에 말라 죽는다"},{"l":"조개류","r":"껍데기가 얇아지거나 깨진다"},{"l":"산호초","r":"하얗게 변한다"},{"l":"동식물","r":"수가 줄거나 멸종한다"}],"mis":"SC6-2-u2-X24","explanation":["숲과 바다를 가려요.","껍데기는 조개류예요.","하얗게 변하는 것은 산호초예요."],"asset":{"type":"passage","lines":["침엽수림 — 한꺼번에 말라 죽는다.","조개류 — 바다가 산성화되어 껍데기가 얇아지거나 깨진다.","산호초 — 바닷물의 온도가 올라 하얗게 변한다.","동식물 — 기후변화에 적응하지 못해 수가 줄거나 멸종한다."],"title":"이산화 탄소로 인한 생태계 피해 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#6','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',2,'mc','auto','조개류의 껍데기가 얇아지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"mc","stem":"조개류의 껍데기가 얇아지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대기 중 이산화 탄소의 일부가 바다에 녹아 바다가 산성화되기 때문에","correct":true},{"t":"바닷속 산소가 모두 사라졌기 때문에","mis":"SC6-2-u2-X24"},{"t":"조개류가 물을 너무 많이 마셨기 때문에","mis":"SC6-2-u2-X24"},{"t":"바닷물이 차가워졌기 때문에","mis":"SC6-2-u2-X24"}],"explanation":["바다에 녹아들어요.","바다가 산성화돼요.","이산화 탄소 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#7','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',2,'ox','auto','조사한 자료를 사용할 때는 출처를 밝혀요.',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"ox","stem":"조사한 자료를 사용할 때는 출처를 밝혀요.","answer":"O","reason_options":[{"t":"누구의 자료인지 알리고 믿을 만한지 확인할 수 있기 때문에","correct":true},{"t":"출처를 밝히면 자료가 틀려지기 때문에","mis":"SC6-2-u2-X26"}],"mis":"SC6-2-u2-X26","explanation":["자료의 주인을 밝혀요.","확인할 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#8','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',2,'error','auto','조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"error","stem":"조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「찾기 귀찮으니 아무 누리집 글이나 그대로 옮기자.」","correct":true,"mis_target":"SC6-2-u2-X26"},{"t":"소윤 — 「믿을 만한 내용인지 먼저 확인하자.」","mis":"SC6-2-u2-X26"},{"t":"태오 — 「수업과 관련 있는 자료만 찾자.」","mis":"SC6-2-u2-X26"}],"explanation":["믿을 만한지 확인해요.","그대로 옮기면 안 돼요.","현우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#9','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',2,'blank','auto','「이산화 탄소로 인한 생태계 피해를 줄이려면 대기 중으로 배출되는 이산화 탄소의 양을 (    ) 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X25','SC6-2-u2-X24']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"blank","stem":"「이산화 탄소로 인한 생태계 피해를 줄이려면 대기 중으로 배출되는 이산화 탄소의 양을 (    ) 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"줄여야","correct":true},{"t":"늘려야","mis":"SC6-2-u2-X25"},{"t":"그대로 두어야","mis":"SC6-2-u2-X25"},{"t":"모두 산소로 바꿔야","mis":"SC6-2-u2-X24"}],"explanation":["피해를 줄이려고 해요.","원인을 줄여요.","줄여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_basic#10','sci',6,2,'u2','L06','g6_2_sci_u2_L06_basic','lesson_basic','SC6-2-u2-C11',3,'mc','auto','여러 피해 사례를 모아 보니 어떤 공통점이 있나요?',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"mc","stem":"여러 피해 사례를 모아 보니 어떤 공통점이 있나요?","options":[{"t":"모두 이산화 탄소의 배출량이 증가하기 때문에 발생한다","correct":true},{"t":"사례마다 원인이 달라 공통점이 없다","mis":"SC6-2-u2-X24"},{"t":"모두 바다에서만 나타나는 피해이다","mis":"SC6-2-u2-X24"},{"t":"모두 대기 중에서 산소가 줄어들어 생기는 피해이다","mis":"SC6-2-u2-X24"}],"explanation":["곳은 달라도 원인을 봐요.","원인 칸이 같아요.","이산화 탄소 배출량 증가예요."],"asset":{"type":"passage","lines":["침엽수림 — 한꺼번에 말라 죽는다.","조개류 — 바다가 산성화되어 껍데기가 얇아지거나 깨진다.","산호초 — 바닷물의 온도가 올라 하얗게 변한다.","동식물 — 기후변화에 적응하지 못해 수가 줄거나 멸종한다."],"title":"이산화 탄소로 인한 생태계 피해 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#1','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',2,'sa','auto','지리산 자락에서 집단으로 말라 죽는 위험에 처한, 한국에만 분포하는 나무는 무엇인가요? (□□나무)','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"sa","stem":"지리산 자락에서 집단으로 말라 죽는 위험에 처한, 한국에만 분포하는 나무는 무엇인가요? (□□나무)","answer":["구상","구상나무"],"explanation":["침엽수예요.","두 글자예요.","구상나무예요."],"mis":"SC6-2-u2-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#2','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',2,'mc','auto','숲에서 나타나는 피해끼리 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"mc","stem":"숲에서 나타나는 피해끼리 짝지은 것은 어느 것인가요?","options":[{"t":"침엽수림이 말라 죽음, 구상나무 군락이 집단으로 말라 죽음","correct":true},{"t":"조개류 껍데기가 얇아짐, 산호초가 하얗게 변함","mis":"SC6-2-u2-X24"},{"t":"침엽수림이 말라 죽음, 산호초가 하얗게 변함","mis":"SC6-2-u2-X24"},{"t":"조개류 껍데기가 얇아짐, 구상나무가 말라 죽음","mis":"SC6-2-u2-X24"}],"explanation":["나무를 골라요.","바다 피해는 빼요.","침엽수림과 구상나무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#3','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',3,'error','auto','피해 사례를 분석하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X25']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"error","stem":"피해 사례를 분석하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「숲과 바다는 서로 다른 곳이니 원인도 서로 달라.」","correct":true,"mis_target":"SC6-2-u2-X24"},{"t":"채린 — 「곳은 달라도 원인은 이산화 탄소 배출량 증가야.」","mis":"SC6-2-u2-X24"},{"t":"지환 — 「배출량이 계속 늘면 피해가 더 커질 거야.」","mis":"SC6-2-u2-X25"}],"explanation":["원인 칸을 견줘요.","모두 같아요.","은우가 잘못 말했어요."],"asset":{"type":"passage","lines":["침엽수림 — 한꺼번에 말라 죽는다.","조개류 — 바다가 산성화되어 껍데기가 얇아지거나 깨진다.","산호초 — 바닷물의 온도가 올라 하얗게 변한다.","동식물 — 기후변화에 적응하지 못해 수가 줄거나 멸종한다."],"title":"이산화 탄소로 인한 생태계 피해 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#4','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',3,'mc','auto','이산화 탄소의 배출량이 계속 증가하면 생태계는 어떻게 될까요?',ARRAY['SC6-2-u2-X25']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"mc","stem":"이산화 탄소의 배출량이 계속 증가하면 생태계는 어떻게 될까요?","options":[{"t":"기후변화와 해양 산성화가 심해져 피해가 더 커진다","correct":true},{"t":"피해가 저절로 사라진다","mis":"SC6-2-u2-X25"},{"t":"바다 생태계만 좋아진다","mis":"SC6-2-u2-X25"},{"t":"아무런 변화가 없다","mis":"SC6-2-u2-X25"}],"explanation":["지금의 피해를 떠올려요.","원인이 늘어나요.","피해가 더 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#5','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',3,'ox','auto','쓰레기 소각장에서 쓰레기를 태울 때에는 연소 생성물이 생기지 않아요.',ARRAY['SC6-2-u2-X25']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"ox","stem":"쓰레기 소각장에서 쓰레기를 태울 때에는 연소 생성물이 생기지 않아요.","answer":"X","reason_options":[{"t":"쓰레기를 태우는 것도 연소이므로 이산화 탄소가 생기기 때문에","correct":true},{"t":"소각장의 불은 특별해 아무것도 생기지 않기 때문에","mis":"SC6-2-u2-X25"}],"mis":"SC6-2-u2-X25","explanation":["태우는 것은 연소예요.","연소하면 생성물이 생겨요.","생기지 않는 게 아니에요."],"asset":{"type":"passage","lines":["자동차나 비행기 같은 교통수단을 운행할 때","가정에서 가스 불로 요리할 때","화력 발전소에서 전기를 생산할 때","쓰레기 소각장에서 폐기물을 처리할 때"],"title":"생활 속에서 연소가 일어나는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#6','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',3,'mc','auto','조사할 내용이 너무 많아 찾기 어려울 때 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"mc","stem":"조사할 내용이 너무 많아 찾기 어려울 때 알맞은 방법은 어느 것인가요?","options":[{"t":"「이산화 탄소 바다 생태계」처럼 검색어를 좁혀 다시 찾는다","correct":true},{"t":"처음 나온 자료를 확인 없이 그대로 쓴다","mis":"SC6-2-u2-X26"},{"t":"친구가 올린 자료를 내 것처럼 올린다","mis":"SC6-2-u2-X26"},{"t":"수업과 관계없는 자료도 모두 모은다","mis":"SC6-2-u2-X26"}],"explanation":["범위를 줄여요.","숲·바다로 나눠요.","검색어를 좁혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#7','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',3,'mc','auto','생태계 피해를 줄이기 위해 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X25','SC6-2-u2-X27']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"mc","stem":"생태계 피해를 줄이기 위해 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 거리는 자전거를 타거나 걸어 다닌다","correct":true},{"t":"빈방에도 전등을 켜 둔다","mis":"SC6-2-u2-X25"},{"t":"가까운 거리도 자동차로 이동한다","mis":"SC6-2-u2-X25"},{"t":"이산화 탄소를 줄이는 일은 어른에게 맡긴다","mis":"SC6-2-u2-X27"}],"explanation":["연소를 줄여요.","생활 속 실천이에요.","걷거나 자전거를 타요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#8','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',4,'mc','auto','「연소 생성물은 생태계에 어떤 피해를 줄까?」를 조사·분석한 결과를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X25']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C11","difficulty":4,"kind":"mc","stem":"「연소 생성물은 생태계에 어떤 피해를 줄까?」를 조사·분석한 결과를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"생활 곳곳의 연소로 이산화 탄소가 많아지면 숲과 바다 등에서 피해가 나타나므로 배출량을 줄이는 노력이 필요하다","correct":true},{"t":"물이 많아져 생태계에 피해가 생기므로 물을 줄여야 한다","mis":"SC6-2-u2-X24"},{"t":"피해는 바다에서만 나타나므로 숲은 걱정하지 않아도 된다","mis":"SC6-2-u2-X24"},{"t":"연소는 공장에서만 일어나므로 우리와 관계없다","mis":"SC6-2-u2-X25"}],"explanation":["원인과 결과를 이어요.","여러 곳의 피해예요.","배출량을 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#9','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',4,'mc','auto','친구가 공유 플랫폼에 올린 조사 자료에 댓글을 단다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C11","difficulty":4,"kind":"mc","stem":"친구가 공유 플랫폼에 올린 조사 자료에 댓글을 단다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「산호초 사례의 원인과 현황을 출처와 함께 잘 정리했네.」","correct":true},{"t":"「이런 건 나도 하겠다.」","mis":"SC6-2-u2-X26"},{"t":"「그냥 내 자료를 베껴 가.」","mis":"SC6-2-u2-X26"},{"t":"「출처는 빼도 상관없어.」","mis":"SC6-2-u2-X26"}],"explanation":["긍정적인 피드백이에요.","잘한 점을 말해요.","존중하는 댓글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L06_challenge#10','sci',6,2,'u2','L06','g6_2_sci_u2_L06_challenge','lesson_challenge','SC6-2-u2-C11',4,'essay','teacher','피해 사례 두 가지를 골라 원인과 현황을 쓰고, 여러 사례의 공통점을 분석한 뒤 생태계 피해를 줄이기 위해 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C11","difficulty":4,"kind":"essay","stem":"피해 사례 두 가지를 골라 원인과 현황을 쓰고, 여러 사례의 공통점을 분석한 뒤 생태계 피해를 줄이기 위해 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 침엽수림은 이산화 탄소가 많아져 기후변화가 생기면서 한꺼번에 말라 죽는다. 조개류는 이산화 탄소의 일부가 바다에 녹아 바다가 산성화되어 껍데기가 얇아지거나 깨진다. 피해가 나타나는 곳은 숲과 바다로 다르지만 모두 이산화 탄소의 배출량이 증가하기 때문에 발생한다. 나는 가까운 거리는 걸어 다니고 빈방의 전등을 꺼서 이산화 탄소의 배출량을 줄이겠다.","scoring_points":["두 사례의 원인과 현황을 썼는가","공통점을 이산화 탄소 배출량 증가로 분석했는가","배출량을 줄이는 실천을 썼는가"]},"explanation":["사례 둘을 골라요.","공통 원인을 찾아요.","나의 실천을 써요."],"asset":{"type":"passage","lines":["침엽수림 — 한꺼번에 말라 죽는다.","조개류 — 바다가 산성화되어 껍데기가 얇아지거나 깨진다.","산호초 — 바닷물의 온도가 올라 하얗게 변한다.","동식물 — 기후변화에 적응하지 못해 수가 줄거나 멸종한다."],"title":"이산화 탄소로 인한 생태계 피해 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#1','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',1,'mc','auto','이산화 탄소로 인한 생태계 피해를 줄이려면 무엇을 줄여야 하나요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X27']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C12","difficulty":1,"kind":"mc","stem":"이산화 탄소로 인한 생태계 피해를 줄이려면 무엇을 줄여야 하나요?","options":[{"t":"대기 중으로 배출되는 이산화 탄소의 양","correct":true},{"t":"대기 중으로 배출되는 산소의 양","mis":"SC6-2-u2-X24"},{"t":"우리가 마시는 물의 양","mis":"SC6-2-u2-X27"},{"t":"공원에 심는 나무의 수","mis":"SC6-2-u2-X27"}],"explanation":["피해의 원인을 떠올려요.","배출량을 줄여요.","이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#2','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',1,'mc','auto','「자동차를 적게 이용하기」의 구체적인 실천 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C12","difficulty":1,"kind":"mc","stem":"「자동차를 적게 이용하기」의 구체적인 실천 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대중교통이나 자전거를 이용하고 가까운 거리는 걸어 다닌다","correct":true},{"t":"음식을 남기지 않고 먹는다","mis":"SC6-2-u2-X27"},{"t":"불필요한 전등을 끈다","mis":"SC6-2-u2-X27"},{"t":"양치 컵을 사용한다","mis":"SC6-2-u2-X27"}],"explanation":["자동차와 관계있는 것을 골라요.","이동 방법이에요.","대중교통·자전거·걷기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#3','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',1,'ox','auto','홍보 자료는 스마트 기기 대신 도화지와 색칠 도구로 만들어도 돼요.',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C12","difficulty":1,"kind":"ox","stem":"홍보 자료는 스마트 기기 대신 도화지와 색칠 도구로 만들어도 돼요.","answer":"O","reason_options":[{"t":"카드 뉴스나 표어는 손으로도 만들 수 있기 때문에","correct":true},{"t":"홍보 자료는 반드시 디자인 플랫폼으로만 만들어야 하기 때문에","mis":"SC6-2-u2-X27"}],"mis":"SC6-2-u2-X27","explanation":["다른 방법도 있어요.","도화지도 돼요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#4','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',1,'sa','auto','짧은 글로 실천을 알리는 홍보 자료의 한 형태로, 두 글자인 것은 무엇인가요?','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C12","difficulty":1,"kind":"sa","stem":"짧은 글로 실천을 알리는 홍보 자료의 한 형태로, 두 글자인 것은 무엇인가요?","answer":["표어"],"explanation":["카드 뉴스와 함께 나왔어요.","짧은 구호예요.","표어예요."],"mis":"SC6-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#5','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',2,'match','auto','제안 활동과 알맞은 홍보 문구를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"match","stem":"제안 활동과 알맞은 홍보 문구를 이으세요.","pairs":[{"l":"자동차를 적게 이용하기","r":"가까운 거리는 걷거나 자전거를 이용해요"},{"l":"물 아껴 쓰기","r":"양치 컵을 사용하거나 물을 받아서 사용해요"},{"l":"전기 절약하기","r":"불필요한 전등은 꺼 주세요"},{"l":"재활용품 분리배출하기","r":"라벨과 오염 자국을 제거해요"}],"mis":"SC6-2-u2-X27","explanation":["제안과 문구의 낱말을 견줘요.","물은 양치 컵이에요.","전기는 전등이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#6','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',2,'mc','auto','이산화 탄소를 줄이기 위한 방법이 아닌 것은 어느 것인가요?',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"mc","stem":"이산화 탄소를 줄이기 위한 방법이 아닌 것은 어느 것인가요?","options":[{"t":"일회용품을 더 많이 사용한다","correct":true},{"t":"재생 에너지를 사용한다","mis":"SC6-2-u2-X27"},{"t":"실내 적정 온도를 유지한다","mis":"SC6-2-u2-X27"},{"t":"재활용품을 분리배출한다","mis":"SC6-2-u2-X27"}],"explanation":["줄이는 방법을 골라내요.","일회용품은 줄여야 해요.","더 많이 쓰는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#7','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',2,'ox','auto','다른 사람의 창작물은 허락 없이 가져다 써도 괜찮아요.',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"ox","stem":"다른 사람의 창작물은 허락 없이 가져다 써도 괜찮아요.","answer":"X","reason_options":[{"t":"창작물은 만든 사람의 것이므로 허락을 받고 출처를 밝혀야 하기 때문에","correct":true},{"t":"인터넷에 있는 것은 누구나 마음대로 써도 되기 때문에","mis":"SC6-2-u2-X26"}],"mis":"SC6-2-u2-X26","explanation":["만든 사람이 있어요.","허락이 필요해요.","괜찮지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#8','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',2,'error','auto','댓글을 두고 친구들이 말했어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"error","stem":"댓글을 두고 친구들이 말했어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?","options":[{"t":"준서 — 「글씨가 촌스러워서 보기 싫어.」","correct":true,"mis_target":"SC6-2-u2-X26"},{"t":"하은 — 「실천하기 쉬운 방법이라 좋아.」","mis":"SC6-2-u2-X26"},{"t":"로운 — 「문구가 재미있어서 기억에 남아.」","mis":"SC6-2-u2-X26"}],"explanation":["잘한 점을 칭찬해요.","바르고 고운 말을 써요.","준서의 댓글이 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#9','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',2,'blank','auto','「완성한 홍보 자료는 공유 플랫폼이나 (    ) 등에 올려 공유합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X26']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"blank","stem":"「완성한 홍보 자료는 공유 플랫폼이나 (    ) 등에 올려 공유합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"사회 관계망 서비스","correct":true},{"t":"쓰레기통","mis":"SC6-2-u2-X26"},{"t":"개인 일기장","mis":"SC6-2-u2-X26"},{"t":"유해 사이트","mis":"SC6-2-u2-X26"}],"explanation":["여럿이 볼 수 있는 곳이에요.","안전한 곳이어야 해요.","사회 관계망 서비스예요."],"asset":{"type":"passage","lines":["계획하기 — 방법 조사 → 제안 활동과 실천 방법 정하기 → 자료 형태 정하기","해 보기 — 문구 정하기 → 디자인 플랫폼으로 만들기","나누기 — 공유 플랫폼에 올리기 → 잘한 점을 댓글로 쓰기"],"title":"홍보 자료 만들기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_basic#10','sci',6,2,'u2','L07','g6_2_sci_u2_L07_basic','lesson_basic','SC6-2-u2-C12',3,'mc','auto','홍보 자료로 제안할 실천 방법은 어떻게 정해야 하나요?',ARRAY['SC6-2-u2-X27','SC6-2-u2-X26']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"mc","stem":"홍보 자료로 제안할 실천 방법은 어떻게 정해야 하나요?","options":[{"t":"생활 속에서 실제로 실천할 수 있는 방법으로 정한다","correct":true},{"t":"세상의 모든 자동차를 없애는 방법으로 정한다","mis":"SC6-2-u2-X27"},{"t":"꾸미기 쉬운 방법으로만 정한다","mis":"SC6-2-u2-X27"},{"t":"다른 모둠이 정한 방법을 그대로 가져온다","mis":"SC6-2-u2-X26"}],"explanation":["누구나 할 수 있어야 해요.","생활 속 행동이에요.","실천할 수 있게 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#1','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',2,'sa','auto','여러 장의 그림과 짧은 글로 소식을 전하는 홍보 자료의 형태는 무엇인가요? (카드 □□)','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"sa","stem":"여러 장의 그림과 짧은 글로 소식을 전하는 홍보 자료의 형태는 무엇인가요? (카드 □□)","answer":["뉴스","카드 뉴스","카드뉴스"],"explanation":["표어와 함께 나왔어요.","두 글자예요.","카드 뉴스예요."],"mis":"SC6-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#2','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',2,'mc','auto','실천하기 어려운 제안은 어느 것인가요?',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C12","difficulty":2,"kind":"mc","stem":"실천하기 어려운 제안은 어느 것인가요?","options":[{"t":"집 안의 전기를 일 년 내내 한 번도 쓰지 않기","correct":true},{"t":"가까운 거리는 걸어 다니기","mis":"SC6-2-u2-X27"},{"t":"양치할 때 양치 컵 사용하기","mis":"SC6-2-u2-X27"},{"t":"사용하지 않는 플러그 뽑아 두기","mis":"SC6-2-u2-X27"}],"explanation":["생활 속에서 할 수 있나요?","너무 지나친 것을 찾아요.","전기를 일 년 내내 안 쓰기는 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#3','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',3,'mc','auto','홍보 문구를 새로 떠올리기 어려울 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u2-X26','SC6-2-u2-X27']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"mc","stem":"홍보 문구를 새로 떠올리기 어려울 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"기존의 생각에 더하거나 빼는 변형으로 자신만의 생각을 정리해 제안한다","correct":true},{"t":"다른 모둠의 문구를 그대로 가져와 쓴다","mis":"SC6-2-u2-X26"},{"t":"인터넷에서 찾은 문구를 출처 없이 올린다","mis":"SC6-2-u2-X26"},{"t":"문구는 대충 정하고 꾸미는 데 시간을 쓴다","mis":"SC6-2-u2-X27"}],"explanation":["그대로 쓰지 않아요.","조금 바꿔 내 생각으로 만들어요.","변형으로 새롭게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#4','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',3,'error','auto','모둠 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X27','SC6-2-u2-X26']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"error","stem":"모둠 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「화려하게 많이 꾸밀수록 좋은 홍보 자료야.」","correct":true,"mis_target":"SC6-2-u2-X27"},{"t":"가온 — 「실천 방법이 잘 드러나게 만들자.」","mis":"SC6-2-u2-X27"},{"t":"라희 — 「참고한 자료는 출처를 밝히자.」","mis":"SC6-2-u2-X26"}],"explanation":["평가하는 것은 내용이에요.","꾸밈이 먼저가 아니에요.","예준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#5','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',3,'ox','auto','이산화 탄소의 배출량을 줄이려면 한 사람이 한 번만 노력하면 충분해요.',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"ox","stem":"이산화 탄소의 배출량을 줄이려면 한 사람이 한 번만 노력하면 충분해요.","answer":"X","reason_options":[{"t":"여러 사람이 함께 생활 속에서 꾸준히 실천해야 하기 때문에","correct":true},{"t":"한 번의 큰 노력으로 모든 배출이 멈추기 때문에","mis":"SC6-2-u2-X27"}],"mis":"SC6-2-u2-X27","explanation":["누가, 얼마나 오래 할까요?","여러 사람이 꾸준히요.","충분하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#6','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',3,'mc','auto','다른 모둠의 홍보 자료를 평가할 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SC6-2-u2-X26','SC6-2-u2-X27']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"mc","stem":"다른 모둠의 홍보 자료를 평가할 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"일상생활에서 실천 가능한 방법이 잘 드러났는지 공정하게 본다","correct":true},{"t":"친한 친구 모둠에만 좋은 점수를 준다","mis":"SC6-2-u2-X26"},{"t":"색을 많이 쓴 자료를 가장 좋은 자료로 고른다","mis":"SC6-2-u2-X27"},{"t":"다른 모둠 자료는 보지 않고 넘어간다","mis":"SC6-2-u2-X26"}],"explanation":["무엇을 보고 평가할까요?","공정하게 봐요.","실천 방법이 잘 드러났는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#7','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',3,'mc','auto','모둠원이 서로 다른 실천 방법으로 홍보 자료를 만들면 좋은 점은 무엇인가요?',ARRAY['SC6-2-u2-X27','SC6-2-u2-X26']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"mc","stem":"모둠원이 서로 다른 실천 방법으로 홍보 자료를 만들면 좋은 점은 무엇인가요?","options":[{"t":"여러 가지 실천 방법을 다양하게 알릴 수 있다","correct":true},{"t":"모두 같은 자료가 되어 비교하기 쉽다","mis":"SC6-2-u2-X27"},{"t":"실천 방법을 고민하지 않아도 된다","mis":"SC6-2-u2-X27"},{"t":"출처를 밝히지 않아도 된다","mis":"SC6-2-u2-X26"}],"explanation":["방법이 여러 가지예요.","다양한 예가 생겨요.","여러 방법을 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#8','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',4,'mc','auto','「물 아껴 쓰기」를 제안하는 모둠이 이산화 탄소와 이어 까닭을 설명할 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X27']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C12","difficulty":4,"kind":"mc","stem":"「물 아껴 쓰기」를 제안하는 모둠이 이산화 탄소와 이어 까닭을 설명할 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물을 깨끗하게 만들고 보내는 데에도 전기가 쓰이므로 물을 아끼면 이산화 탄소 배출을 줄이는 데 도움이 된다","correct":true},{"t":"물을 아끼면 대기 중 산소가 줄어든다","mis":"SC6-2-u2-X24"},{"t":"물은 연소 생성물이라 많이 쓸수록 좋다","mis":"SC6-2-u2-X24"},{"t":"물 절약은 이산화 탄소와 아무 관계가 없다","mis":"SC6-2-u2-X27"}],"explanation":["물과 전기를 이어 봐요.","전기를 만들 때 연소가 일어나요.","그래서 배출을 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#9','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',4,'mc','auto','이 차시의 활동을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X27','SC6-2-u2-X26']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C12","difficulty":4,"kind":"mc","stem":"이 차시의 활동을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"생활 속에서 실천할 수 있는 이산화 탄소 줄이기 방법을 자신만의 문구로 홍보 자료를 만들어 공유하고 서로 칭찬한다","correct":true},{"t":"꾸밈이 가장 화려한 자료를 만든 모둠이 이긴다","mis":"SC6-2-u2-X27"},{"t":"다른 모둠의 자료를 모아 그대로 다시 올린다","mis":"SC6-2-u2-X26"},{"t":"홍보 자료를 만든 뒤 아무와도 나누지 않는다","mis":"SC6-2-u2-X26"}],"explanation":["계획–해 보기–나누기예요.","실천 방법이 중심이에요.","공유하고 칭찬해요."],"asset":{"type":"passage","lines":["계획하기 — 방법 조사 → 제안 활동과 실천 방법 정하기 → 자료 형태 정하기","해 보기 — 문구 정하기 → 디자인 플랫폼으로 만들기","나누기 — 공유 플랫폼에 올리기 → 잘한 점을 댓글로 쓰기"],"title":"홍보 자료 만들기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L07_challenge#10','sci',6,2,'u2','L07','g6_2_sci_u2_L07_challenge','lesson_challenge','SC6-2-u2-C12',4,'essay','teacher','이산화 탄소를 줄이는 제안 활동을 하나 정해 구체적인 실천 방법 두 가지와 홍보 문구를 쓰고, 그 방법이 생활 속에서 실천 가능한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C12","difficulty":4,"kind":"essay","stem":"이산화 탄소를 줄이는 제안 활동을 하나 정해 구체적인 실천 방법 두 가지와 홍보 문구를 쓰고, 그 방법이 생활 속에서 실천 가능한 까닭을 쓰세요.","answer_guide":{"answer":"예: 제안 활동은 「전기 절약하기」이다. 구체적인 실천 방법은 교실을 나갈 때 불필요한 전등을 끄기와 사용하지 않는 플러그를 뽑아 두기이다. 홍보 문구는 「나가면서 딸깍! 전등도 쉬게 해 주세요」로 정했다. 전기를 만들 때 연소가 일어나 이산화 탄소가 생기므로 전기를 아끼면 배출량을 줄일 수 있고, 두 방법 모두 누구나 매일 쉽게 할 수 있어 꾸준히 실천할 수 있다.","scoring_points":["제안 활동과 구체적인 실천 방법 두 가지를 썼는가","자신만의 홍보 문구를 썼는가","실천 가능한 까닭과 이산화 탄소를 이어 썼는가"]},"explanation":["활동을 하나 정해요.","방법과 문구를 써요.","실천 가능한 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#1','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',1,'mc','auto','이미 배출된 이산화 탄소에 대해 사람들은 어떤 노력을 하고 있나요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"mc","stem":"이미 배출된 이산화 탄소에 대해 사람들은 어떤 노력을 하고 있나요?","options":[{"t":"생활에 필요한 자원으로 바꾸려는 노력을 한다","correct":true},{"t":"그대로 대기 중에 두고 지켜본다","mis":"SC6-2-u2-X28"},{"t":"더 많이 배출해 두었다가 한꺼번에 처리한다","mis":"SC6-2-u2-X28"},{"t":"이산화 탄소를 산소로 바꾸어 되돌린다","mis":"SC6-2-u2-X28"}],"explanation":["재활용 이야기예요.","자원으로 바꿔요.","쓸모 있게 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#2','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',1,'mc','auto','농작물을 재배할 때 이산화 탄소를 주입하면 좋은 점은 무엇인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"mc","stem":"농작물을 재배할 때 이산화 탄소를 주입하면 좋은 점은 무엇인가요?","options":[{"t":"농작물의 생장 속도와 품질을 높일 수 있다","correct":true},{"t":"농작물을 차갑게 얼려 둘 수 있다","mis":"SC6-2-u2-X28"},{"t":"농작물에 붙은 불을 끌 수 있다","mis":"SC6-2-u2-X28"},{"t":"농작물을 약으로 바꿀 수 있다","mis":"SC6-2-u2-X28"}],"explanation":["식물이 자라는 데 써요.","빨리, 좋게 자라요.","생장 속도와 품질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#3','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',1,'ox','auto','포집한 이산화 탄소로 드라이아이스를 만들어 아이스크림을 차갑게 유지할 수 있어요.',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"ox","stem":"포집한 이산화 탄소로 드라이아이스를 만들어 아이스크림을 차갑게 유지할 수 있어요.","answer":"O","reason_options":[{"t":"드라이아이스로 신선식품이나 아이스크림을 차갑게 유지하기 때문에","correct":true},{"t":"포집한 이산화 탄소는 쓸 곳이 없기 때문에","mis":"SC6-2-u2-X28"}],"mis":"SC6-2-u2-X28","explanation":["차가운 것을 떠올려요.","드라이아이스예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#4','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',1,'sa','auto','배기가스에서 이산화 탄소만 따로 모으는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"sa","stem":"배기가스에서 이산화 탄소만 따로 모으는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["포집"],"explanation":["③단계에 나와요.","붙잡아 모아요.","포집이에요."],"asset":{"type":"passage","lines":["① 배기가스 발생","② 이산화 탄소 흡수","③ 배기가스 중 이산화 탄소만 포집하기","④ 다양한 산업 분야에 활용"],"title":"이산화 탄소를 모으는 차례"},"mis":"SC6-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#5','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',2,'match','auto','포집한 이산화 탄소의 쓰임과 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"match","stem":"포집한 이산화 탄소의 쓰임과 설명을 알맞게 이으세요.","pairs":[{"l":"농작물 재배","r":"생장 속도와 품질을 높인다"},{"l":"드라이아이스","r":"신선식품을 차갑게 유지한다"},{"l":"소화기","r":"만드는 데 활용되기도 한다"},{"l":"의약품","r":"제조하는 데 활용되기도 한다"}],"mis":"SC6-2-u2-X28","explanation":["자라는 것은 농작물이에요.","차가운 것은 드라이아이스예요.","만드는 것과 제조하는 것을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#6','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',2,'mc','auto','이산화 탄소를 모으는 차례에서 맨 처음 단계는 어느 것인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"mc","stem":"이산화 탄소를 모으는 차례에서 맨 처음 단계는 어느 것인가요?","options":[{"t":"배기가스 발생","correct":true},{"t":"다양한 산업 분야에 활용","mis":"SC6-2-u2-X28"},{"t":"이산화 탄소만 포집하기","mis":"SC6-2-u2-X28"},{"t":"이산화 탄소 흡수","mis":"SC6-2-u2-X28"}],"explanation":["연소가 일어나면 무엇이 나올까요?","①단계예요.","배기가스 발생이에요."],"asset":{"type":"passage","lines":["① 배기가스 발생","② 이산화 탄소 흡수","③ 배기가스 중 이산화 탄소만 포집하기","④ 다양한 산업 분야에 활용"],"title":"이산화 탄소를 모으는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#7','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',2,'ox','auto','배기가스에서는 이산화 탄소만 따로 모을 수 없어요.',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"ox","stem":"배기가스에서는 이산화 탄소만 따로 모을 수 없어요.","answer":"X","reason_options":[{"t":"배기가스 중 이산화 탄소만 포집하는 기술이 있기 때문에","correct":true},{"t":"배기가스는 한 가지 물질로만 되어 있기 때문에","mis":"SC6-2-u2-X28"}],"mis":"SC6-2-u2-X28","explanation":["③단계를 떠올려요.","이산화 탄소만 모아요.","모을 수 있어요."],"asset":{"type":"passage","lines":["① 배기가스 발생","② 이산화 탄소 흡수","③ 배기가스 중 이산화 탄소만 포집하기","④ 다양한 산업 분야에 활용"],"title":"이산화 탄소를 모으는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#8','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',2,'error','auto','이산화 탄소 재활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"error","stem":"이산화 탄소 재활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시온 — 「재활용 기술이 있으니 이산화 탄소는 마음껏 내보내도 돼.」","correct":true,"mis_target":"SC6-2-u2-X28"},{"t":"하랑 — 「화력 발전소에서도 이산화 탄소를 분리해 재활용해.」","mis":"SC6-2-u2-X28"},{"t":"다온 — 「배출량을 줄이는 노력도 함께 해야 해.」","mis":"SC6-2-u2-X28"}],"explanation":["두 갈래 노력을 떠올려요.","줄이는 노력도 필요해요.","시온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#9','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',2,'blank','auto','「(    ) 과정에서 이산화 탄소를 포집하는 기술을 개발했습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"blank","stem":"「(    ) 과정에서 이산화 탄소를 포집하는 기술을 개발했습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"가스발전","correct":true},{"t":"얼음 만들기","mis":"SC6-2-u2-X28"},{"t":"빨래 말리기","mis":"SC6-2-u2-X28"},{"t":"나무 심기","mis":"SC6-2-u2-X28"}],"explanation":["발전 과정이에요.","가스를 써요.","가스발전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_basic#10','sci',6,2,'u2','L08','g6_2_sci_u2_L08_basic','lesson_basic','SC6-2-u2-C13',3,'mc','auto','이산화 탄소를 재활용하면 어떤 도움이 될 수 있나요?',ARRAY['SC6-2-u2-X28','SC6-2-u2-X24']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"mc","stem":"이산화 탄소를 재활용하면 어떤 도움이 될 수 있나요?","options":[{"t":"연소 생성물인 이산화 탄소를 생활에 다시 써서 생태계의 피해를 줄이는 데 도움이 된다","correct":true},{"t":"이산화 탄소를 더 많이 배출해도 피해가 없어진다","mis":"SC6-2-u2-X28"},{"t":"연소가 일어나지 않게 된다","mis":"SC6-2-u2-X28"},{"t":"대기 중 산소가 모두 이산화 탄소로 바뀐다","mis":"SC6-2-u2-X24"}],"explanation":["배출된 것을 다시 써요.","피해를 줄여요.","도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#1','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',2,'sa','auto','포집한 이산화 탄소로 만들어 신선식품이나 아이스크림을 차갑게 유지하는 것은 무엇인가요?','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"sa","stem":"포집한 이산화 탄소로 만들어 신선식품이나 아이스크림을 차갑게 유지하는 것은 무엇인가요?","answer":["드라이아이스"],"explanation":["아주 차가워요.","아이스가 들어가요.","드라이아이스예요."],"mis":"SC6-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#2','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',2,'mc','auto','배출량을 줄이는 노력에 해당하는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"mc","stem":"배출량을 줄이는 노력에 해당하는 것은 어느 것인가요?","options":[{"t":"가까운 거리는 걸어 다니기","correct":true},{"t":"배기가스에서 이산화 탄소를 분리해 재활용하기","mis":"SC6-2-u2-X28"},{"t":"포집한 이산화 탄소로 드라이아이스 만들기","mis":"SC6-2-u2-X28"},{"t":"농작물 재배에 이산화 탄소 주입하기","mis":"SC6-2-u2-X28"}],"explanation":["두 갈래를 가려요.","처음부터 덜 내보내요.","걸어 다니기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#3','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',3,'mc','auto','재활용된 이산화 탄소를 내가 이용하는 생각으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"mc","stem":"재활용된 이산화 탄소를 내가 이용하는 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"좋아하는 음료에 이산화 탄소를 녹여 나만의 탄산음료를 만든다","correct":true},{"t":"모아 둔 이산화 탄소를 공기 중에 그냥 내보낸다","mis":"SC6-2-u2-X28"},{"t":"이산화 탄소를 더 많이 만드는 공장을 짓는다","mis":"SC6-2-u2-X28"},{"t":"쓸 곳이 없으니 생각하지 않는다","mis":"SC6-2-u2-X28"}],"explanation":["이용하는 생각이어야 해요.","생활 속에서 써요.","탄산음료를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#4','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',3,'error','auto','포집한 이산화 탄소의 쓰임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"error","stem":"포집한 이산화 탄소의 쓰임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「포집한 이산화 탄소는 쓸 곳이 없어 모두 버려.」","correct":true,"mis_target":"SC6-2-u2-X28"},{"t":"지우 — 「소화기를 만드는 데 쓰이기도 해.」","mis":"SC6-2-u2-X28"},{"t":"민결 — 「의약품을 제조하는 데 쓰이기도 해.」","mis":"SC6-2-u2-X28"}],"explanation":["쓰임이 넷이나 있어요.","버리지 않아요.","태린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#5','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',3,'ox','auto','이산화 탄소를 줄이는 노력과 자원으로 바꾸는 노력은 함께 이루어져야 해요.',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"ox","stem":"이산화 탄소를 줄이는 노력과 자원으로 바꾸는 노력은 함께 이루어져야 해요.","answer":"O","reason_options":[{"t":"이미 배출된 것은 자원으로 바꾸고, 새로 내보내는 양은 줄여야 피해가 줄기 때문에","correct":true},{"t":"재활용 기술만 있으면 줄이는 노력은 필요 없기 때문에","mis":"SC6-2-u2-X28"}],"mis":"SC6-2-u2-X28","explanation":["두 갈래를 떠올려요.","함께 가요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#6','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',3,'mc','auto','화력 발전소에서 이산화 탄소를 분리해 재활용하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X25','SC6-2-u2-X28']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"mc","stem":"화력 발전소에서 이산화 탄소를 분리해 재활용하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전기를 생산할 때 연소로 생기는 이산화 탄소를 자원으로 다시 쓰려고","correct":true},{"t":"발전소에서는 연소가 일어나지 않아서","mis":"SC6-2-u2-X25"},{"t":"이산화 탄소를 산소로 바꾸려고","mis":"SC6-2-u2-X28"},{"t":"더 많은 이산화 탄소를 대기로 보내려고","mis":"SC6-2-u2-X28"}],"explanation":["발전소에서도 연소가 일어나요.","생긴 것을 모아요.","다시 쓰려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#7','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',3,'match','auto','노력과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"match","stem":"노력과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"불필요한 전등 끄기","r":"배출량을 줄이는 노력"},{"l":"배기가스에서 이산화 탄소 포집하기","r":"자원으로 바꾸려는 노력"},{"l":"포집한 이산화 탄소로 소화기 만들기","r":"자원으로 활용하는 쓰임"}],"mis":"SC6-2-u2-X28","explanation":["덜 내보내는 것이 있어요.","모으는 것이 있어요.","쓰는 것이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#8','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',4,'mc','auto','「재활용 기술이 있으니 이산화 탄소를 마음껏 배출해도 된다」는 생각이 옳지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X28']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C13","difficulty":4,"kind":"mc","stem":"「재활용 기술이 있으니 이산화 탄소를 마음껏 배출해도 된다」는 생각이 옳지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"재활용은 이미 배출된 것을 다시 쓰는 노력이고, 배출량을 줄이는 노력과 함께 해야 생태계 피해를 줄일 수 있기 때문에","correct":true},{"t":"이산화 탄소는 생태계에 아무 피해를 주지 않기 때문에","mis":"SC6-2-u2-X24"},{"t":"포집한 이산화 탄소는 쓸 곳이 없기 때문에","mis":"SC6-2-u2-X28"},{"t":"재활용 기술은 산소만 모으기 때문에","mis":"SC6-2-u2-X28"}],"explanation":["두 갈래를 나란히 떠올려요.","재활용만으로는 부족해요.","함께 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#9','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',4,'mc','auto','이 차시를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C13","difficulty":4,"kind":"mc","stem":"이 차시를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"배기가스에서 이산화 탄소만 포집해 농작물 재배·드라이아이스·소화기·의약품 등에 활용하며, 배출량을 줄이는 노력과 함께 지속가능한 사회를 만든다","correct":true},{"t":"이산화 탄소는 다시 쓸 수 없으므로 모두 버린다","mis":"SC6-2-u2-X28"},{"t":"재활용하면 되므로 배출을 줄일 필요가 없다","mis":"SC6-2-u2-X28"},{"t":"이산화 탄소는 소화기에만 쓰인다","mis":"SC6-2-u2-X28"}],"explanation":["모으는 차례와 쓰임을 떠올려요.","두 갈래 노력이에요.","지속가능한 사회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_L08_challenge#10','sci',6,2,'u2','L08','g6_2_sci_u2_L08_challenge','lesson_challenge','SC6-2-u2-C13',4,'essay','teacher','배기가스에서 이산화 탄소를 모아 활용하는 차례를 쓰고, 포집한 이산화 탄소의 쓰임 두 가지를 쓰세요. 재활용된 이산화 탄소를 내가 이용한다면 어디에 쓸지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u2-C13","difficulty":4,"kind":"essay","stem":"배기가스에서 이산화 탄소를 모아 활용하는 차례를 쓰고, 포집한 이산화 탄소의 쓰임 두 가지를 쓰세요. 재활용된 이산화 탄소를 내가 이용한다면 어디에 쓸지도 쓰세요.","answer_guide":{"answer":"예: 연소로 배기가스가 발생하면 이산화 탄소를 흡수하고, 배기가스 중 이산화 탄소만 포집해 다양한 산업 분야에 활용한다. 포집한 이산화 탄소는 농작물 재배에 주입해 생장 속도와 품질을 높이고, 드라이아이스로 만들어 신선식품을 차갑게 유지한다. 나는 재활용된 이산화 탄소를 좋아하는 우유에 녹여 나만의 탄산음료를 만들고 싶다.","scoring_points":["포집과 활용 차례를 바르게 썼는가","쓰임 두 가지를 바르게 썼는가","재활용된 이산화 탄소를 이용하는 생각을 썼는가"]},"explanation":["차례를 써요.","쓰임을 둘 써요.","나의 생각을 써요."],"asset":{"type":"passage","lines":["① 배기가스 발생","② 이산화 탄소 흡수","③ 배기가스 중 이산화 탄소만 포집하기","④ 다양한 산업 분야에 활용"],"title":"이산화 탄소를 모으는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#1','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C3',1,'mc','auto','별빛반 일지 ①에서 물질의 성질이 변한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X07','SC6-2-u2-X06','SC6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C3","difficulty":1,"kind":"mc","stem":"별빛반 일지 ①에서 물질의 성질이 변한 것은 어느 것인가요?","options":[{"t":"㉡ 제빵 소다에 식초를 부은 것","correct":true},{"t":"㉠ 우유에 코코아 가루를 섞은 것","mis":"SC6-2-u2-X07"},{"t":"㉢ 물에 소금을 녹인 것","mis":"SC6-2-u2-X06"},{"t":"세 가지 모두 성질이 변하지 않았다","mis":"SC6-2-u2-X03"}],"explanation":["새로운 모습이 생긴 것을 찾아요.","기포가 생겼어요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#2','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C4',1,'mc','auto','물질이 탈 때 불꽃 주변은 어떻게 되나요?',ARRAY['SC6-2-u2-X08']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"mc","stem":"물질이 탈 때 불꽃 주변은 어떻게 되나요?","options":[{"t":"밝아지고 따뜻해진다","correct":true},{"t":"어두워지고 차가워진다","mis":"SC6-2-u2-X08"},{"t":"밝아지지만 차가워진다","mis":"SC6-2-u2-X08"},{"t":"아무런 변화가 없다","mis":"SC6-2-u2-X08"}],"explanation":["촛불을 떠올려요.","빛과 열이 나요.","밝고 따뜻해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#3','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C6',1,'mc','auto','연소가 일어나는 데 필요한 조건을 바르게 모은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"mc","stem":"연소가 일어나는 데 필요한 조건을 바르게 모은 것은 어느 것인가요?","options":[{"t":"탈 물질, 산소, 발화점 이상의 온도","correct":true},{"t":"탈 물질, 산소, 발화점 미만의 온도","mis":"SC6-2-u2-X14"},{"t":"탈 물질, 이산화 탄소, 발화점 이상의 온도","mis":"SC6-2-u2-X14"},{"t":"탈 물질, 이산화 탄소, 발화점 미만의 온도","mis":"SC6-2-u2-X14"}],"explanation":["세 가지예요.","산소와 온도를 확인해요.","발화점 이상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#4','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C7',1,'mc','auto','별빛반 일지 ③에서 부채질을 했더니 불이 세진 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X15','SC6-2-u2-X14']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C7","difficulty":1,"kind":"mc","stem":"별빛반 일지 ③에서 부채질을 했더니 불이 세진 까닭은 무엇인가요?","options":[{"t":"산소가 더 공급되었기 때문에","correct":true},{"t":"장작의 온도가 낮아졌기 때문에","mis":"SC6-2-u2-X15"},{"t":"장작이 모두 없어졌기 때문에","mis":"SC6-2-u2-X14"},{"t":"이산화 탄소가 더 들어갔기 때문에","mis":"SC6-2-u2-X14"}],"explanation":["부채질은 공기를 보내요.","산소가 들어가요.","연소가 활발해져요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#5','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C8',1,'mc','auto','철판 실험에서 성냥의 머리 부분과 나무 부분 가운데 발화점이 더 낮은 쪽은 어느 것인가요?',ARRAY['SC6-2-u2-X17']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":1,"kind":"mc","stem":"철판 실험에서 성냥의 머리 부분과 나무 부분 가운데 발화점이 더 낮은 쪽은 어느 것인가요?","options":[{"t":"성냥의 머리 부분","correct":true},{"t":"성냥의 나무 부분","mis":"SC6-2-u2-X17"},{"t":"둘의 발화점은 같다","mis":"SC6-2-u2-X17"},{"t":"알 수 없다","mis":"SC6-2-u2-X17"}],"explanation":["먼저 불이 붙은 쪽이에요.","낮은 온도에서 붙어요.","머리 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#6','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C9',1,'mc','auto','양초가 연소한 뒤 생성되는 물질을 바르게 모은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X21','SC6-2-u2-X20']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"mc","stem":"양초가 연소한 뒤 생성되는 물질을 바르게 모은 것은 어느 것인가요?","options":[{"t":"물과 이산화 탄소","correct":true},{"t":"산소와 물","mis":"SC6-2-u2-X21"},{"t":"산소와 이산화 탄소","mis":"SC6-2-u2-X21"},{"t":"석회수와 물","mis":"SC6-2-u2-X20"}],"explanation":["두 지시약이 알려 줬어요.","종이는 물이에요.","석회수는 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#7','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C11',1,'mc','auto','연소 생성물 가운데 많아지면 생태계에 피해를 주는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"mc","stem":"연소 생성물 가운데 많아지면 생태계에 피해를 주는 것은 어느 것인가요?","options":[{"t":"이산화 탄소","correct":true},{"t":"산소","mis":"SC6-2-u2-X24"},{"t":"물","mis":"SC6-2-u2-X24"},{"t":"석회수","mis":"SC6-2-u2-X24"}],"explanation":["대기 중에 많아지면 문제예요.","양초 연소 뒤 석회수가 알려 줬어요.","이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#8','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C1',1,'mc','auto','향불을 넣었을 때 불씨가 커진 병에 들어 있던 가루는 무엇인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"mc","stem":"향불을 넣었을 때 불씨가 커진 병에 들어 있던 가루는 무엇인가요?","options":[{"t":"산소계 표백제","correct":true},{"t":"소금","mis":"SC6-2-u2-X01"},{"t":"탄산 칼슘","mis":"SC6-2-u2-X01"},{"t":"제빵 소다","mis":"SC6-2-u2-X01"}],"explanation":["불씨를 살린 병이에요.","하나뿐이었어요.","산소계 표백제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#9','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C3',2,'mc','auto','별빛반 일지 ①의 ㉢에서 소금의 성질이 그대로라고 말할 수 있는 근거는 어느 것인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"mc","stem":"별빛반 일지 ①의 ㉢에서 소금의 성질이 그대로라고 말할 수 있는 근거는 어느 것인가요?","options":[{"t":"소금이 보이지 않아도 짠맛이 났다","correct":true},{"t":"소금이 눈에 보이지 않았다","mis":"SC6-2-u2-X06"},{"t":"소금물이 투명했다","mis":"SC6-2-u2-X06"},{"t":"물의 양이 조금 늘었다","mis":"SC6-2-u2-X06"}],"explanation":["성질을 보여 주는 것을 골라요.","맛이 남았어요.","짠맛이에요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#10','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C4',2,'mc','auto','별빛반 일지 ②에서 양초 랜턴과 알코올램프가 다른 점은 어느 것인가요?',ARRAY['SC6-2-u2-X09','SC6-2-u2-X10']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"mc","stem":"별빛반 일지 ②에서 양초 랜턴과 알코올램프가 다른 점은 어느 것인가요?","options":[{"t":"불꽃의 색깔","correct":true},{"t":"주변이 밝아지는 것","mis":"SC6-2-u2-X09"},{"t":"가까울수록 따뜻한 것","mis":"SC6-2-u2-X09"},{"t":"시간이 지나면 양이 줄어드는 것","mis":"SC6-2-u2-X10"}],"explanation":["두 줄을 견줘요.","하나만 달라요.","색깔이에요."],"asset":{"type":"passage","lines":["양초 랜턴 — 불꽃 노란색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","알코올램프 — 불꽃 푸른색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","한 시간 뒤 — 양초 길이 8 cm → 6 cm, 알코올의 양도 줄었다."],"title":"별빛반 일지 ② 랜턴 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#11','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C7',2,'mc','auto','별빛반 일지 ③의 ㉣에서 불씨가 꺼진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X15','SC6-2-u2-X14']::text[],false,'{"seq":11,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"mc","stem":"별빛반 일지 ③의 ㉣에서 불씨가 꺼진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뚜껑 안의 산소가 연소할 수 있을 만큼 충분하지 않게 되었기 때문에","correct":true},{"t":"뚜껑 안의 산소가 하나도 남지 않았기 때문에","mis":"SC6-2-u2-X16"},{"t":"뚜껑이 장작의 온도를 높였기 때문에","mis":"SC6-2-u2-X15"},{"t":"뚜껑이 장작을 모두 없앴기 때문에","mis":"SC6-2-u2-X14"}],"explanation":["아크릴 통 실험과 같아요.","산소가 모자라요.","충분하지 않아서예요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#12','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C9',2,'mc','auto','별빛반 일지 ⑤에서 석회수가 뿌옇게 흐려진 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X20','SC6-2-u2-X21','SC6-2-u2-X22']::text[],false,'{"seq":12,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑤에서 석회수가 뿌옇게 흐려진 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"이산화 탄소가 생성되었다","correct":true},{"t":"물이 생성되었다","mis":"SC6-2-u2-X20"},{"t":"산소가 생성되었다","mis":"SC6-2-u2-X21"},{"t":"양초가 늘어났다","mis":"SC6-2-u2-X22"}],"explanation":["석회수의 성질이에요.","이산화 탄소를 만나요.","이산화 탄소가 생겼어요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#13','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C10',2,'mc','auto','연소 전의 물질과 연소 후의 물질을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X21','SC6-2-u2-X22']::text[],false,'{"seq":13,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"mc","stem":"연소 전의 물질과 연소 후의 물질을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"연소 전 양초 — 연소 후 물과 이산화 탄소","correct":true},{"t":"연소 전 양초 — 연소 후 산소","mis":"SC6-2-u2-X21"},{"t":"연소 전 물 — 연소 후 양초","mis":"SC6-2-u2-X22"},{"t":"연소 전 양초 — 연소 후 같은 양초","mis":"SC6-2-u2-X22"}],"explanation":["전과 후를 가려요.","새 물질이 생겨요.","물과 이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#14','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C11',2,'mc','auto','별빛반 일지 ⑦에서 야영장 화로와 자동차를 함께 적은 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X25']::text[],false,'{"seq":14,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑦에서 야영장 화로와 자동차를 함께 적은 까닭은 무엇인가요?","options":[{"t":"둘 다 연소가 일어나 이산화 탄소가 생기는 곳이기 때문에","correct":true},{"t":"둘 다 산소를 만드는 곳이기 때문에","mis":"SC6-2-u2-X24"},{"t":"둘 다 연소가 일어나지 않는 곳이기 때문에","mis":"SC6-2-u2-X25"},{"t":"둘 다 물만 생기는 곳이기 때문에","mis":"SC6-2-u2-X24"}],"explanation":["안내판 첫 줄을 읽어요.","연소가 일어나요.","이산화 탄소가 생겨요."],"asset":{"type":"passage","lines":["야영장 화로와 자동차에서도 연소가 일어나 이산화 탄소가 생겨요.","이산화 탄소가 많아지면 숲과 바다의 생태계가 피해를 입어요.","우리 야영장의 약속 — 가까운 곳은 걸어서, 장작은 필요한 만큼만!"],"title":"별빛반 일지 ⑦ 야영장 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#15','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C13',2,'mc','auto','별빛반 일지 ⑧에서 비닐하우스 농장으로 이산화 탄소를 보내는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":15,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑧에서 비닐하우스 농장으로 이산화 탄소를 보내는 까닭은 무엇인가요?","options":[{"t":"채소의 생장 속도와 품질을 높이려고","correct":true},{"t":"채소를 얼려 두려고","mis":"SC6-2-u2-X28"},{"t":"채소에 붙은 불을 끄려고","mis":"SC6-2-u2-X28"},{"t":"채소를 약으로 바꾸려고","mis":"SC6-2-u2-X28"}],"explanation":["농작물 재배예요.","잘 자라게 해요.","생장 속도와 품질이에요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#16','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C1',2,'mc','auto','불씨 살리기 활동에서 네 병에 모두 따뜻한 물을 넣은 것은 무엇을 같게 한 것인가요?',ARRAY['SC6-2-u2-X01','SC6-2-u2-X02']::text[],false,'{"seq":16,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"mc","stem":"불씨 살리기 활동에서 네 병에 모두 따뜻한 물을 넣은 것은 무엇을 같게 한 것인가요?","options":[{"t":"물질 말고 나머지 조건","correct":true},{"t":"불씨를 살리는 물질","mis":"SC6-2-u2-X01"},{"t":"병마다 다른 물의 온도","mis":"SC6-2-u2-X01"},{"t":"향불의 크기를 다르게 한 것","mis":"SC6-2-u2-X02"}],"explanation":["다른 것은 가루뿐이에요.","물은 같아요.","나머지 조건을 같게 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#17','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C7',3,'mc','auto','별빛반 일지 ④에서 작은 통의 촛불이 먼저 꺼진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X15']::text[],false,'{"seq":17,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"mc","stem":"별빛반 일지 ④에서 작은 통의 촛불이 먼저 꺼진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 통 안의 산소가 더 빨리 연소할 수 있을 만큼 충분하지 않게 되었기 때문에","correct":true},{"t":"작은 통 안의 산소가 하나도 남지 않았기 때문에","mis":"SC6-2-u2-X16"},{"t":"작은 통 안의 양초가 더 컸기 때문에","mis":"SC6-2-u2-X15"},{"t":"작은 통이 더 시원했기 때문에","mis":"SC6-2-u2-X15"}],"explanation":["통이 작으면 공기도 적어요.","산소도 적어요.","더 빨리 모자라져요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙이고 크기가 다른 투명한 통으로 동시에 덮었다.","작은 통의 촛불이 먼저 꺼지고, 큰 통의 촛불이 나중에 꺼졌다.","선생님이 측정기로 재어 보니 꺼진 뒤에도 두 통 안에 산소가 남아 있었다."],"title":"별빛반 일지 ④ 통 크기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#18','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C8',3,'mc','auto','같은 거리에서 가열했는데 성냥의 머리 부분에 먼저 불이 붙었어요. 그 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X19','SC6-2-u2-X17','SC6-2-u2-X14']::text[],false,'{"seq":18,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"mc","stem":"같은 거리에서 가열했는데 성냥의 머리 부분에 먼저 불이 붙었어요. 그 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"머리 부분이 나무 부분보다 낮은 온도에서 타기 시작하기 때문에","correct":true},{"t":"머리 부분이 열을 덜 받았기 때문에","mis":"SC6-2-u2-X19"},{"t":"두 부분의 발화점이 같기 때문에","mis":"SC6-2-u2-X17"},{"t":"나무 부분에는 산소가 닿지 않았기 때문에","mis":"SC6-2-u2-X14"}],"explanation":["같은 열을 받았어요.","발화점이 달라요.","머리 부분이 더 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#19','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C10',3,'mc','auto','별빛반 일지 ⑥에서 서준의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X22','SC6-2-u2-X09','SC6-2-u2-X21']::text[],false,'{"seq":19,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑥에서 서준의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"타는 동안 물과 이산화 탄소가 새로 생긴 것이 확인되었다","correct":true},{"t":"양초가 녹아 촛농이 흘렀다","mis":"SC6-2-u2-X22"},{"t":"양초 불꽃이 노란색이었다","mis":"SC6-2-u2-X09"},{"t":"양초가 산소로 바뀌는 것을 보았다","mis":"SC6-2-u2-X21"}],"explanation":["일지 ⑤를 떠올려요.","새 물질이 생겼어요.","크기만 작아진 게 아니에요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#20','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C3',3,'mc','auto','별빛반 일지 ⑥의 라온의 말을 바로잡는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":20,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑥의 라온의 말을 바로잡는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물을 증발시켜 소금을 다시 얻어 보인다","correct":true},{"t":"소금물을 더 휘저어 본다","mis":"SC6-2-u2-X06"},{"t":"소금물에 소금을 더 넣는다","mis":"SC6-2-u2-X06"},{"t":"소금물을 빛에 비추어 투명한지 본다","mis":"SC6-2-u2-X06"}],"explanation":["실험 물질은 맛보지 않아요.","물을 없애면 남아요.","증발시켜 보여 줘요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#21','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C6',3,'mc','auto','로켓을 발사하기 위해 연소의 조건을 모두 만족해야 한다는 것은 무슨 뜻인가요?',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":21,"concept":"SC6-2-u2-C6","difficulty":3,"kind":"mc","stem":"로켓을 발사하기 위해 연소의 조건을 모두 만족해야 한다는 것은 무슨 뜻인가요?","options":[{"t":"탈 물질, 산소, 발화점 이상의 온도가 하나도 빠짐없이 있어야 한다","correct":true},{"t":"탈 물질만 많으면 된다","mis":"SC6-2-u2-X14"},{"t":"산소만 충분하면 된다","mis":"SC6-2-u2-X14"},{"t":"온도는 낮을수록 좋다","mis":"SC6-2-u2-X14"}],"explanation":["조건이 셋이에요.","모두 있어야 해요.","빠짐없이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#22','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C12',3,'mc','auto','이산화 탄소를 줄이는 홍보 자료를 평가할 때 가장 중요하게 볼 것은 어느 것인가요?',ARRAY['SC6-2-u2-X27','SC6-2-u2-X26']::text[],false,'{"seq":22,"concept":"SC6-2-u2-C12","difficulty":3,"kind":"mc","stem":"이산화 탄소를 줄이는 홍보 자료를 평가할 때 가장 중요하게 볼 것은 어느 것인가요?","options":[{"t":"생활 속에서 실천 가능한 방법이 잘 드러났는지","correct":true},{"t":"색을 얼마나 많이 썼는지","mis":"SC6-2-u2-X27"},{"t":"글자가 얼마나 큰지","mis":"SC6-2-u2-X27"},{"t":"다른 모둠 자료와 똑같은지","mis":"SC6-2-u2-X26"}],"explanation":["홍보의 목적을 떠올려요.","실천하게 하는 것이에요.","실천 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#23','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C9',4,'mc','auto','별빛반 일지 ②와 ⑤를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-2-u2-X22','SC6-2-u2-X21','SC6-2-u2-X20']::text[],false,'{"seq":23,"concept":"SC6-2-u2-C9","difficulty":4,"kind":"mc","stem":"별빛반 일지 ②와 ⑤를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"양초가 타면서 양이 줄고 물과 이산화 탄소가 생겼으므로 연소 과정에서 물질의 성질이 달라진다","correct":true},{"t":"양초는 타도 같은 물질로 남아 크기만 작아진다","mis":"SC6-2-u2-X22"},{"t":"양초가 타면서 산소가 생겨 양이 줄었다","mis":"SC6-2-u2-X21"},{"t":"양초가 타면 석회수가 생겨 종이가 붉어진다","mis":"SC6-2-u2-X20"}],"explanation":["②는 양이 줄었어요.","⑤는 새 물질을 알려 줘요.","성질이 달라져요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#24','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C2',4,'essay','teacher','별빛반 일지 ①의 ㉠~㉣을 성질이 변한 것과 변하지 않은 것으로 나누고, 그렇게 나눈 근거를 쓰세요. ㉢처럼 보이지 않게 된 것을 어떻게 판단해야 하는지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u2-C2","difficulty":4,"kind":"essay","stem":"별빛반 일지 ①의 ㉠~㉣을 성질이 변한 것과 변하지 않은 것으로 나누고, 그렇게 나눈 근거를 쓰세요. ㉢처럼 보이지 않게 된 것을 어떻게 판단해야 하는지도 쓰세요.","answer_guide":{"answer":"예: 성질이 변한 것은 ㉡과 ㉣이다. ㉡은 보글거리며 기포가 생겼고 ㉣은 열이 나고 색깔이 변해 새로운 변화가 나타났다. 성질이 변하지 않은 것은 ㉠과 ㉢이다. ㉠은 우유 맛과 코코아 맛이 그대로 함께 났고, ㉢은 소금이 보이지 않았지만 짠맛이 났다. 물에 녹아 보이지 않아도 짠맛 같은 성질이 그대로 남아 있으므로 성질이 변한 것이 아니며, 물을 증발시키면 소금을 다시 얻을 수 있다.","scoring_points":["네 가지를 바르게 나누었는가","기포·열·맛 같은 근거를 썼는가","보이지 않아도 성질이 그대로임을 썼는가"]},"explanation":["둘로 나눠요.","근거를 써요.","㉢을 따로 설명해요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_a#25','sci',6,2,'u2','','g6_2_sci_u2_review_a','unit_review','SC6-2-u2-C9',4,'essay','teacher','별빛반 일지 ⑤의 두 결과를 쓰고, 양초가 연소한 뒤 생성되는 물질을 추리하세요. 서준의 말(일지 ⑥)이 옳지 않은 까닭도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u2-C9","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑤의 두 결과를 쓰고, 양초가 연소한 뒤 생성되는 물질을 추리하세요. 서준의 말(일지 ⑥)이 옳지 않은 까닭도 쓰세요.","answer_guide":{"answer":"예: 유리 덮개 안쪽의 푸른색 염화 코발트 종이가 붉은색으로 변했고 테이프 자리는 푸른색 그대로였으므로 물이 생성되었다. 뚜껑을 닫고 흔든 석회수가 뿌옇게 흐려졌으므로 이산화 탄소가 생성되었다. 양초가 연소하면 물과 이산화 탄소가 생성된다. 서준의 말은 옳지 않다. 양초는 크기만 작아진 것이 아니라 연소하면서 전혀 다른 물질인 물과 이산화 탄소로 변했으므로 성질이 달라졌다.","scoring_points":["두 결과를 바르게 썼는가","물과 이산화 탄소를 추리했는가","성질이 달라졌다는 근거로 서준의 말을 바로잡았는가"]},"explanation":["결과를 써요.","생성 물질을 추리해요.","서준의 말을 바로잡아요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#1','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C2',1,'ox','auto','서로 다른 물질을 섞으면 성질이 변하기도 하고 변하지 않기도 해요.',ARRAY['SC6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C2","difficulty":1,"kind":"ox","stem":"서로 다른 물질을 섞으면 성질이 변하기도 하고 변하지 않기도 해요.","answer":"O","reason_options":[{"t":"섞는 물질에 따라 결과가 다르기 때문에","correct":true},{"t":"섞으면 언제나 성질이 변하기 때문에","mis":"SC6-2-u2-X03"}],"mis":"SC6-2-u2-X03","explanation":["두 고무풍선을 떠올려요.","한쪽만 변했어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#2','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C4',1,'ox','auto','알코올이 탈 때 불꽃은 푸른색, 붉은색 등으로 보여요.',ARRAY['SC6-2-u2-X09']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"ox","stem":"알코올이 탈 때 불꽃은 푸른색, 붉은색 등으로 보여요.","answer":"O","reason_options":[{"t":"알코올 불꽃의 색깔을 관찰한 결과이기 때문에","correct":true},{"t":"알코올 불꽃은 노란색만 보이기 때문에","mis":"SC6-2-u2-X09"}],"mis":"SC6-2-u2-X09","explanation":["알코올램프 불꽃이에요.","양초와 색깔이 달라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#3','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C6',1,'ox','auto','탈 물질과 산소만 있으면 온도와 관계없이 언제나 연소가 일어나요.',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"ox","stem":"탈 물질과 산소만 있으면 온도와 관계없이 언제나 연소가 일어나요.","answer":"X","reason_options":[{"t":"발화점 이상의 온도도 함께 있어야 연소가 일어나기 때문에","correct":true},{"t":"온도는 연소와 아무 관계가 없기 때문에","mis":"SC6-2-u2-X14"}],"mis":"SC6-2-u2-X14","explanation":["조건이 몇 가지인가요?","온도도 필요해요.","언제나는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#4','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C7',1,'ox','auto','공기 중에 산소가 많을수록 물질의 연소가 활발하게 일어나요.',ARRAY['SC6-2-u2-X15']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C7","difficulty":1,"kind":"ox","stem":"공기 중에 산소가 많을수록 물질의 연소가 활발하게 일어나요.","answer":"O","reason_options":[{"t":"산소는 물질이 타는 것을 돕기 때문에","correct":true},{"t":"산소가 많으면 불이 약해지기 때문에","mis":"SC6-2-u2-X15"}],"mis":"SC6-2-u2-X15","explanation":["비커와 함께 덮은 촛불을 떠올려요.","더 오래 탔어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#5','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C8',1,'ox','auto','발화점은 물질에 따라 달라요.',ARRAY['SC6-2-u2-X17']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":1,"kind":"ox","stem":"발화점은 물질에 따라 달라요.","answer":"O","reason_options":[{"t":"같은 열을 받아도 성냥 머리 부분과 나무 부분에 불이 붙는 때가 달랐기 때문에","correct":true},{"t":"모든 물질은 같은 온도에서 타기 시작하기 때문에","mis":"SC6-2-u2-X17"}],"mis":"SC6-2-u2-X17","explanation":["철판 실험을 떠올려요.","붙는 때가 달랐어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#6','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C9',1,'ox','auto','석회수는 이산화 탄소를 만나면 붉은색으로 변해요.',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"ox","stem":"석회수는 이산화 탄소를 만나면 붉은색으로 변해요.","answer":"X","reason_options":[{"t":"석회수는 이산화 탄소를 만나면 뿌옇게 흐려지기 때문에","correct":true},{"t":"석회수는 물에 닿으면 붉은색으로 변하기 때문에","mis":"SC6-2-u2-X20"}],"mis":"SC6-2-u2-X20","explanation":["석회수의 변화예요.","색이 아니라 흐려져요.","붉은색이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#7','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C11',1,'ox','auto','자동차나 비행기 같은 교통수단을 운행할 때에도 연소가 일어나요.',ARRAY['SC6-2-u2-X25']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"ox","stem":"자동차나 비행기 같은 교통수단을 운행할 때에도 연소가 일어나요.","answer":"O","reason_options":[{"t":"교통수단은 물질을 태워 움직이기 때문에","correct":true},{"t":"교통수단에서는 아무것도 타지 않기 때문에","mis":"SC6-2-u2-X25"}],"mis":"SC6-2-u2-X25","explanation":["생활 속 연소예요.","움직이려면 태워요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#8','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C12',1,'mc','auto','이산화 탄소를 줄이는 실천 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C12","difficulty":1,"kind":"mc","stem":"이산화 탄소를 줄이는 실천 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"사용하지 않는 플러그를 뽑아 둔다","correct":true},{"t":"빈방의 전등을 켜 둔다","mis":"SC6-2-u2-X27"},{"t":"가까운 거리도 자동차로 간다","mis":"SC6-2-u2-X27"},{"t":"일회용품을 더 많이 쓴다","mis":"SC6-2-u2-X27"}],"explanation":["전기를 아껴요.","생활 속 실천이에요.","플러그를 뽑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#9','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C3',2,'mc','auto','별빛반 일지 ①의 ㉣과 같은 쪽으로 가를 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X07']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"mc","stem":"별빛반 일지 ①의 ㉣과 같은 쪽으로 가를 수 있는 것은 어느 것인가요?","options":[{"t":"우유에 식초를 섞으면 덩어리가 생긴다","correct":true},{"t":"물에 꿀을 섞으면 꿀의 단맛이 난다","mis":"SC6-2-u2-X07"},{"t":"물에 설탕을 섞으면 단맛이 난다","mis":"SC6-2-u2-X07"},{"t":"소금과 설탕을 섞으면 두 맛이 함께 난다","mis":"SC6-2-u2-X07"}],"explanation":["㉣은 성질이 변했어요.","새로운 모습이 생긴 것을 찾아요.","덩어리가 생겨요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#10','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C4',2,'mc','auto','별빛반 일지 ②에서 한 시간 동안 양초의 길이는 얼마나 줄었나요?',ARRAY['SC6-2-u2-X10']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"mc","stem":"별빛반 일지 ②에서 한 시간 동안 양초의 길이는 얼마나 줄었나요?","options":[{"t":"2 cm","correct":true},{"t":"6 cm","mis":"SC6-2-u2-X10"},{"t":"8 cm","mis":"SC6-2-u2-X10"},{"t":"줄지 않았다","mis":"SC6-2-u2-X10"}],"explanation":["8에서 6이 됐어요.","빼 보아요.","2 cm예요."],"asset":{"type":"passage","lines":["양초 랜턴 — 불꽃 노란색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","알코올램프 — 불꽃 푸른색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","한 시간 뒤 — 양초 길이 8 cm → 6 cm, 알코올의 양도 줄었다."],"title":"별빛반 일지 ② 랜턴 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#11','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C7',2,'mc','auto','별빛반 일지 ③에서 산소와 관계있는 기록끼리 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X15']::text[],false,'{"seq":11,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"mc","stem":"별빛반 일지 ③에서 산소와 관계있는 기록끼리 짝지은 것은 어느 것인가요?","options":[{"t":"㉡과 ㉢","correct":true},{"t":"㉠과 ㉡","mis":"SC6-2-u2-X15"},{"t":"㉠만","mis":"SC6-2-u2-X15"},{"t":"㉡만","mis":"SC6-2-u2-X15"}],"explanation":["공기를 넣고 막은 것을 찾아요.","부채질과 조절 장치예요.","㉡과 ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#12','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C9',2,'mc','auto','별빛반 일지 ⑤에서 테이프 자리가 푸른색으로 남은 것이 쓸모 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X20','SC6-2-u2-X23']::text[],false,'{"seq":12,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑤에서 테이프 자리가 푸른색으로 남은 것이 쓸모 있는 까닭은 무엇인가요?","options":[{"t":"물이 닿지 않은 자리와 견주어 색 변화가 물 때문임을 알 수 있어서","correct":true},{"t":"종이가 원래 붉은색이었음을 알 수 있어서","mis":"SC6-2-u2-X20"},{"t":"테이프가 물을 만들었음을 알 수 있어서","mis":"SC6-2-u2-X23"},{"t":"이산화 탄소가 생겼음을 알 수 있어서","mis":"SC6-2-u2-X20"}],"explanation":["같은 종이 안에서 견줘요.","닿은 곳만 변해요.","물 때문이에요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#13','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C10',2,'ox','auto','연소 과정에서는 물질의 성질이 달라져요.',ARRAY['SC6-2-u2-X22']::text[],false,'{"seq":13,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"ox","stem":"연소 과정에서는 물질의 성질이 달라져요.","answer":"O","reason_options":[{"t":"연소 전과 전혀 다른 물질이 새로 생기기 때문에","correct":true},{"t":"연소 뒤에도 같은 물질이 그대로 남기 때문에","mis":"SC6-2-u2-X22"}],"mis":"SC6-2-u2-X22","explanation":["생성된 물질을 떠올려요.","양초와 달라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#14','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C11',2,'mc','auto','별빛반 일지 ⑦의 「장작은 필요한 만큼만!」이라는 약속이 생태계에 도움이 되는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X25','SC6-2-u2-X21']::text[],false,'{"seq":14,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑦의 「장작은 필요한 만큼만!」이라는 약속이 생태계에 도움이 되는 까닭은 무엇인가요?","options":[{"t":"태우는 양을 줄여 이산화 탄소 배출을 줄이기 때문에","correct":true},{"t":"장작이 많을수록 생태계가 좋아지기 때문에","mis":"SC6-2-u2-X25"},{"t":"장작을 태우면 산소만 생기기 때문에","mis":"SC6-2-u2-X21"},{"t":"장작은 타도 아무것도 생기지 않기 때문에","mis":"SC6-2-u2-X25"}],"explanation":["덜 태우면 어떨까요?","생기는 것도 줄어요.","배출을 줄여요."],"asset":{"type":"passage","lines":["야영장 화로와 자동차에서도 연소가 일어나 이산화 탄소가 생겨요.","이산화 탄소가 많아지면 숲과 바다의 생태계가 피해를 입어요.","우리 야영장의 약속 — 가까운 곳은 걸어서, 장작은 필요한 만큼만!"],"title":"별빛반 일지 ⑦ 야영장 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#15','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C13',2,'mc','auto','별빛반 일지 ⑧에서 아이스크림 가게로 보내는 것은 무엇이며 어디에 쓰이나요?',ARRAY['SC6-2-u2-X28','SC6-2-u2-X20']::text[],false,'{"seq":15,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"mc","stem":"별빛반 일지 ⑧에서 아이스크림 가게로 보내는 것은 무엇이며 어디에 쓰이나요?","options":[{"t":"드라이아이스 — 아이스크림을 차갑게 유지한다","correct":true},{"t":"소화기 — 아이스크림을 데운다","mis":"SC6-2-u2-X28"},{"t":"의약품 — 아이스크림을 만든다","mis":"SC6-2-u2-X28"},{"t":"석회수 — 아이스크림을 흐리게 한다","mis":"SC6-2-u2-X20"}],"explanation":["차갑게 하는 것이에요.","드라이아이스예요.","차갑게 유지해요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#16','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C2',2,'mc','auto','고무풍선 섞기 실험에서 두 고무풍선을 동시에 세운 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X05','SC6-2-u2-X04']::text[],false,'{"seq":16,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"mc","stem":"고무풍선 섞기 실험에서 두 고무풍선을 동시에 세운 까닭은 무엇인가요?","options":[{"t":"같은 때에 같은 조작을 해서 가루에 따른 차이만 견주려고","correct":true},{"t":"한쪽 고무풍선을 더 크게 부풀리려고","mis":"SC6-2-u2-X05"},{"t":"식초의 양을 다르게 하려고","mis":"SC6-2-u2-X05"},{"t":"밀가루를 더 빨리 녹이려고","mis":"SC6-2-u2-X04"}],"explanation":["견주려면 같게 해요.","때를 맞춰요.","가루만 다르게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#17','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C7',3,'mc','auto','별빛반 일지 ④의 측정 결과가 바로잡아 주는 생각은 어느 것인가요?',ARRAY['SC6-2-u2-X15','SC6-2-u2-X14']::text[],false,'{"seq":17,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"mc","stem":"별빛반 일지 ④의 측정 결과가 바로잡아 주는 생각은 어느 것인가요?","options":[{"t":"통 안의 산소가 모두 없어져 촛불이 꺼진다","correct":true},{"t":"산소는 물질이 타는 것을 돕는다","mis":"SC6-2-u2-X15"},{"t":"통이 크면 산소가 더 많다","mis":"SC6-2-u2-X15"},{"t":"연소에는 산소가 필요하다","mis":"SC6-2-u2-X14"}],"explanation":["꺼진 뒤에도 남아 있었어요.","모두 없어진 게 아니에요.","그 오개념을 바로잡아요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙이고 크기가 다른 투명한 통으로 동시에 덮었다.","작은 통의 촛불이 먼저 꺼지고, 큰 통의 촛불이 나중에 꺼졌다.","선생님이 측정기로 재어 보니 꺼진 뒤에도 두 통 안에 산소가 남아 있었다."],"title":"별빛반 일지 ④ 통 크기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#18','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C8',3,'mc','auto','볼록 렌즈로 햇빛을 모아 종이를 태울 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X18','SC6-2-u2-X14','SC6-2-u2-X17']::text[],false,'{"seq":18,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"mc","stem":"볼록 렌즈로 햇빛을 모아 종이를 태울 수 있는 까닭은 무엇인가요?","options":[{"t":"모은 햇빛이 종이의 온도를 발화점 이상으로 높이기 때문에","correct":true},{"t":"햇빛이 종이에 산소를 없애기 때문에","mis":"SC6-2-u2-X18"},{"t":"볼록 렌즈가 탈 물질이기 때문에","mis":"SC6-2-u2-X14"},{"t":"종이는 발화점이 없기 때문에","mis":"SC6-2-u2-X17"}],"explanation":["온도를 높여요.","발화점 이상이 돼요.","그래서 타요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#19','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C7',3,'mc','auto','별빛반 일지 ⑥의 하늘의 말을 바로잡을 수 있는 기록은 어느 것인가요?',ARRAY['SC6-2-u2-X10','SC6-2-u2-X03','SC6-2-u2-X28']::text[],false,'{"seq":19,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑥의 하늘의 말을 바로잡을 수 있는 기록은 어느 것인가요?","options":[{"t":"일지 ④ — 꺼진 뒤에도 통 안에 산소가 남아 있었다","correct":true},{"t":"일지 ② — 양초 길이가 줄었다","mis":"SC6-2-u2-X10"},{"t":"일지 ① — 기포가 생겼다","mis":"SC6-2-u2-X03"},{"t":"일지 ⑧ — 이산화 탄소를 모았다","mis":"SC6-2-u2-X28"}],"explanation":["산소가 남았는지 본 기록이에요.","측정기로 재었어요.","일지 ④예요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#20','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C3',3,'ox','auto','별빛반 일지 ⑥의 라온의 말처럼 물에 녹아 보이지 않으면 물질의 성질이 변한 거예요.',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":20,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"ox","stem":"별빛반 일지 ⑥의 라온의 말처럼 물에 녹아 보이지 않으면 물질의 성질이 변한 거예요.","answer":"X","reason_options":[{"t":"녹아 보이지 않아도 짠맛 같은 성질을 그대로 지니기 때문에","correct":true},{"t":"눈에 보이지 않으면 다른 물질이 된 것이기 때문에","mis":"SC6-2-u2-X06"}],"mis":"SC6-2-u2-X06","explanation":["일지 ①의 ㉢을 떠올려요.","짠맛이 났어요.","변한 게 아니에요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#21','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C6',3,'mc','auto','조리용 종이 그릇에 물을 붓고 라면을 끓여도 종이 그릇에 불이 붙지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X14','SC6-2-u2-X17']::text[],false,'{"seq":21,"concept":"SC6-2-u2-C6","difficulty":3,"kind":"mc","stem":"조리용 종이 그릇에 물을 붓고 라면을 끓여도 종이 그릇에 불이 붙지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그릇 속 물이 열을 받아 종이의 온도가 발화점 이상으로 올라가지 않기 때문에","correct":true},{"t":"종이 그릇에는 산소가 닿지 않기 때문에","mis":"SC6-2-u2-X14"},{"t":"종이는 탈 물질이 아니기 때문에","mis":"SC6-2-u2-X14"},{"t":"종이의 발화점은 모든 물질과 같기 때문에","mis":"SC6-2-u2-X17"}],"explanation":["세 조건을 하나씩 따져요.","종이도 산소도 있어요.","온도가 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#22','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C13',3,'mc','auto','배출량을 줄이는 노력과 자원으로 바꾸는 노력을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X28','SC6-2-u2-X27']::text[],false,'{"seq":22,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"mc","stem":"배출량을 줄이는 노력과 자원으로 바꾸는 노력을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"대중교통 이용하기 — 포집한 이산화 탄소로 드라이아이스 만들기","correct":true},{"t":"드라이아이스 만들기 — 대중교통 이용하기","mis":"SC6-2-u2-X28"},{"t":"전등 켜 두기 — 배기가스 그대로 내보내기","mis":"SC6-2-u2-X28"},{"t":"일회용품 더 쓰기 — 농작물에 이산화 탄소 주입하기","mis":"SC6-2-u2-X27"}],"explanation":["앞은 줄이기, 뒤는 바꾸기예요.","순서를 확인해요.","대중교통과 드라이아이스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#23','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C6',4,'mc','auto','별빛반 일지 ③의 ㉠~㉣을 연소의 조건과 이어 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X14','SC6-2-u2-X16']::text[],false,'{"seq":23,"concept":"SC6-2-u2-C6","difficulty":4,"kind":"mc","stem":"별빛반 일지 ③의 ㉠~㉣을 연소의 조건과 이어 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"㉠ 탈 물질과 발화점 이상의 온도 · ㉡㉢ 산소의 양 · ㉣ 산소가 충분하지 않음","correct":true},{"t":"㉠ 산소 · ㉡㉢ 온도 · ㉣ 탈 물질이 모두 없어짐","mis":"SC6-2-u2-X14"},{"t":"㉠ 이산화 탄소 · ㉡㉢ 산소 · ㉣ 산소가 하나도 남지 않음","mis":"SC6-2-u2-X16"},{"t":"㉠㉡㉢㉣ 모두 온도와만 관계있음","mis":"SC6-2-u2-X14"}],"explanation":["기록마다 무엇이 달라졌나요?","부채질과 조절 장치는 산소예요.","덮은 것도 산소예요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#24','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C4',4,'essay','teacher','별빛반 일지 ②를 보고 양초와 알코올이 탈 때의 같은 점과 다른 점을 쓰고, 물질이 탈 때 나타나는 공통적인 현상을 쓰세요. 야영장에서 그 현상을 이용하는 예도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u2-C4","difficulty":4,"kind":"essay","stem":"별빛반 일지 ②를 보고 양초와 알코올이 탈 때의 같은 점과 다른 점을 쓰고, 물질이 탈 때 나타나는 공통적인 현상을 쓰세요. 야영장에서 그 현상을 이용하는 예도 하나 쓰세요.","answer_guide":{"answer":"예: 두 불꽃 모두 주변이 밝아지고 가까울수록 따뜻했으며, 시간이 지나자 양초와 알코올의 양이 줄었다. 다른 점은 불꽃의 색깔로 양초는 노란색·붉은색 등, 알코올은 푸른색·붉은색 등이었다. 물질이 탈 때에는 공통적으로 빛과 열이 발생한다. 야영장에서는 랜턴 불빛으로 텐트 주변을 밝히거나 모닥불의 열로 몸을 따뜻하게 한다.","scoring_points":["같은 점과 다른 점을 바르게 썼는가","빛과 열을 공통적인 현상으로 썼는가","빛이나 열을 이용하는 예를 썼는가"]},"explanation":["같은 점·다른 점을 써요.","공통 현상을 써요.","야영장 예를 들어요."],"asset":{"type":"passage","lines":["양초 랜턴 — 불꽃 노란색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","알코올램프 — 불꽃 푸른색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","한 시간 뒤 — 양초 길이 8 cm → 6 cm, 알코올의 양도 줄었다."],"title":"별빛반 일지 ② 랜턴 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_b#25','sci',6,2,'u2','','g6_2_sci_u2_review_b','unit_review','SC6-2-u2-C11',4,'essay','teacher','별빛반 일지 ⑦을 보고 연소로 생긴 이산화 탄소가 생태계에 어떤 피해를 주는지 숲과 바다의 예를 하나씩 들어 쓰고, 두 피해의 공통 원인과 우리가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u2-C11","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑦을 보고 연소로 생긴 이산화 탄소가 생태계에 어떤 피해를 주는지 숲과 바다의 예를 하나씩 들어 쓰고, 두 피해의 공통 원인과 우리가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 이산화 탄소가 많아져 기후변화가 생기면 침엽수림이 한꺼번에 말라 죽는다. 이산화 탄소의 일부가 바다에 녹으면 바다가 산성화되어 조개류의 껍데기가 얇아지거나 깨진다. 두 피해는 나타나는 곳은 다르지만 모두 이산화 탄소의 배출량이 증가하기 때문에 발생한다. 우리는 가까운 곳은 걸어 다니고 장작을 필요한 만큼만 태워 이산화 탄소의 배출량을 줄일 수 있다.","scoring_points":["숲과 바다의 피해를 하나씩 썼는가","공통 원인을 배출량 증가로 썼는가","배출량을 줄이는 실천을 썼는가"]},"explanation":["숲 하나, 바다 하나예요.","공통 원인을 찾아요.","우리의 실천을 써요."],"asset":{"type":"passage","lines":["야영장 화로와 자동차에서도 연소가 일어나 이산화 탄소가 생겨요.","이산화 탄소가 많아지면 숲과 바다의 생태계가 피해를 입어요.","우리 야영장의 약속 — 가까운 곳은 걸어서, 장작은 필요한 만큼만!"],"title":"별빛반 일지 ⑦ 야영장 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#1','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C2',1,'sa','auto','밀가루와 식초를 섞었을 때 고무풍선에는 아무런 □□가 없었습니다. □□에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C2","difficulty":1,"kind":"sa","stem":"밀가루와 식초를 섞었을 때 고무풍선에는 아무런 □□가 없었습니다. □□에 알맞은 두 글자를 쓰세요.","answer":["변화"],"explanation":["밀가루 쪽이에요.","그대로였어요.","변화가 없었어요."],"mis":"SC6-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#2','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C5',1,'sa','auto','물질이 탈 때 나오는 것 가운데 음식을 조리하는 데 쓰는 것은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u2-C5","difficulty":1,"kind":"sa","stem":"물질이 탈 때 나오는 것 가운데 음식을 조리하는 데 쓰는 것은 무엇인가요? 한 글자로 쓰세요.","answer":["열"],"explanation":["뜨거운 것이에요.","빛과 함께 나와요.","열이에요."],"mis":"SC6-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#3','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C6',1,'blank','auto','「물질이 (    )와 만나 빛과 열을 내면서 타는 현상을 연소라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X13']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"blank","stem":"「물질이 (    )와 만나 빛과 열을 내면서 타는 현상을 연소라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"산소","correct":true},{"t":"물","mis":"SC6-2-u2-X13"},{"t":"식초","mis":"SC6-2-u2-X13"},{"t":"석회수","mis":"SC6-2-u2-X13"}],"explanation":["연소의 뜻이에요.","타는 것을 도와요.","산소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#4','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C7',1,'sa','auto','묽은 과산화 수소수에 아이오딘화 칼륨을 넣으면 발생하는 기체는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C7","difficulty":1,"kind":"sa","stem":"묽은 과산화 수소수에 아이오딘화 칼륨을 넣으면 발생하는 기체는 무엇인가요? 두 글자로 쓰세요.","answer":["산소"],"explanation":["촛불을 더 오래 타게 했어요.","연소의 조건이에요.","산소예요."],"mis":"SC6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#5','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C8',1,'mc','auto','불을 직접 붙이지 않아도 물질이 탈 수 있는 경우는 어느 것인가요?',ARRAY['SC6-2-u2-X18','SC6-2-u2-X14']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":1,"kind":"mc","stem":"불을 직접 붙이지 않아도 물질이 탈 수 있는 경우는 어느 것인가요?","options":[{"t":"마른나무를 마찰해 온도를 높일 때","correct":true},{"t":"물질을 차가운 곳에 둘 때","mis":"SC6-2-u2-X18"},{"t":"물질을 물에 적실 때","mis":"SC6-2-u2-X18"},{"t":"물질을 통으로 덮을 때","mis":"SC6-2-u2-X14"}],"explanation":["온도를 높여야 해요.","발화점 이상이 되게 해요.","마찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#6','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C9',1,'mc','auto','별빛반 일지 ⑤에서 종이가 붉은색으로 변한 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X21','SC6-2-u2-X20','SC6-2-u2-X22']::text[],false,'{"seq":6,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑤에서 종이가 붉은색으로 변한 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물이 생성되었다","correct":true},{"t":"산소가 생성되었다","mis":"SC6-2-u2-X21"},{"t":"이산화 탄소가 생성되었다","mis":"SC6-2-u2-X20"},{"t":"양초가 그대로 남았다","mis":"SC6-2-u2-X22"}],"explanation":["푸른색 염화 코발트 종이예요.","물에 닿으면 붉어져요.","물이 생겼어요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#7','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C11',1,'mc','auto','이산화 탄소가 많아져 생기는 바다 생태계의 피해는 어느 것인가요?',ARRAY['SC6-2-u2-X24','SC6-2-u2-X25']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"mc","stem":"이산화 탄소가 많아져 생기는 바다 생태계의 피해는 어느 것인가요?","options":[{"t":"산호초가 하얗게 변한다","correct":true},{"t":"침엽수림이 말라 죽는다","mis":"SC6-2-u2-X24"},{"t":"구상나무가 말라 죽는다","mis":"SC6-2-u2-X24"},{"t":"바닷물이 늘 깨끗해진다","mis":"SC6-2-u2-X25"}],"explanation":["바다를 골라요.","하얗게 변해요.","산호초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#8','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C13',1,'ox','auto','포집한 이산화 탄소는 소화기를 만드는 데 활용되기도 해요.',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"ox","stem":"포집한 이산화 탄소는 소화기를 만드는 데 활용되기도 해요.","answer":"O","reason_options":[{"t":"포집한 이산화 탄소는 소화기·의약품 등 여러 분야에 활용되기 때문에","correct":true},{"t":"포집한 이산화 탄소는 모두 버려지기 때문에","mis":"SC6-2-u2-X28"}],"mis":"SC6-2-u2-X28","explanation":["쓰임 넷을 떠올려요.","소화기도 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#9','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C3',2,'ox','auto','별빛반 일지 ①의 ㉠은 물질의 성질이 변하지 않은 예예요.',ARRAY['SC6-2-u2-X03']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"ox","stem":"별빛반 일지 ①의 ㉠은 물질의 성질이 변하지 않은 예예요.","answer":"O","reason_options":[{"t":"우유 맛과 코코아 맛이 그대로 함께 났기 때문에","correct":true},{"t":"섞었으니 반드시 성질이 변했기 때문에","mis":"SC6-2-u2-X03"}],"mis":"SC6-2-u2-X03","explanation":["맛을 봐요.","두 맛이 그대로예요.","맞는 말이에요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#10','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C5',2,'ox','auto','야영장에서 랜턴 불빛으로 텐트 주변을 밝히는 것은 물질이 탈 때 나오는 빛을 이용한 예예요.',ARRAY['SC6-2-u2-X11']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C5","difficulty":2,"kind":"ox","stem":"야영장에서 랜턴 불빛으로 텐트 주변을 밝히는 것은 물질이 탈 때 나오는 빛을 이용한 예예요.","answer":"O","reason_options":[{"t":"타면서 나온 빛으로 어두운 곳을 밝히기 때문에","correct":true},{"t":"랜턴 불꽃에서는 빛이 나오지 않기 때문에","mis":"SC6-2-u2-X11"}],"mis":"SC6-2-u2-X11","explanation":["밝히는 것이에요.","빛을 써요.","맞는 말이에요."],"asset":{"type":"passage","lines":["양초 랜턴 — 불꽃 노란색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","알코올램프 — 불꽃 푸른색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","한 시간 뒤 — 양초 길이 8 cm → 6 cm, 알코올의 양도 줄었다."],"title":"별빛반 일지 ② 랜턴 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#11','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C7',2,'ox','auto','별빛반 일지 ③의 ㉡과 ㉢은 산소의 양에 따라 불의 세기가 달라짐을 보여 줘요.',ARRAY['SC6-2-u2-X15']::text[],false,'{"seq":11,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"ox","stem":"별빛반 일지 ③의 ㉡과 ㉢은 산소의 양에 따라 불의 세기가 달라짐을 보여 줘요.","answer":"O","reason_options":[{"t":"산소를 더 넣으면 세지고 덜 넣으면 약해졌기 때문에","correct":true},{"t":"산소와 불의 세기는 관계가 없기 때문에","mis":"SC6-2-u2-X15"}],"mis":"SC6-2-u2-X15","explanation":["두 기록을 견줘요.","산소를 넣고 막았어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#12','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C9',2,'ox','auto','별빛반 일지 ⑤에서 석회수 병은 뚜껑을 닫고 흔든 뒤 관찰했어요.',ARRAY['SC6-2-u2-X23']::text[],false,'{"seq":12,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"ox","stem":"별빛반 일지 ⑤에서 석회수 병은 뚜껑을 닫고 흔든 뒤 관찰했어요.","answer":"O","reason_options":[{"t":"뚜껑을 닫고 흔들어야 석회수의 변화를 잘 볼 수 있기 때문에","correct":true},{"t":"석회수는 흔들면 결과가 사라지기 때문에","mis":"SC6-2-u2-X23"}],"mis":"SC6-2-u2-X23","explanation":["기록을 읽어요.","흔든 뒤 봤어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#13','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C10',2,'mc','auto','연소 과정에서 물질의 성질이 달라지는 예로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X06','SC6-2-u2-X03','SC6-2-u2-X22']::text[],false,'{"seq":13,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"mc","stem":"연소 과정에서 물질의 성질이 달라지는 예로 알맞은 것은 어느 것인가요?","options":[{"t":"양초가 타서 물과 이산화 탄소가 생긴다","correct":true},{"t":"물에 설탕이 녹아 보이지 않는다","mis":"SC6-2-u2-X06"},{"t":"밀가루를 식초에 넣었더니 가라앉는다","mis":"SC6-2-u2-X03"},{"t":"양초를 칼로 잘라 두 조각으로 만든다","mis":"SC6-2-u2-X22"}],"explanation":["타는 것을 골라요.","새 물질이 생겨요.","양초가 타는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#14','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C11',2,'ox','auto','별빛반 일지 ⑦처럼 숲과 바다의 생태계 피해는 원인이 서로 전혀 달라요.',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":14,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"ox","stem":"별빛반 일지 ⑦처럼 숲과 바다의 생태계 피해는 원인이 서로 전혀 달라요.","answer":"X","reason_options":[{"t":"숲과 바다의 피해 모두 이산화 탄소 배출량 증가 때문이기 때문에","correct":true},{"t":"숲은 숲대로, 바다는 바다대로 원인이 따로 있기 때문에","mis":"SC6-2-u2-X24"}],"mis":"SC6-2-u2-X24","explanation":["공통점을 분석했어요.","원인이 같아요.","전혀 다르지 않아요."],"asset":{"type":"passage","lines":["야영장 화로와 자동차에서도 연소가 일어나 이산화 탄소가 생겨요.","이산화 탄소가 많아지면 숲과 바다의 생태계가 피해를 입어요.","우리 야영장의 약속 — 가까운 곳은 걸어서, 장작은 필요한 만큼만!"],"title":"별빛반 일지 ⑦ 야영장 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#15','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C13',2,'ox','auto','별빛반 일지 ⑧의 발전소는 이미 배출된 이산화 탄소를 자원으로 바꾸는 노력을 하고 있어요.',ARRAY['SC6-2-u2-X28']::text[],false,'{"seq":15,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"ox","stem":"별빛반 일지 ⑧의 발전소는 이미 배출된 이산화 탄소를 자원으로 바꾸는 노력을 하고 있어요.","answer":"O","reason_options":[{"t":"배기가스 속 이산화 탄소를 모아 농장과 가게에서 쓰기 때문에","correct":true},{"t":"이산화 탄소를 그대로 대기로 내보내기 때문에","mis":"SC6-2-u2-X28"}],"mis":"SC6-2-u2-X28","explanation":["모아서 다시 써요.","자원으로 바꿔요.","맞는 말이에요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#16','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C1',2,'ox','auto','불씨 살리기 활동에서는 향 끝에 큰 불꽃이 있을 때 병에 넣어요.',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":16,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"ox","stem":"불씨 살리기 활동에서는 향 끝에 큰 불꽃이 있을 때 병에 넣어요.","answer":"X","reason_options":[{"t":"작은 불씨만 남았을 때 넣어야 불씨가 커지는지 볼 수 있기 때문에","correct":true},{"t":"큰 불꽃이어야 결과가 잘 보이기 때문에","mis":"SC6-2-u2-X02"}],"mis":"SC6-2-u2-X02","explanation":["꺼져 가는 불씨예요.","작은 불씨일 때예요.","큰 불꽃이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#17','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C7',3,'ox','auto','별빛반 일지 ④에서 두 촛불을 동시에 덮은 것은 통의 크기만 다르게 하려는 것이에요.',ARRAY['SC6-2-u2-X19']::text[],false,'{"seq":17,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"ox","stem":"별빛반 일지 ④에서 두 촛불을 동시에 덮은 것은 통의 크기만 다르게 하려는 것이에요.","answer":"O","reason_options":[{"t":"덮는 때와 양초는 같게 하고 통의 크기만 달리했기 때문에","correct":true},{"t":"덮는 때를 다르게 하는 것이 실험의 목적이기 때문에","mis":"SC6-2-u2-X19"}],"mis":"SC6-2-u2-X19","explanation":["같게 한 것을 찾아요.","동시에 덮었어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙이고 크기가 다른 투명한 통으로 동시에 덮었다.","작은 통의 촛불이 먼저 꺼지고, 큰 통의 촛불이 나중에 꺼졌다.","선생님이 측정기로 재어 보니 꺼진 뒤에도 두 통 안에 산소가 남아 있었다."],"title":"별빛반 일지 ④ 통 크기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#18','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C8',3,'ox','auto','철판 실험에서 성냥의 머리 부분과 나무 부분을 바짝 붙여 놓으면 결과를 더 정확히 견줄 수 있어요.',ARRAY['SC6-2-u2-X19']::text[],false,'{"seq":18,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"ox","stem":"철판 실험에서 성냥의 머리 부분과 나무 부분을 바짝 붙여 놓으면 결과를 더 정확히 견줄 수 있어요.","answer":"X","reason_options":[{"t":"너무 가까우면 먼저 붙은 불이 옆으로 옮겨 붙어 각각의 결과를 견줄 수 없기 때문에","correct":true},{"t":"가까울수록 두 부분이 똑같이 타기 때문에","mis":"SC6-2-u2-X19"}],"mis":"SC6-2-u2-X19","explanation":["너무 가까이 두지 않아요.","불이 옮겨붙어요.","정확하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#19','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C10',3,'ox','auto','별빛반 일지 ⑥의 서준의 말은 옳아요.',ARRAY['SC6-2-u2-X22']::text[],false,'{"seq":19,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"ox","stem":"별빛반 일지 ⑥의 서준의 말은 옳아요.","answer":"X","reason_options":[{"t":"양초가 연소하면 전혀 다른 물질로 변하므로 성질이 달라지기 때문에","correct":true},{"t":"양초는 타도 크기만 작아질 뿐 같은 물질이기 때문에","mis":"SC6-2-u2-X22"}],"mis":"SC6-2-u2-X22","explanation":["연소 뒤 무엇이 생겼나요?","물과 이산화 탄소예요.","옳지 않아요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#20','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C2',3,'mc','auto','섞었을 때 성질이 변했는지 판단하는 근거로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X06','SC6-2-u2-X05','SC6-2-u2-X03']::text[],false,'{"seq":20,"concept":"SC6-2-u2-C2","difficulty":3,"kind":"mc","stem":"섞었을 때 성질이 변했는지 판단하는 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"기포·덩어리·열처럼 새로운 변화가 나타났는지","correct":true},{"t":"섞은 뒤 눈에 보이지 않게 되었는지","mis":"SC6-2-u2-X06"},{"t":"섞은 그릇이 투명한지","mis":"SC6-2-u2-X05"},{"t":"섞은 물질이 둘인지","mis":"SC6-2-u2-X03"}],"explanation":["성질 변화의 신호를 찾아요.","새로운 변화예요.","기포·덩어리·열이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#21','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C6',3,'ox','auto','연소의 조건 가운데 하나만 없애도 불은 계속 타지 못해요.',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":21,"concept":"SC6-2-u2-C6","difficulty":3,"kind":"ox","stem":"연소의 조건 가운데 하나만 없애도 불은 계속 타지 못해요.","answer":"O","reason_options":[{"t":"연소에는 세 조건이 모두 필요하기 때문에","correct":true},{"t":"세 조건 가운데 하나만 있어도 연소가 일어나기 때문에","mis":"SC6-2-u2-X14"}],"mis":"SC6-2-u2-X14","explanation":["조건이 셋이에요.","하나라도 없으면 안 돼요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#22','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C11',3,'ox','auto','이산화 탄소로 인한 생태계 피해는 숲에서만 나타나요.',ARRAY['SC6-2-u2-X24']::text[],false,'{"seq":22,"concept":"SC6-2-u2-C11","difficulty":3,"kind":"ox","stem":"이산화 탄소로 인한 생태계 피해는 숲에서만 나타나요.","answer":"X","reason_options":[{"t":"바다에서도 조개류·산호초 같은 피해가 나타나기 때문에","correct":true},{"t":"바다는 이산화 탄소와 관계없기 때문에","mis":"SC6-2-u2-X24"}],"mis":"SC6-2-u2-X24","explanation":["바다 사례를 떠올려요.","조개류와 산호초예요.","숲에서만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#23','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C3',4,'mc','auto','「서로 다른 물질을 섞을 때」와 「물질이 연소할 때」를 견주어 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u2-X03','SC6-2-u2-X22','SC6-2-u2-X06']::text[],false,'{"seq":23,"concept":"SC6-2-u2-C3","difficulty":4,"kind":"mc","stem":"「서로 다른 물질을 섞을 때」와 「물질이 연소할 때」를 견주어 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"섞을 때는 성질이 변하기도 하고 변하지 않기도 하지만, 연소할 때는 새로운 물질이 생겨 성질이 달라진다","correct":true},{"t":"두 경우 모두 성질이 항상 변하지 않는다","mis":"SC6-2-u2-X03"},{"t":"섞을 때는 늘 성질이 변하고 연소할 때는 변하지 않는다","mis":"SC6-2-u2-X22"},{"t":"녹아서 안 보이게 되는 것도 연소와 같다","mis":"SC6-2-u2-X06"}],"explanation":["두 차시를 떠올려요.","섞기는 둘 다 있어요.","연소는 새 물질이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#24','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C7',4,'essay','teacher','별빛반 일지 ④의 결과를 쓰고, 하늘의 말(일지 ⑥)을 이 결과로 바로잡으세요. 산소와 연소의 관계도 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u2-C7","difficulty":4,"kind":"essay","stem":"별빛반 일지 ④의 결과를 쓰고, 하늘의 말(일지 ⑥)을 이 결과로 바로잡으세요. 산소와 연소의 관계도 함께 쓰세요.","answer_guide":{"answer":"예: 크기가 다른 통으로 동시에 덮었더니 작은 통의 촛불이 먼저, 큰 통의 촛불이 나중에 꺼졌고, 꺼진 뒤에도 두 통 안에 산소가 남아 있었다. 하늘아, 불이 꺼진 것은 산소가 하나도 남지 않아서가 아니라 연소할 수 있을 만큼 산소가 충분하지 않았기 때문이야. 산소는 물질이 타는 것을 도우므로 산소가 많을수록 연소가 활발하고, 충분하지 않으면 연소가 일어나지 않는다.","scoring_points":["일지 ④의 결과를 바르게 썼는가","산소가 남아 있다는 근거로 하늘의 말을 바로잡았는가","산소와 연소의 관계를 썼는가"]},"explanation":["결과를 써요.","근거를 들어 바로잡아요.","산소와 연소를 이어요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙이고 크기가 다른 투명한 통으로 동시에 덮었다.","작은 통의 촛불이 먼저 꺼지고, 큰 통의 촛불이 나중에 꺼졌다.","선생님이 측정기로 재어 보니 꺼진 뒤에도 두 통 안에 산소가 남아 있었다."],"title":"별빛반 일지 ④ 통 크기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_c#25','sci',6,2,'u2','','g6_2_sci_u2_review_c','unit_review','SC6-2-u2-C13',4,'essay','teacher','별빛반 일지 ⑧의 발전소가 하는 일을 이산화 탄소를 모으는 차례와 쓰임으로 설명하고, 「재활용하면 되니 마음껏 배출해도 된다」는 생각에 대한 나의 의견을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u2-C13","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑧의 발전소가 하는 일을 이산화 탄소를 모으는 차례와 쓰임으로 설명하고, 「재활용하면 되니 마음껏 배출해도 된다」는 생각에 대한 나의 의견을 쓰세요.","answer_guide":{"answer":"예: 발전소에서는 연소로 배기가스가 나오면 이산화 탄소를 흡수하고 그중 이산화 탄소만 포집한다. 모은 이산화 탄소는 비닐하우스 농장에서 채소의 생장 속도와 품질을 높이는 데 쓰고, 드라이아이스로 만들어 아이스크림을 차갑게 유지하는 데 쓴다. 그러나 재활용은 이미 배출된 것을 다시 쓰는 노력일 뿐이므로 마음껏 배출해도 된다는 생각은 옳지 않다. 배출량을 줄이는 노력과 자원으로 바꾸는 노력을 함께 해야 생태계의 피해를 줄일 수 있다.","scoring_points":["모으는 차례를 썼는가","포집한 이산화 탄소의 쓰임을 썼는가","두 갈래 노력을 들어 의견을 썼는가"]},"explanation":["차례를 써요.","쓰임을 써요.","의견을 근거와 함께 써요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#1','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C3',1,'blank','auto','「물에 녹아 보이지 않는 소금도 (    )은 그대로 납니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C3","difficulty":1,"kind":"blank","stem":"「물에 녹아 보이지 않는 소금도 (    )은 그대로 납니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"짠맛","correct":true},{"t":"단맛","mis":"SC6-2-u2-X06"},{"t":"신맛","mis":"SC6-2-u2-X06"},{"t":"쓴맛","mis":"SC6-2-u2-X06"}],"explanation":["소금의 맛이에요.","녹아도 남아요.","짠맛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#2','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C4',1,'mc','auto','양초에 불을 붙일 때 쓰는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u2-X12']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C4","difficulty":1,"kind":"mc","stem":"양초에 불을 붙일 때 쓰는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"점화기","correct":true},{"t":"석회수","mis":"SC6-2-u2-X12"},{"t":"분말 깔때기","mis":"SC6-2-u2-X12"},{"t":"셀로판테이프","mis":"SC6-2-u2-X12"}],"explanation":["불을 붙이는 도구예요.","향에도 썼어요.","점화기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#3','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C6',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC6-2-u2-C6","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"연소","r":"물질이 산소와 만나 빛과 열을 내며 타는 현상"},{"l":"발화점","r":"물질이 타기 시작하는 온도"},{"l":"탈 물질","r":"양초·나무·알코올처럼 타는 물질"}],"mis":"SC6-2-u2-X13","explanation":["현상, 온도, 물질을 가려요.","연소는 현상이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#4','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C7',1,'mc','auto','별빛반 일지 ③에서 화로의 공기 조절 장치를 닫았더니 불이 약해진 까닭은 무엇인가요?',ARRAY['SC6-2-u2-X15','SC6-2-u2-X21']::text[],false,'{"seq":4,"concept":"SC6-2-u2-C7","difficulty":1,"kind":"mc","stem":"별빛반 일지 ③에서 화로의 공기 조절 장치를 닫았더니 불이 약해진 까닭은 무엇인가요?","options":[{"t":"들어가는 산소가 줄었기 때문에","correct":true},{"t":"탈 물질이 늘었기 때문에","mis":"SC6-2-u2-X15"},{"t":"온도가 크게 올라갔기 때문에","mis":"SC6-2-u2-X15"},{"t":"장작이 물로 변했기 때문에","mis":"SC6-2-u2-X21"}],"explanation":["공기가 드나드는 곳을 막았어요.","산소가 덜 들어가요.","불이 약해져요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#5','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C8',1,'sa','auto','철판 실험에서 철판을 받쳐 올려놓은 도구는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u2-C8","difficulty":1,"kind":"sa","stem":"철판 실험에서 철판을 받쳐 올려놓은 도구는 무엇인가요? 세 글자로 쓰세요.","answer":["삼발이"],"explanation":["다리가 셋이에요.","□발이예요.","삼발이예요."],"mis":"SC6-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#6','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C9',1,'sa','auto','물에 닿으면 붉은색으로 변하는 종이는 무엇인가요? (푸른색 □□ □□ 종이)','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u2-C9","difficulty":1,"kind":"sa","stem":"물에 닿으면 붉은색으로 변하는 종이는 무엇인가요? (푸른색 □□ □□ 종이)","answer":["염화 코발트","염화코발트","푸른색 염화 코발트 종이"],"explanation":["아크릴 통에 붙였어요.","네 글자예요.","염화 코발트예요."],"mis":"SC6-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#7','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C11',1,'sa','auto','조사한 자료를 사용할 때 꼭 밝혀야 하는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u2-C11","difficulty":1,"kind":"sa","stem":"조사한 자료를 사용할 때 꼭 밝혀야 하는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["자료가 어디서 왔나요?","□처예요.","출처예요."],"mis":"SC6-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#8','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C13',1,'sa','auto','이산화 탄소를 주입해 생장 속도와 품질을 높이는 것은 무엇을 재배할 때인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC6-2-u2-C13","difficulty":1,"kind":"sa","stem":"이산화 탄소를 주입해 생장 속도와 품질을 높이는 것은 무엇을 재배할 때인가요? 세 글자로 쓰세요.","answer":["농작물"],"explanation":["밭에서 길러요.","□작물이에요.","농작물이에요."],"mis":"SC6-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#9','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C3',2,'error','auto','별빛반 일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X06','SC6-2-u2-X07']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C3","difficulty":2,"kind":"error","stem":"별빛반 일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보미 — 「㉢은 소금이 안 보이니 성질이 변했어.」","correct":true,"mis_target":"SC6-2-u2-X06"},{"t":"이안 — 「㉡은 기포가 생겨 성질이 변했어.」","mis":"SC6-2-u2-X07"},{"t":"채윤 — 「㉣은 열이 나고 색이 변했어.」","mis":"SC6-2-u2-X07"}],"explanation":["짠맛이 났어요.","보이지 않아도 남아요.","보미가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 우유에 코코아 가루를 섞었다 — 우유 맛과 코코아 맛이 함께 났다.","㉡ 제빵 소다에 식초를 부었다 — 보글거리며 기포가 생겼다.","㉢ 물에 소금을 녹였다 — 소금이 보이지 않았지만 짠맛이 났다.","㉣ 흔든 손난로 — 따뜻해지고 속 가루의 색깔이 변했다."],"title":"별빛반 일지 ① 저녁 준비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#10','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C4',2,'error','auto','별빛반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X09','SC6-2-u2-X08','SC6-2-u2-X10']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C4","difficulty":2,"kind":"error","stem":"별빛반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「색깔이 다르니 공통적인 현상은 없어.」","correct":true,"mis_target":"SC6-2-u2-X09"},{"t":"지성 — 「둘 다 빛과 열이 났어.」","mis":"SC6-2-u2-X08"},{"t":"소율 — 「둘 다 타면서 양이 줄었어.」","mis":"SC6-2-u2-X10"}],"explanation":["같은 점이 셋이에요.","빛과 열은 둘 다예요.","하진이 잘못 말했어요."],"asset":{"type":"passage","lines":["양초 랜턴 — 불꽃 노란색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","알코올램프 — 불꽃 푸른색·붉은색 등 · 주변이 밝아짐 · 가까울수록 따뜻함","한 시간 뒤 — 양초 길이 8 cm → 6 cm, 알코올의 양도 줄었다."],"title":"별빛반 일지 ② 랜턴 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#11','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C7',2,'error','auto','별빛반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X15']::text[],false,'{"seq":11,"concept":"SC6-2-u2-C7","difficulty":2,"kind":"error","stem":"별빛반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「부채질로 장작의 온도를 낮춰서 불이 세진 거야.」","correct":true,"mis_target":"SC6-2-u2-X15"},{"t":"나래 — 「부채질로 산소가 더 들어갔어.」","mis":"SC6-2-u2-X15"},{"t":"윤재 — 「조절 장치를 닫으면 산소가 덜 들어가.」","mis":"SC6-2-u2-X15"}],"explanation":["부채질은 공기를 보내요.","산소 공급이에요.","태윤이 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 마른 장작에 불을 붙였다.","㉡ 불이 약해져 부채질을 했더니 불이 세졌다.","㉢ 화로의 공기 조절 장치를 닫았더니 불이 약해졌다.","㉣ 남은 불씨를 금속 뚜껑으로 덮었더니 얼마 뒤 꺼졌다."],"title":"별빛반 일지 ③ 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#12','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C9',2,'error','auto','별빛반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":12,"concept":"SC6-2-u2-C9","difficulty":2,"kind":"error","stem":"별빛반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「종이가 붉어졌으니 이산화 탄소가 생겼어.」","correct":true,"mis_target":"SC6-2-u2-X20"},{"t":"서연 — 「종이가 붉어졌으니 물이 생겼어.」","mis":"SC6-2-u2-X20"},{"t":"도경 — 「석회수가 흐려졌으니 이산화 탄소가 생겼어.」","mis":"SC6-2-u2-X20"}],"explanation":["종이는 물을 알려 줘요.","지시약을 바꿔 말했어요.","민호가 잘못 말했어요."],"asset":{"type":"passage","lines":["랜턴 유리 덮개 안쪽에 푸른색 염화 코발트 종이를 붙였다.","불을 켠 뒤 종이가 붉은색으로 변했다(테이프 자리는 푸른색).","덮개 안에 석회수 병을 두었다가 뚜껑을 닫고 흔들었다.","무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"별빛반 일지 ⑤ 연소 뒤 확인"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#13','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C10',2,'blank','auto','「양초가 많이 연소할수록 생성되는 물질의 양도 (    ).」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X22','SC6-2-u2-X21']::text[],false,'{"seq":13,"concept":"SC6-2-u2-C10","difficulty":2,"kind":"blank","stem":"「양초가 많이 연소할수록 생성되는 물질의 양도 (    ).」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"많아집니다","correct":true},{"t":"적어집니다","mis":"SC6-2-u2-X22"},{"t":"그대로입니다","mis":"SC6-2-u2-X22"},{"t":"사라집니다","mis":"SC6-2-u2-X21"}],"explanation":["많이 타면 어떨까요?","생기는 것도 늘어요.","많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#14','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C11',2,'error','auto','별빛반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X27']::text[],false,'{"seq":14,"concept":"SC6-2-u2-C11","difficulty":2,"kind":"error","stem":"별빛반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「우리 같은 학생은 이산화 탄소를 줄일 수 없어.」","correct":true,"mis_target":"SC6-2-u2-X27"},{"t":"도현 — 「가까운 곳은 걸어가면 돼.」","mis":"SC6-2-u2-X27"},{"t":"유리 — 「장작을 아끼는 것도 방법이야.」","mis":"SC6-2-u2-X27"}],"explanation":["우리도 할 수 있어요.","생활 속 실천이에요.","세아가 잘못 말했어요."],"asset":{"type":"passage","lines":["야영장 화로와 자동차에서도 연소가 일어나 이산화 탄소가 생겨요.","이산화 탄소가 많아지면 숲과 바다의 생태계가 피해를 입어요.","우리 야영장의 약속 — 가까운 곳은 걸어서, 장작은 필요한 만큼만!"],"title":"별빛반 일지 ⑦ 야영장 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#15','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C13',2,'sa','auto','별빛반 일지 ⑧처럼 배기가스 속 이산화 탄소만 따로 모으는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"SC6-2-u2-C13","difficulty":2,"kind":"sa","stem":"별빛반 일지 ⑧처럼 배기가스 속 이산화 탄소만 따로 모으는 것을 두 글자로 쓰세요.","answer":["포집"],"explanation":["잡아 모아요.","□집이에요.","포집이에요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"},"mis":"SC6-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#16','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C2',2,'error','auto','섞기 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X04']::text[],false,'{"seq":16,"concept":"SC6-2-u2-C2","difficulty":2,"kind":"error","stem":"섞기 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「밀가루 쪽 고무풍선이 부풀었어.」","correct":true,"mis_target":"SC6-2-u2-X04"},{"t":"현서 — 「탄산수소 나트륨 쪽에 기포가 생겼어.」","mis":"SC6-2-u2-X04"},{"t":"민재 — 「밀가루는 가라앉았어.」","mis":"SC6-2-u2-X04"}],"explanation":["부푼 쪽을 떠올려요.","탄산수소 나트륨이에요.","지아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#17','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C7',3,'error','auto','별빛반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X16','SC6-2-u2-X15']::text[],false,'{"seq":17,"concept":"SC6-2-u2-C7","difficulty":3,"kind":"error","stem":"별빛반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"강우 — 「작은 통 안의 산소가 완전히 바닥나서 꺼졌어.」","correct":true,"mis_target":"SC6-2-u2-X16"},{"t":"세빈 — 「산소가 남았어도 충분하지 않으면 꺼져.」","mis":"SC6-2-u2-X16"},{"t":"하윤 — 「큰 통에 공기가 더 많아 더 오래 탔어.」","mis":"SC6-2-u2-X15"}],"explanation":["측정 결과를 떠올려요.","산소가 남아 있었어요.","강우가 잘못 말했어요."],"asset":{"type":"passage","lines":["양초 두 개에 불을 붙이고 크기가 다른 투명한 통으로 동시에 덮었다.","작은 통의 촛불이 먼저 꺼지고, 큰 통의 촛불이 나중에 꺼졌다.","선생님이 측정기로 재어 보니 꺼진 뒤에도 두 통 안에 산소가 남아 있었다."],"title":"별빛반 일지 ④ 통 크기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#18','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C8',3,'error','auto','발화점을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X18','SC6-2-u2-X17']::text[],false,'{"seq":18,"concept":"SC6-2-u2-C8","difficulty":3,"kind":"error","stem":"발화점을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「불을 직접 대지 않으면 물질은 절대 타지 않아.」","correct":true,"mis_target":"SC6-2-u2-X18"},{"t":"은솔 — 「온도를 발화점 이상으로 높이면 타.」","mis":"SC6-2-u2-X18"},{"t":"지유 — 「발화점은 물질마다 달라.」","mis":"SC6-2-u2-X17"}],"explanation":["철판 실험을 떠올려요.","불을 대지 않았는데 붙었어요.","수호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#19','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C10',3,'error','auto','별빛반 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X22','SC6-2-u2-X16']::text[],false,'{"seq":19,"concept":"SC6-2-u2-C10","difficulty":3,"kind":"error","stem":"별빛반 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「서준 말이 맞아. 녹은 촛농도 다 양초니까.」","correct":true,"mis_target":"SC6-2-u2-X22"},{"t":"은찬 — 「양초는 타서 물과 이산화 탄소가 됐어.」","mis":"SC6-2-u2-X22"},{"t":"예솔 — 「하늘이처럼 산소가 다 없어진 건 아니야.」","mis":"SC6-2-u2-X16"}],"explanation":["녹은 것과 탄 것은 달라요.","탄 양초는 새 물질이 돼요.","다빈이 잘못 말했어요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#20','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C3',3,'error','auto','별빛반 일지 ⑥의 라온의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X06']::text[],false,'{"seq":20,"concept":"SC6-2-u2-C3","difficulty":3,"kind":"error","stem":"별빛반 일지 ⑥의 라온의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준이 — 「라온 말이 맞아, 소금이 안 보이니까.」","correct":true,"mis_target":"SC6-2-u2-X06"},{"t":"하람 — 「짠맛이 나니 소금의 성질은 그대로야.」","mis":"SC6-2-u2-X06"},{"t":"서윤 — 「물을 증발시키면 소금이 남아.」","mis":"SC6-2-u2-X06"}],"explanation":["보이지 않아도 남아요.","짠맛이 근거예요.","준이가 잘못 말했어요."],"asset":{"type":"passage","lines":["하늘 — 「뚜껑 속 산소가 하나도 남지 않아서 불이 꺼진 거야.」","서준 — 「양초는 크기만 작아졌을 뿐 그대로 양초야.」","라온 — 「소금물 속 소금은 안 보이니 성질이 변한 거야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"별빛반 일지 ⑥ 텐트 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#21','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C6',3,'error','auto','연소의 조건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X14']::text[],false,'{"seq":21,"concept":"SC6-2-u2-C6","difficulty":3,"kind":"error","stem":"연소의 조건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「이산화 탄소가 있어야 물질이 타.」","correct":true,"mis_target":"SC6-2-u2-X14"},{"t":"라율 — 「산소가 있어야 물질이 타.」","mis":"SC6-2-u2-X14"},{"t":"우진 — 「발화점 이상의 온도가 되어야 타.」","mis":"SC6-2-u2-X14"}],"explanation":["연소에 필요한 기체예요.","이산화 탄소는 생기는 쪽이에요.","하온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#22','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C13',3,'error','auto','이산화 탄소 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X28','SC6-2-u2-X27']::text[],false,'{"seq":22,"concept":"SC6-2-u2-C13","difficulty":3,"kind":"error","stem":"이산화 탄소 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「재활용하면 되니까 배출을 줄일 필요는 없어.」","correct":true,"mis_target":"SC6-2-u2-X28"},{"t":"도윤 — 「줄이는 노력과 바꾸는 노력은 함께 해야 해.」","mis":"SC6-2-u2-X28"},{"t":"하리 — 「가까운 거리는 걸어 다니자.」","mis":"SC6-2-u2-X27"}],"explanation":["두 갈래 노력이에요.","재활용만으로는 부족해요.","은재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#23','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C11',4,'mc','auto','별빛반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-2-u2-X28','SC6-2-u2-X25','SC6-2-u2-X24']::text[],false,'{"seq":23,"concept":"SC6-2-u2-C11","difficulty":4,"kind":"mc","stem":"별빛반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"연소로 생긴 이산화 탄소는 생태계에 피해를 주므로 배출을 줄이는 노력과 모아서 다시 쓰는 노력을 함께 해야 한다","correct":true},{"t":"이산화 탄소는 모아서 쓸 수 있으니 마음껏 배출해도 된다","mis":"SC6-2-u2-X28"},{"t":"야영장 화로에서는 연소 생성물이 생기지 않는다","mis":"SC6-2-u2-X25"},{"t":"생태계 피해는 산소가 줄어서 생긴다","mis":"SC6-2-u2-X24"}],"explanation":["⑦은 피해와 줄이기예요.","⑧은 다시 쓰기예요.","둘을 함께 해요."],"asset":{"type":"passage","lines":["발전소에서는 배기가스 속 이산화 탄소만 따로 모은다.","모은 이산화 탄소는 이웃 비닐하우스 농장의 채소 재배에 쓴다.","일부는 드라이아이스로 만들어 아이스크림 가게로 보낸다."],"title":"별빛반 일지 ⑧ 돌아오는 길 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#24','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C6',4,'essay','teacher','조리용 종이 그릇에 물을 붓고 라면을 끓여도 종이 그릇에 불이 붙지 않는 까닭을 연소의 조건 세 가지를 하나씩 따져 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u2-C6","difficulty":4,"kind":"essay","stem":"조리용 종이 그릇에 물을 붓고 라면을 끓여도 종이 그릇에 불이 붙지 않는 까닭을 연소의 조건 세 가지를 하나씩 따져 설명하세요.","answer_guide":{"answer":"예: 연소가 일어나려면 탈 물질, 산소, 발화점 이상의 온도가 모두 있어야 한다. 종이 그릇은 탈 물질이고 주변에 산소도 있다. 그러나 그릇 안의 물이 열을 받아 가므로 종이의 온도가 발화점 이상으로 올라가지 않는다. 세 조건 가운데 발화점 이상의 온도가 없으므로 연소가 일어나지 않아 종이 그릇에 불이 붙지 않는다.","scoring_points":["연소의 조건 세 가지를 썼는가","탈 물질과 산소는 있다고 따졌는가","발화점 이상의 온도가 되지 않는다고 설명했는가"]},"explanation":["조건 셋을 써요.","하나씩 따져요.","빠진 조건을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u2_review_d#25','sci',6,2,'u2','','g6_2_sci_u2_review_d','unit_review','SC6-2-u2-C12',4,'essay','teacher','「물질의 연소」에서 배운 것을 바탕으로 우리 반 야영 때 지킬 「연소 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요. (안전 하나, 이산화 탄소 줄이기 하나를 꼭 넣으세요.)','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u2-C12","difficulty":4,"kind":"essay","stem":"「물질의 연소」에서 배운 것을 바탕으로 우리 반 야영 때 지킬 「연소 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요. (안전 하나, 이산화 탄소 줄이기 하나를 꼭 넣으세요.)","answer_guide":{"answer":"예: 첫째, 화로 근처에 탈 수 있는 물건을 두지 않는다 — 탈 물질이 가까이 있고 온도가 발화점 이상이 되면 불이 옮겨붙을 수 있기 때문이다. 둘째, 장작은 필요한 만큼만 태운다 — 연소하면 이산화 탄소가 생기고, 대기 중 이산화 탄소가 많아지면 생태계에 피해를 주기 때문이다. 셋째, 모닥불을 다 쓰면 뚜껑을 덮어 끄고 완전히 꺼졌는지 확인한다 — 산소가 충분하지 않으면 연소가 일어나지 않기 때문이다.","scoring_points":["약속 세 가지를 썼는가","안전 약속과 이산화 탄소 줄이기 약속을 넣었는가","각 약속을 연소의 조건·연소 생성물 같은 과학적 사실과 이었는가"]},"explanation":["약속을 셋 정해요.","안전과 줄이기를 넣어요.","과학적 사실과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
